  // Handle workspace selection
  // - Default: switch workspace in same window (in-window switching)
  // - With openInNewWindow=true: open in new window (or focus existing)
  const handleSelectWorkspace = useCallback(async (workspaceId: string, openInNewWindow = false) => {
    // If selecting current workspace, do nothing
    if (workspaceId === windowWorkspaceId) return

    if (openInNewWindow) {
      // Open (or focus) the window for the selected workspace
      window.electronAPI.openWorkspace(workspaceId)
    } else {
      // Switch workspace in current window
      // 1. Update the main process's window-workspace mapping
      await window.electronAPI.switchWorkspace(workspaceId)

      // 2. Update React state to trigger re-renders
      setWindowWorkspaceId(workspaceId)

      // 3. Clear selected session - the old session belongs to the previous workspace
      // and should not remain selected when switching to a new workspace.
      // This prevents showing stale session data from the wrong workspace.
      setSession({ selected: null })

      // 4. Clear pending permissions/credentials (not relevant to new workspace)
      setPendingPermissions(new Map())
      setPendingCredentials(new Map())

      // 5. Clear session options from previous workspace
      // (session IDs are unique UUIDs, but clearing prevents unbounded memory growth
      // and ensures no stale state from old workspace persists)
      setSessionOptions(new Map())

      // 6. Clear message drafts from previous workspace
      // (prevents memory growth on repeated workspace switches)
      sessionDraftsRef.current.clear()

      // 7. Reset sources and skills atoms to empty
      // (prevents stale data flash during workspace switch - AppShell will reload)
      store.set(sourcesAtom, [])
      store.set(skillsAtom, [])

      // 8. Clear session atoms BEFORE workspace switch
      // This prevents stale session data from the previous workspace being visible.
      store.set(sessionMetaMapAtom, new Map())
      store.set(sessionIdsAtom, [])

      // Note: NavigationContext detects the workspaceId change and handles
      // panel restoration from the stored workspace URL (or defaults to allSessions).
      // Sessions and theme will reload automatically due to windowWorkspaceId dependency
      // in useEffect hooks.
    }
  }, [windowWorkspaceId, setSession, store])

  // Handle workspace switch by slug (called by NavigationContext on popstate when ?ws= changes)
  const handleSwitchWorkspaceBySlug = useCallback((slug: string) => {
    const target = workspaces.find(w => w.slug === slug)
    if (target) {
      handleSelectWorkspace(target.id)
    }
  }, [workspaces, handleSelectWorkspace])

  // Handle workspace refresh (e.g., after icon upload)
  const handleRefreshWorkspaces = useCallback(() => {
    window.electronAPI.getWorkspaces().then(setWorkspaces)
  }, [])

  // Handle cancel during onboarding
  const handleOnboardingCancel = useCallback(() => {
    onboarding.handleCancel()
  }, [onboarding])

  // Build context value for AppShell component
  // This is memoized to prevent unnecessary re-renders
  // IMPORTANT: Must be before early returns to maintain consistent hook order
  const appShellContextValue = useMemo<AppShellContextType>(() => ({
    // Data
    // NOTE: sessions is NOT included - use sessionMetaMapAtom for listing
    // and useSession(id) hook for individual sessions. This prevents memory leaks.
    workspaces,
    activeWorkspaceId: windowWorkspaceId,
    activeWorkspaceSlug: windowWorkspaceSlug,
    llmConnections,
    workspaceDefaultLlmConnection,
    refreshLlmConnections,
    pendingPermissions,
    pendingCredentials,
    pendingQuestions,
    getDraft,
    getDraftAttachmentRefs,
    hydrateDraftAttachments,
    sessionOptions,
    // Session callbacks
    onCreateSession: handleCreateSession,
    onSendMessage: handleSendMessage,
    onRenameSession: handleRenameSession,
    onFlagSession: handleFlagSession,
    onUnflagSession: handleUnflagSession,
    onArchiveSession: handleArchiveSession,
    onUnarchiveSession: handleUnarchiveSession,
    onMarkSessionRead: handleMarkSessionRead,
    onMarkSessionUnread: handleMarkSessionUnread,
    onSetActiveViewingSession: handleSetActiveViewingSession,
    onSessionStatusChange: handleSessionStatusChange,
    onDeleteSession: handleDeleteSession,
    onRespondToPermission: handleRespondToPermission,
    onRespondToCredential: handleRespondToCredential,
    onRespondToAskUser: handleRespondToAskUser,
    // File/URL handlers
    onOpenFile: handleOpenFile,
    onOpenUrl: handleOpenUrl,
    // Workspace
    onSelectWorkspace: handleSelectWorkspace,
    onRefreshWorkspaces: handleRefreshWorkspaces,
    // App actions
    onOpenSettings: handleOpenSettings,
    onOpenKeyboardShortcuts: handleOpenKeyboardShortcuts,
    onOpenStoredUserPreferences: handleOpenStoredUserPreferences,
    onReset: handleReset,
    // Session options
    onSessionOptionsChange: handleSessionOptionsChange,
    onInputChange: handleInputChange,
    onAttachmentsChange: handleAttachmentsChange,
    // New chat (via deep link navigation)
    openNewChat,
  }), [
    // NOTE: sessions removed to prevent memory leaks - components use atoms instead
    workspaces,
    windowWorkspaceId,
    windowWorkspaceSlug,
    llmConnections,
    workspaceDefaultLlmConnection,
    refreshLlmConnections,
    pendingPermissions,
    pendingCredentials,
    pendingQuestions,
    getDraft,
    getDraftAttachmentRefs,
    hydrateDraftAttachments,
    sessionOptions,
    handleCreateSession,
    handleSendMessage,
    handleRenameSession,
    handleFlagSession,
    handleUnflagSession,
    handleArchiveSession,
    handleUnarchiveSession,
    handleMarkSessionRead,
    handleMarkSessionUnread,
    handleSetActiveViewingSession,
    handleSessionStatusChange,
    handleDeleteSession,
    handleRespondToPermission,
    handleRespondToCredential,
    handleRespondToAskUser,
    handleOpenFile,
    handleOpenUrl,
    handleSelectWorkspace,
    handleRefreshWorkspaces,
    handleOpenSettings,
    handleOpenKeyboardShortcuts,
    handleOpenStoredUserPreferences,
    handleReset,
    handleSessionOptionsChange,
    handleInputChange,
    handleAttachmentsChange,
    openNewChat,
  ])

  // Platform actions for @phaneris/ui components (overlays, etc.)
  // Memoized to prevent re-renders when these callbacks don't change
  // NOTE: Must be defined before early returns to maintain consistent hook order
  const platformActions = useMemo(() => ({
    onOpenFile: handleOpenFile,
    onOpenUrl: handleOpenUrl,
    // Bypass link interceptor — opens file directly in system editor.
    // Used by overlay header badges (when already viewing a file, "Open" should launch editor).
    onOpenFileExternal: linkInterceptor.openFileExternal,
    // Read file contents as UTF-8 string (used by datatable/spreadsheet/html-preview src fields)
    onReadFile: (path: string) => window.electronAPI.readFile(path),
    // Read file as data URL (used by image-preview blocks)
    onReadFileDataUrl: (path: string) => window.electronAPI.readFileDataUrl(path),
    // Read file as binary Uint8Array (used by PDF preview blocks)
    onReadFileBinary: (path: string) => window.electronAPI.readFileBinary(path),
    // Reveal a file in the system file manager (Finder on macOS, Explorer on Windows, etc.)
    onRevealInFinder: (path: string) => {
      window.electronAPI.showInFolder(path).catch(() => {})
    },
    // Platform-specific file manager name for UI labels
    fileManagerName: getFileManagerName(),
    // Hide/show macOS traffic lights when fullscreen overlays are open
    onSetTrafficLightsVisible: (visible: boolean) => {
      window.electronAPI.setTrafficLightsVisible(visible)
    },
  }), [handleOpenFile, handleOpenUrl, linkInterceptor.openFileExternal])

  // Loading state - show splash screen
  if (appState === 'loading') {
    return <SplashScreen isExiting={false} />
  }

  // Reauth state - session expired, need to re-login
  // ModalProvider + WindowCloseHandler ensures X button works on Windows
  if (appState === 'reauth') {
    return (
      <DismissibleLayerProvider>
        <ModalProvider>
          <WindowCloseHandler />
          <ReauthScreen
            onLogin={handleReauthLogin}
            onReset={handleReauthReset}
          />
          <ResetConfirmationDialog
            open={showResetDialog}
            onConfirm={executeReset}
            onCancel={() => setShowResetDialog(false)}
          />
        </ModalProvider>
      </DismissibleLayerProvider>
    )
  }

  // Onboarding state
  // ModalProvider + WindowCloseHandler ensures X button works on Windows
  // (without this, the close IPC message has no listener and window stays open)
  if (appState === 'onboarding') {
    return (
      <DismissibleLayerProvider>
        <ModalProvider>
          <WindowCloseHandler />
          <OnboardingWizard
            state={onboarding.state}
            onContinue={onboarding.handleContinue}
            onBack={onboarding.handleBack}
            onSelectProvider={onboarding.handleSelectProvider}
            onSkipSetup={onboarding.handleSkipSetup}
            onSelectApiSetupMethod={onboarding.handleSelectApiSetupMethod}
            onSubmitCredential={onboarding.handleSubmitCredential}
            onSubmitLocalModel={onboarding.handleSubmitLocalModel}
            onStartOAuth={onboarding.handleStartOAuth}
            onFinish={onboarding.handleFinish}
            isWaitingForCode={onboarding.isWaitingForCode}
            onSubmitAuthCode={onboarding.handleSubmitAuthCode}
            onSubmitPiOAuthCode={onboarding.handleSubmitPiOAuthCode}
            onCancelOAuth={onboarding.handleCancelOAuth}
            copilotDeviceCode={onboarding.copilotDeviceCode}
            onBrowseGitBash={onboarding.handleBrowseGitBash}
            onUseGitBashPath={onboarding.handleUseGitBashPath}
            onRecheckGitBash={onboarding.handleRecheckGitBash}
            onClearError={onboarding.handleClearError}
          />
        </ModalProvider>
      </DismissibleLayerProvider>
    )
  }

  // Workspace picker — thin client with no workspace selected
  if (appState === 'workspace-picker') {
    return (
      <DismissibleLayerProvider>
        <ModalProvider>
          <WindowCloseHandler />
          <WorkspacePicker
            onSelectWorkspace={async (id) => {
              await window.electronAPI.switchWorkspace(id)
              setWindowWorkspaceId(id)
              setAppState('ready')
            }}
          />
        </ModalProvider>
      </DismissibleLayerProvider>
    )
  }

  // Show splash until exit animation completes
  const showSplash = !splashHidden

  // Ready state - main app with splash overlay during data loading
  return (
    <PlatformProvider actions={platformActions}>
    <ShikiThemeProvider shikiTheme={shikiTheme}>
      <ActionRegistryProvider>
      <FocusProvider>
        <DismissibleLayerProvider>
        <ModalProvider>
        <TooltipProvider delayDuration={0}>
        <NavigationProvider
          workspaceId={windowWorkspaceId}
          workspaceSlug={windowWorkspaceSlug}
          onSwitchWorkspaceBySlug={handleSwitchWorkspaceBySlug}
          onCreateSession={handleCreateSession}
          onInputChange={handleInputChange}
          getDraft={getDraft}
          onAutoDeleteEmptySession={handleAutoDeleteEmptySession}
          isReady={appState === 'ready'}
          isSessionsReady={sessionsLoaded}
          remoteWorkspaceId={windowRemoteWorkspaceId}
        >
          {/* Handle window close requests (X button, Cmd+W) - close modal first if open */}
          <WindowCloseHandler />

          {/*
            The app's single in-app confirmation surface: renderer-local
            `confirmDialog()` prompts, plus the server-requested ones the main
            process relays down from the `client:confirmDialog` capability.
            Mounted here (not in main.tsx) so it sits inside `ModalProvider` and
            Cmd+W closes the dialog before the window.
          */}
          <ConfirmDialogHost />

          {/* Splash screen overlay - fades out when fully ready */}
          {showSplash && (
            <SplashScreen
              isExiting={splashExiting}
              onExitComplete={handleSplashExitComplete}
            />
          )}

          {/* Main UI - always rendered, splash fades away to reveal it */}
          <div
            className="h-full flex flex-col text-foreground"
            style={{ paddingTop: 'var(--topbar-height)' }}
          >
            {showTransportConnectionBanner && connectionState && (
              <TransportConnectionBanner
                state={connectionState}
                onRetry={handleReconnectTransport}
              />
            )}
            <div className="flex-1 min-h-0">
              {sessionLoadError ? (
                <SessionLoadErrorScreen
                  message={sessionLoadError}
                  onRetry={() => { void loadSessionsFromServer() }}
                />
              ) : (
                <AppShell
                  contextValue={appShellContextValue}
                  defaultLayout={[20, 32, 48]}
                  menuNewChatTrigger={menuNewChatTrigger}
                  isFocusedMode={isFocusedMode}
                />
              )}
            </div>
            <ResetConfirmationDialog
              open={showResetDialog}
              onConfirm={executeReset}
              onCancel={() => setShowResetDialog(false)}
            />
          </div>

          {/* File preview overlay — rendered by the link interceptor when a previewable file is clicked */}
          {linkInterceptor.previewState && (
            <FilePreviewRenderer
              state={linkInterceptor.previewState}
              onClose={linkInterceptor.closePreview}
              isDark={isDark}
              onOpenFile={handleOpenFile}
              onOpenUrl={handleOpenUrl}
            />
          )}

          {/* Chat pop-outs (message / response / turn details) — read-only documents */}
          <MarkdownPopoutOverlay isDark={isDark} onOpenUrl={handleOpenUrl} onOpenFile={handleOpenFile} />

          {/* Documentation overlay — the target of every in-app help link */}
          <DocsOverlay />
          <RtkUpdatePrompt workspaceId={windowWorkspaceId} />
        </NavigationProvider>
        </TooltipProvider>
        </ModalProvider>
        </DismissibleLayerProvider>
      </FocusProvider>
      </ActionRegistryProvider>
    </ShikiThemeProvider>
    </PlatformProvider>
  )
}

/**
 * Component that handles window close requests.
 * Must be inside ModalProvider to access the modal registry.
 */
function WindowCloseHandler() {
  useWindowCloseHandler()
  return null
}

/** Global fallback uses exactly the same renderer and actions as Workbench. */
function FilePreviewRenderer({ state, onClose, isDark, onOpenFile, onOpenUrl }: {
  state: FilePreviewState
  onClose: () => void
  isDark: boolean
  onOpenFile: (path: string) => void
  onOpenUrl: (url: string) => void
}) {
  const { t } = useTranslation()
  return (
    <PreviewOverlay isOpen onClose={onClose} filePath={state.filePath} theme={isDark ? 'dark' : 'light'}
      typeBadge={{ icon: FileText, label: t('filePreview.preview'), variant: 'default' }}>
      <FilePreviewContent {...state} onFileClick={onOpenFile} onOpenUrl={onOpenUrl} />
    </PreviewOverlay>
  )
}

import * as React from 'react'
import { cn } from '@/lib/utils'
import type { ComponentEntry } from './registry'
import { TooltipProvider } from '@phaneris/ui'

interface ComponentPreviewProps {
  component: ComponentEntry
  props: Record<string, unknown>
}

const MIN_WIDTH = 100
const MIN_HEIGHT = 100
const DEFAULT_WIDTH = 800
const DEFAULT_HEIGHT = 600
const STORAGE_KEY = 'playground-preview-size'

function loadSavedSize(): { width: number; height: number } {
  try {
    const saved = localStorage.getItem(STORAGE_KEY)
    if (saved) {
      const parsed = JSON.parse(saved)
      if (typeof parsed.width === 'number' && typeof parsed.height === 'number') {
        return {
          width: Math.max(MIN_WIDTH, parsed.width),
          height: Math.max(MIN_HEIGHT, parsed.height),
        }
      }
    }
  } catch {
    // Ignore parse errors
  }
  return { width: DEFAULT_WIDTH, height: DEFAULT_HEIGHT }
}

export function ComponentPreview({ component, props }: ComponentPreviewProps) {
  const [size, setSize] = React.useState(loadSavedSize)
  const containerRef = React.useRef<HTMLDivElement>(null)
  const isDraggingRef = React.useRef<'right' | 'bottom' | 'corner' | null>(null)
  const startPosRef = React.useRef({ x: 0, y: 0 })
  const startSizeRef = React.useRef({ width: 0, height: 0 })

  // Merge default props, mock data, and current props
  const mergedProps = React.useMemo(() => {
    const defaults: Record<string, unknown> = {}
    for (const prop of component.props) {
      defaults[prop.name] = prop.defaultValue
    }
    const mockData = component.mockData?.() ?? {}
    return { ...defaults, ...mockData, ...props }
  }, [component, props])

  // Render with optional wrapper
  const Component = component.component
  const Wrapper = component.wrapper ?? React.Fragment

  const handleMouseDown = React.useCallback((e: React.MouseEvent, direction: 'right' | 'bottom' | 'corner') => {
    e.preventDefault()
    isDraggingRef.current = direction
    startPosRef.current = { x: e.clientX, y: e.clientY }
    startSizeRef.current = { ...size }
  }, [size])

  React.useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDraggingRef.current) return

      const deltaX = e.clientX - startPosRef.current.x
      const deltaY = e.clientY - startPosRef.current.y

      setSize(prev => {
        let newWidth = prev.width
        let newHeight = prev.height

        if (isDraggingRef.current === 'right' || isDraggingRef.current === 'corner') {
          newWidth = Math.max(MIN_WIDTH, startSizeRef.current.width + deltaX)
        }
        if (isDraggingRef.current === 'bottom' || isDraggingRef.current === 'corner') {
          newHeight = Math.max(MIN_HEIGHT, startSizeRef.current.height + deltaY)
        }

        return { width: newWidth, height: newHeight }
      })
    }

    const handleMouseUp = () => {
      if (isDraggingRef.current) {
        // Save size to localStorage when drag ends
        setSize(currentSize => {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(currentSize))
          return currentSize
        })
      }
      isDraggingRef.current = null
    }

    document.addEventListener('mousemove', handleMouseMove)
    document.addEventListener('mouseup', handleMouseUp)

    return () => {
      document.removeEventListener('mousemove', handleMouseMove)
      document.removeEventListener('mouseup', handleMouseUp)
    }
  }, [])

  const previewOverflowClass = component.previewOverflow
    ? (component.previewOverflow === 'visible' ? 'overflow-visible' : component.previewOverflow === 'hidden' ? 'overflow-hidden' : 'overflow-auto')
    : (component.layout === 'full' ? 'overflow-hidden' : 'overflow-auto')

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      {/* Header */}
      <div className="border-b border-border px-4 pt-3 pb-3">
        <h2 className="text-lg font-semibold text-foreground font-sans">
          {component.name}
        </h2>
        <div className="mt-1 flex flex-wrap items-center gap-4 text-sm text-muted-foreground">
          <p>{component.description}</p>
          <div className="flex items-center gap-2">
            <span className="text-xs font-mono">
              {Math.round(size.width)} × {Math.round(size.height)}
            </span>
            <button
              onClick={() => {
                setSize({ width: DEFAULT_WIDTH, height: DEFAULT_HEIGHT })
                localStorage.removeItem(STORAGE_KEY)
              }}
              className="px-2 py-1 rounded text-xs text-muted-foreground hover:text-foreground hover:bg-foreground/5 transition-colors"
            >
              Reset
            </button>
          </div>
        </div>
      </div>

      {/* Preview area */}
      <div
        className={cn(
          'flex-1 overflow-auto p-4 flex',
          component.layout === 'top' ? 'items-start justify-center' : 'items-center justify-center'
        )}
      >
        {/* Resizable container */}
        <div
          ref={containerRef}
          className="relative"
          style={{ width: size.width, height: size.height }}
        >
          {/* Component preview box */}
          <div
            className={cn(
              'w-full h-full rounded-lg border border-border',
              previewOverflowClass,
              component.layout === 'centered' || !component.layout ? 'flex items-center justify-center' : '',
              'bg-background'
            )}
          >
            <TooltipProvider>
              <Wrapper>
                <Component {...mergedProps} />
              </Wrapper>
            </TooltipProvider>
          </div>

          {/* Right resize handle */}
          <div
            onMouseDown={(e) => handleMouseDown(e, 'right')}
            className="absolute top-0 -right-1 w-2 h-full cursor-ew-resize hover:bg-foreground/20 active:bg-foreground/30 transition-colors"
          />

          {/* Bottom resize handle */}
          <div
            onMouseDown={(e) => handleMouseDown(e, 'bottom')}
            className="absolute -bottom-1 left-0 h-2 w-full cursor-ns-resize hover:bg-foreground/20 active:bg-foreground/30 transition-colors"
          />

          {/* Corner resize handle */}
          <div
            onMouseDown={(e) => handleMouseDown(e, 'corner')}
            className="absolute -bottom-1 -right-1 w-3 h-3 cursor-nwse-resize hover:bg-foreground/30 active:bg-foreground/40 transition-colors rounded-br"
          />
        </div>
      </div>
    </div>
  )
}

import * as React from 'react'
import { Accessibility, Sparkles, Monitor } from 'lucide-react'
import { cn } from '@/lib/utils'

/**
 * Explicit motion preference switch for the Playground.
 *
 * The Playground is the acceptance harness for component interaction, so it has
 * to be able to show the reduced-motion behaviour of a component on a machine
 * whose OS preference is not set — otherwise "check it under reduce" requires
 * changing system settings and a restart.
 *
 * `system` matches production hosts (`MotionConfig reducedMotion="user"`).
 * `reduced`/`normal` force the branch so both paths can be compared side by
 * side. The forced value is mirrored onto `<html data-reduce-motion>` so CSS-level
 * animation and transitions follow the same switch as the Motion tree — the OS
 * media query alone cannot see this control.
 */

export type PlaygroundMotionPreference = 'system' | 'normal' | 'reduced'

const STORAGE_KEY = 'playground-motion-preference'

const PREFERENCES: { value: PlaygroundMotionPreference; icon: typeof Sparkles; label: string }[] = [
  { value: 'system', icon: Monitor, label: 'System' },
  { value: 'normal', icon: Sparkles, label: 'Normal' },
  { value: 'reduced', icon: Accessibility, label: 'Reduced' },
]

/** MotionConfig's own vocabulary for the same three states. */
export const MOTION_CONFIG_BY_PREFERENCE = {
  system: 'user',
  normal: 'never',
  reduced: 'always',
} as const satisfies Record<PlaygroundMotionPreference, 'user' | 'never' | 'always'>

function loadPreference(): PlaygroundMotionPreference {
  try {
    const saved = localStorage.getItem(STORAGE_KEY)
    if (saved === 'system' || saved === 'normal' || saved === 'reduced') return saved
  } catch {
    // Ignore storage errors — fall through to the system default.
  }
  return 'system'
}

export function usePlaygroundMotionPreference() {
  const [preference, setPreference] = React.useState<PlaygroundMotionPreference>(loadPreference)

  React.useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, preference)
    } catch {
      // Ignore storage errors
    }
  }, [preference])

  // Forced reduce has to reach plain CSS too: media queries cannot see this
  // control, so the reduced ruleset is also keyed on the attribute.
  React.useEffect(() => {
    const root = document.documentElement
    if (preference === 'reduced') {
      root.setAttribute('data-reduce-motion', 'true')
    } else {
      root.removeAttribute('data-reduce-motion')
    }
    return () => root.removeAttribute('data-reduce-motion')
  }, [preference])

  return [preference, setPreference] as const
}

interface MotionToggleProps {
  preference: PlaygroundMotionPreference
  onPreferenceChange: (preference: PlaygroundMotionPreference) => void
}

export function MotionToggle({ preference, onPreferenceChange }: MotionToggleProps) {
  return (
    <div
      className="flex items-center gap-1 p-1 rounded-lg bg-foreground/5"
      role="radiogroup"
      aria-label="Motion preference"
    >
      {PREFERENCES.map(({ value, icon: Icon, label }) => (
        <button
          key={value}
          type="button"
          role="radio"
          aria-checked={preference === value}
          onClick={() => onPreferenceChange(value)}
          className={cn(
            'flex items-center gap-1.5 px-2.5 py-1.5 rounded-md text-xs font-medium transition-colors',
            preference === value
              ? 'bg-background text-foreground shadow-sm'
              : 'text-muted-foreground hover:text-foreground'
          )}
          title={`${label} motion`}
        >
          <Icon className="h-3.5 w-3.5" />
          <span className="hidden sm:inline">{label}</span>
        </button>
      ))}
    </div>
  )
}

import * as React from 'react'
import { PanelRight } from 'lucide-react'
import { MotionConfig } from 'motion/react'
import { PhanerisSymbol } from '@/components/icons/PhanerisSymbol'
import { cn } from '@/lib/utils'
import { useTheme } from '@/context/ThemeContext'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import type { ThemeSummary } from '@config/theme'
import { ThemeToggle } from './ThemeToggle'
import { MotionToggle, usePlaygroundMotionPreference, MOTION_CONFIG_BY_PREFERENCE } from './MotionToggle'
import { Sidebar } from './Sidebar'
import { ComponentPreview } from './ComponentPreview'
import { VariantsSidebar } from './VariantsSidebar'
import { getCategories, getComponentById, type ComponentVariant } from './registry'

const SELECTED_STORAGE_KEY = 'playground-selected-component'
const VARIANTS_SIDEBAR_KEY = 'playground-variants-sidebar-open'

const FALLBACK_THEME_OPTIONS = [
  { value: 'default', label: 'Twilight' },
] as const

export function PlaygroundApp() {
  const categories = React.useMemo(() => getCategories(), [])
  const {
    workspaceColorTheme,
    effectiveColorTheme,
    setColorTheme,
    setWorkspaceColorTheme,
    setPreviewColorTheme,
    activeWorkspaceId,
  } = useTheme()
  const [presetThemes, setPresetThemes] = React.useState<ThemeSummary[]>([])
  const [selectedId, setSelectedId] = React.useState<string | null>(() => {
    // Try to restore from localStorage
    try {
      const stored = localStorage.getItem(SELECTED_STORAGE_KEY)
      if (stored) {
        // Verify the component still exists
        const component = getComponentById(stored)
        if (component) {
          return stored
        }
      }
    } catch {
      // Ignore parse errors
    }
    return null
  })
  const [props, setProps] = React.useState<Record<string, unknown>>({})
  const [selectedVariant, setSelectedVariant] = React.useState<string | null>(null)
  const [variantsSidebarOpen, setVariantsSidebarOpen] = React.useState(() => {
    try {
      const stored = localStorage.getItem(VARIANTS_SIDEBAR_KEY)
      return stored !== 'false' // Default to open
    } catch {
      return true
    }
  })

  React.useEffect(() => {
    const loadThemes = async () => {
      if (!window.electronAPI?.loadPresetThemes) {
        console.warn('[Playground] electronAPI.loadPresetThemes is unavailable; using fallback theme options')
        setPresetThemes([])
        return
      }

      try {
        const themes = await window.electronAPI.loadPresetThemes()
        setPresetThemes(themes)
      } catch (error) {
        console.error('[Playground] Failed to load preset themes, using fallback options:', error)
        setPresetThemes([])
      }
    }

    void loadThemes()
    const cleanup = window.electronAPI?.onUserThemesChanged?.(() => {
      void loadThemes()
    })
    return cleanup
  }, [])

  const themeOptions = React.useMemo(() => {
    const loadedOptions = presetThemes.map(theme => ({
      value: theme.id,
      label: theme.name || theme.id,
    }))

    const merged = new Map<string, string>()

    for (const option of FALLBACK_THEME_OPTIONS) {
      merged.set(option.value, option.label)
    }

    for (const option of loadedOptions) {
      merged.set(option.value, option.label)
    }

    return Array.from(merged.entries()).map(([value, label]) => ({ value, label }))
  }, [presetThemes])

  React.useEffect(() => {
    return () => {
      setPreviewColorTheme(null)
    }
  }, [setPreviewColorTheme])

  // Persist selected component to localStorage
  React.useEffect(() => {
    try {
      if (selectedId) {
        localStorage.setItem(SELECTED_STORAGE_KEY, selectedId)
      } else {
        localStorage.removeItem(SELECTED_STORAGE_KEY)
      }
    } catch {
      // Ignore storage errors
    }
  }, [selectedId])

  // Persist variants sidebar state
  React.useEffect(() => {
    try {
      localStorage.setItem(VARIANTS_SIDEBAR_KEY, String(variantsSidebarOpen))
    } catch {
      // Ignore storage errors
    }
  }, [variantsSidebarOpen])

  const selectedComponent = selectedId ? (getComponentById(selectedId) ?? null) : null

  // Reset props when component changes
  React.useEffect(() => {
    if (selectedComponent) {
      const defaults: Record<string, unknown> = {}
      for (const prop of selectedComponent.props) {
        defaults[prop.name] = prop.defaultValue
      }
      setProps(defaults)
      setSelectedVariant(null)
    }
  }, [selectedComponent])

  const handleVariantSelect = (variant: ComponentVariant) => {
    if (selectedComponent) {
      // Start with defaults, then apply variant props
      const defaults: Record<string, unknown> = {}
      for (const prop of selectedComponent.props) {
        defaults[prop.name] = prop.defaultValue
      }
      setProps({ ...defaults, ...variant.props })
      setSelectedVariant(variant.name)
    }
  }

  const handlePropsChange = (newProps: Record<string, unknown>) => {
    setProps(newProps)
    // Clear variant selection when props are manually changed
    setSelectedVariant(null)
  }

  const handleThemeChange = (nextTheme: string) => {
    const normalized = nextTheme === 'default' ? null : nextTheme

    // Apply immediately regardless of persistence layer
    setPreviewColorTheme(normalized)

    // Respect current precedence: if a workspace override is active, update that;
    // otherwise update app default theme.
    if (workspaceColorTheme !== null && activeWorkspaceId) {
      setWorkspaceColorTheme(normalized)
      return
    }

    setColorTheme(nextTheme)
  }

  const [motionPreference, setMotionPreference] = usePlaygroundMotionPreference()

  return (
    // Parity with every production host (apps/electron, apps/webui, viewer):
    // the harness must exercise the same reduced-motion contract as the app,
    // including the ability to force either branch on a machine whose OS
    // preference is unset.
    <MotionConfig reducedMotion={MOTION_CONFIG_BY_PREFERENCE[motionPreference]}>
      <div className="h-screen flex flex-col bg-background text-foreground">
        {/* Header */}
        <header className="h-12 shrink-0 flex items-center justify-between px-4 border-b border-border bg-background">
          <div className="flex items-center gap-3">
            <PhanerisSymbol className="h-5 w-5" />
            <h1 className="font-semibold text-foreground font-sans">
              Design System Playground
            </h1>
          </div>
          <div className="flex items-center gap-2">
            <MotionToggle preference={motionPreference} onPreferenceChange={setMotionPreference} />
            <ThemeToggle />
            <Select value={effectiveColorTheme ?? 'default'} onValueChange={handleThemeChange}>
              <SelectTrigger className="h-8 w-[170px] bg-foreground/5 border-border/50 text-xs">
                <SelectValue placeholder="Theme" />
              </SelectTrigger>
              <SelectContent>
                {themeOptions.map((option) => (
                  <SelectItem key={option.value} value={option.value}>
                    {option.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <button
              onClick={() => setVariantsSidebarOpen(!variantsSidebarOpen)}
              className={cn(
                'p-2 rounded-md transition-colors',
                variantsSidebarOpen
                  ? 'bg-foreground/10 text-foreground'
                  : 'text-muted-foreground hover:text-foreground hover:bg-foreground/5'
              )}
              title={variantsSidebarOpen ? 'Hide variants' : 'Show variants'}
            >
              <PanelRight className="w-4 h-4" />
            </button>
          </div>
        </header>

        {/* Main content */}
        <div className="flex-1 flex overflow-hidden">
          {/* Left Sidebar - Component list */}
          <Sidebar
            categories={categories}
            selectedId={selectedId}
            onSelect={setSelectedId}
          />

          {/* Content area - full height preview */}
          {selectedComponent ? (
            <ComponentPreview
              component={selectedComponent}
              props={props}
            />
          ) : (
            <div className="flex-1 flex items-center justify-center text-muted-foreground">
              Select a component from the sidebar
            </div>
          )}

          {/* Right Sidebar - Variants & Props */}
          <VariantsSidebar
            component={selectedComponent}
            selectedVariant={selectedVariant}
            onVariantSelect={handleVariantSelect}
            props={props}
            onPropsChange={handlePropsChange}
            isOpen={variantsSidebarOpen}
          />
        </div>
      </div>
    </MotionConfig>
  )
}

import * as React from 'react'
import { ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { CategoryGroup } from './registry'

interface SidebarProps {
  categories: CategoryGroup[]
  selectedId: string | null
  onSelect: (id: string) => void
}

const STORAGE_KEY = 'playground-expanded-categories'

export function Sidebar({ categories, selectedId, onSelect }: SidebarProps) {
  const [expandedCategories, setExpandedCategories] = React.useState<Set<string>>(() => {
    // Try to restore from localStorage, otherwise collapse all by default
    try {
      const stored = localStorage.getItem(STORAGE_KEY)
      if (stored) {
        const parsed = JSON.parse(stored) as string[]
        return new Set(parsed)
      }
    } catch {
      // Ignore parse errors
    }
    return new Set<string>()
  })

  // Persist expanded categories to localStorage
  React.useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify([...expandedCategories]))
    } catch {
      // Ignore storage errors
    }
  }, [expandedCategories])

  const toggleCategory = (name: string) => {
    setExpandedCategories(prev => {
      const next = new Set(prev)
      if (next.has(name)) {
        next.delete(name)
      } else {
        next.add(name)
      }
      return next
    })
  }

  return (
    <nav className="w-56 shrink-0 border-r border-border bg-background overflow-y-auto">
      <div className="p-3 space-y-1">
        {categories.map(category => {
          const isExpanded = expandedCategories.has(category.name)

          return (
            <div key={category.name}>
              {/* Category header */}
              <button
                onClick={() => toggleCategory(category.name)}
                className="w-full flex items-center gap-1.5 px-2 py-1.5 text-xs font-semibold text-muted-foreground uppercase tracking-wider hover:text-foreground transition-colors"
              >
                <ChevronRight
                  className={cn(
                    'h-3.5 w-3.5 transition-transform',
                    isExpanded && 'rotate-90'
                  )}
                />
                {category.name}
                <span className="ml-auto text-[10px] font-normal opacity-60">
                  {category.components.length}
                </span>
              </button>

              {/* Component list */}
              {isExpanded && (
                <div className="ml-2 space-y-0.5">
                  {category.components.map(component => (
                    <button
                      key={component.id}
                      onClick={() => onSelect(component.id)}
                      className={cn(
                        'w-full text-left px-3 py-1.5 rounded-md text-sm transition-colors',
                        selectedId === component.id
                          ? 'bg-foreground/10 text-foreground font-medium'
                          : 'text-muted-foreground hover:bg-foreground/5 hover:text-foreground'
                      )}
                    >
                      {component.name}
                    </button>
                  ))}
                </div>
              )}
            </div>
          )
        })}
      </div>
    </nav>
  )
}

/**
 * PairingCodeDialogPreview
 *
 * Renders the real PairingCodeDialog with `open` wired to local state so the
 * user can dismiss it (ESC / outside click / close button) just like in the
 * real app. The dialog auto-reopens whenever any display prop changes so that
 * switching variants in the playground sidebar brings it back without needing
 * a separate "reopen" button. Computes `expiresAt` from an
 * `expiresInSeconds` prop so the variant sidebar can show "Expired" (0) or
 * a specific countdown state.
 */

import * as React from 'react'
import { PairingCodeDialog } from '../../../components/messaging/PairingCodeDialog'

export interface PairingCodeDialogPreviewProps {
  platform: 'telegram' | 'whatsapp'
  code: string
  expiresInSeconds: number
  botUsername: string
  error: string
}

export function PairingCodeDialogPreview({
  platform,
  code,
  expiresInSeconds,
  botUsername,
  error,
}: PairingCodeDialogPreviewProps) {
  const [open, setOpen] = React.useState(true)

  // Reopen on any prop change so switching variants in the sidebar brings
  // the dialog back up after the user has dismissed it.
  React.useEffect(() => {
    setOpen(true)
  }, [platform, code, expiresInSeconds, botUsername, error])

  // Recompute expiresAt when the countdown prop changes so the timer restarts.
  const expiresAt = React.useMemo(() => {
    if (expiresInSeconds < 0) return null
    return Date.now() + expiresInSeconds * 1000
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [expiresInSeconds])

  return (
    <>
      <PairingCodeDialog
        open={open}
        onOpenChange={setOpen}
        platform={platform}
        code={code || null}
        expiresAt={expiresAt}
        botUsername={botUsername || undefined}
        error={error || undefined}
      />
      {!open && (
        <div className="p-6 text-sm text-foreground/60">
          Dialog dismissed.{' '}
          <button
            type="button"
            className="underline hover:text-foreground"
            onClick={() => setOpen(true)}
          >
            Reopen
          </button>
        </div>
      )}
    </>
  )
}

