/** Known code file extensions - used to pick code file icon vs generic file icon */
const CODE_EXTENSIONS = new Set([
  'ts', 'tsx', 'js', 'jsx', 'mjs', 'cjs',
  'py', 'rs', 'go', 'java', 'rb', 'swift', 'kt',
  'c', 'cpp', 'h', 'hpp', 'cs',
  'css', 'scss', 'less', 'html', 'vue', 'svelte',
  'json', 'yaml', 'yml', 'toml', 'xml',
  'sh', 'bash', 'zsh', 'fish',
  'md', 'mdx',
  'sql', 'graphql', 'proto',
])

function isCodeFile(name: string): boolean {
  const ext = name.split('.').pop()?.toLowerCase()
  return ext ? CODE_EXTENSIONS.has(ext) : false
}

function renderBadgeHTML(
  type: MentionItemType,
  label: string,
  skill?: LoadedSkill,
  source?: LoadedSource,
  workspaceId?: string,
  tooltip?: string
): string {
  // Try to get cached icon first
  let iconHtml = ''
  let cachedIconUrl: string | null = null

  if (type === 'skill' && skill && workspaceId) {
    cachedIconUrl = getSkillIconSync(workspaceId, skill.slug)
  } else if (type === 'source' && source && workspaceId) {
    cachedIconUrl = getSourceIconSync(workspaceId, source.config.slug)
  }

  if (cachedIconUrl) {
    // Check for emoji marker - render as text, not image
    if (cachedIconUrl.startsWith(EMOJI_ICON_PREFIX)) {
      const emoji = cachedIconUrl.slice(EMOJI_ICON_PREFIX.length)
      iconHtml = `<span class="h-[12px] w-[12px] flex items-center justify-center text-[10px] leading-none shrink-0">${emoji}</span>`
    } else {
      // Use cached icon as img (data URL or external URL)
      iconHtml = `<img src="${cachedIconUrl}" class="h-[12px] w-[12px] rounded-[2px] shrink-0" alt="" />`
    }
  } else {
    // Fall back to generic SVG icon based on type
    if (type === 'skill') {
      iconHtml = `<span class="h-[12px] w-[12px] rounded-[2px] bg-foreground/5 flex items-center justify-center text-foreground/50 shrink-0">${SKILL_ICON_SVG}</span>`
    } else if (type === 'source') {
      iconHtml = `<span class="h-[12px] w-[12px] rounded-[2px] bg-foreground/5 flex items-center justify-center text-foreground/50 shrink-0">${SOURCE_ICON_SVG}</span>`
    } else if (type === 'file') {
      // Pick code file or generic file icon based on extension (no container, icon carries its own classes)
      iconHtml = isCodeFile(label) ? CODE_FILE_ICON_SVG : FILE_ICON_SVG
    } else if (type === 'folder') {
      iconHtml = FOLDER_ICON_SVG
    }
  }

  const escapedLabel = label.replace(/</g, '&lt;').replace(/>/g, '&gt;')
  const titleAttr = tooltip ? ` title="${tooltip.replace(/"/g, '&quot;')}"` : ''

  // Line height is increased when badges are present (see hasMentions in component)
  // Use transform for upward shift - doesn't affect layout flow (works even at start of line)
  return `<span contenteditable="false" data-mention="true"${titleAttr} class="mention-badge inline-flex items-center gap-1 h-[22px] px-1.5 mx-1 rounded-[5px] bg-background shadow-minimal text-[12px] text-foreground select-none [&_*]:selection:bg-transparent selection:bg-transparent" style="vertical-align: middle; transform: translateY(-1px)">${iconHtml}<span class="truncate max-w-[200px]">${escapedLabel}</span></span>`
}

// ============================================================================
// Helper: Extract plain text from contenteditable
// ============================================================================

function getTextFromElement(element: HTMLElement): string {
  let text = ''

  // isTopLevel: true for direct children of the contenteditable root
  function processNode(node: Node, isTopLevel: boolean = false) {
    if (node.nodeType === Node.TEXT_NODE) {
      // Filter out zero-width spaces (used for contenteditable cursor fix)
      text += (node.textContent || '').replace(/\u200B/g, '')
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      const el = node as HTMLElement

      // Skip mention badges - they shouldn't contribute additional text
      if (el.getAttribute('data-mention') === 'true') {
        // Get the mention text from data attribute
        const mentionText = el.getAttribute('data-mention-text')
        if (mentionText) {
          text += mentionText
        }
        return // Don't process children
      }

      // Handle line breaks
      if (el.tagName === 'BR') {
        text += '\n'
      } else if (el.tagName === 'DIV' && text.length > 0 && !text.endsWith('\n')) {
        // DIVs in contenteditable normally represent line breaks.
        // HOWEVER: When typing before a badge at position 0, browsers wrap the
        // typed character in a <div>, creating: <div>typed</div><span badge>
        // This is NOT a user-intended line break - it's browser behavior.
        // We detect this by checking if a top-level DIV is immediately followed
        // by a mention badge sibling. If so, skip adding the newline.
        if (isTopLevel) {
          // Check if this DIV is followed by a mention badge at top level.
          // Skip over ZWS-only text nodes - browser may preserve them between
          // the DIV wrapper and the badge span.
          let nextSibling: Node | null = el.nextSibling
          while (
            nextSibling?.nodeType === Node.TEXT_NODE &&
            nextSibling.textContent?.replace(/\u200B/g, '') === ''
          ) {
            nextSibling = nextSibling.nextSibling
          }
          const isBrowserWrapper =
            (nextSibling as HTMLElement)?.getAttribute?.('data-mention') === 'true'
          if (!isBrowserWrapper) {
            text += '\n'
          }
          // If it IS followed by a badge, don't add newline - just process children
        } else {
          // Nested DIVs are always treated as line breaks
          text += '\n'
        }
      }

      // Process children (no longer top-level)
      Array.from(el.childNodes).forEach(child => {
        processNode(child, false)
      })
    }
  }

  // Process direct children as top-level nodes
  Array.from(element.childNodes).forEach(child => {
    processNode(child, true)
  })

  return text
}

// ============================================================================
// Helper: Get cursor position in text model
// ============================================================================

function getCursorPosition(element: HTMLElement, fallback: number = 0): number {
  const selection = window.getSelection()
  if (!selection || selection.rangeCount === 0) return fallback

  const range = selection.getRangeAt(0)

  // Create a range from start of element to cursor
  const preRange = document.createRange()
  preRange.selectNodeContents(element)
  preRange.setEnd(range.startContainer, range.startOffset)

  // Get text length before cursor, excluding badge content
  const fragment = preRange.cloneContents()
  const div = document.createElement('div')
  div.appendChild(fragment)
  return getTextFromElement(div).length
}

// ============================================================================
// Helper: Set cursor position in contenteditable
// ============================================================================

function setCursorPosition(element: HTMLElement, targetPosition: number): void {
  const selection = window.getSelection()
  if (!selection) return

  let currentPos = 0

  function findPosition(node: Node): { node: Node; offset: number } | null {
    if (node.nodeType === Node.TEXT_NODE) {
      const rawText = node.textContent || ''
      // Filter out zero-width spaces to match text model (ZWS is a DOM-only artifact)
      const textWithoutZWS = rawText.replace(/\u200B/g, '')
      const modelLength = textWithoutZWS.length

      if (currentPos + modelLength >= targetPosition) {
        // Calculate actual DOM offset accounting for zero-width spaces
        const modelOffset = targetPosition - currentPos
        let domOffset = 0
        let modelCount = 0
        while (modelCount < modelOffset && domOffset < rawText.length) {
          if (rawText[domOffset] !== '\u200B') {
            modelCount++
          }
          domOffset++
        }
        // Skip any trailing ZWS at the target position
        while (domOffset < rawText.length && rawText[domOffset] === '\u200B') {
          domOffset++
        }
        return { node, offset: domOffset }
      }
      currentPos += modelLength
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      const el = node as HTMLElement

      // Skip mention badge internals - treat as atomic
      if (el.getAttribute('data-mention') === 'true') {
        const mentionText = el.getAttribute('data-mention-text') || ''
        const mentionLength = mentionText.length
        if (currentPos + mentionLength >= targetPosition) {
          // Position cursor after the badge
          return { node: el.parentNode!, offset: Array.from(el.parentNode!.childNodes).indexOf(el) + 1 }
        }
        currentPos += mentionLength
        return null
      }

      // Handle BR
      if (el.tagName === 'BR') {
        currentPos += 1
        if (currentPos >= targetPosition) {
          return { node: el.parentNode!, offset: Array.from(el.parentNode!.childNodes).indexOf(el) + 1 }
        }
        return null
      }

      for (let i = 0; i < el.childNodes.length; i++) {
        const result = findPosition(el.childNodes[i])
        if (result) return result
      }
    }
    return null
  }

  const result = findPosition(element)

  if (result) {
    const range = document.createRange()
    range.setStart(result.node, result.offset)
    range.collapse(true)
    selection.removeAllRanges()
    selection.addRange(range)
  } else {
    // Position at end
    const range = document.createRange()
    range.selectNodeContents(element)
    range.collapse(false)
    selection.removeAllRanges()
    selection.addRange(range)
  }
}

// ============================================================================
// Convert text with mentions to HTML
// ============================================================================

function textToHTML(
  text: string,
  skills: LoadedSkill[],
  sources: LoadedSource[],
  workspaceId?: string
): string {
  if (!text) return ''

  const skillSlugs = skills.map(s => s.slug)
  const sourceSlugs = sources.map(s => s.config.slug)
  const matches = findMentionMatches(text, skillSlugs, sourceSlugs)

  // Escape HTML in text
  const escapeHTML = (str: string) => str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\n/g, '<br>')

  if (matches.length === 0) {
    return escapeHTML(text)
  }

  let html = ''
  let lastIndex = 0

  // If first match starts at position 0, prepend zero-width space for contenteditable cursor fix
  if (matches[0].startIndex === 0) {
    html += '\u200B'
  }

  for (const match of matches) {
    // Add escaped text before this mention
    if (match.startIndex > lastIndex) {
      html += escapeHTML(text.slice(lastIndex, match.startIndex))
    }

    // Determine label and data for badge
    let label = match.id
    let skill: LoadedSkill | undefined
    let source: LoadedSource | undefined
    let tooltip: string | undefined

    if (match.type === 'skill') {
      skill = skills.find(s => s.slug === match.id)
      label = skill?.metadata.name || match.id
    } else if (match.type === 'source') {
      source = sources.find(s => s.config.slug === match.id)
      label = source?.config.name || match.id
    } else if (match.type === 'file') {
      // Show filename as badge label, full path as tooltip
      label = match.id.split('/').pop() || match.id
      tooltip = match.id
    } else if (match.type === 'folder') {
      // Show folder name as badge label, full path as tooltip
      label = match.id.split('/').pop() || match.id
      tooltip = match.id
    }

    // Render badge with data-mention-text storing the original text
    const badgeHtml = renderBadgeHTML(match.type, label, skill, source, workspaceId, tooltip)
    // Add data-mention-text attribute to store original text for extraction
    const withMentionText = badgeHtml.replace(
      'data-mention="true"',
      `data-mention="true" data-mention-text="${match.fullMatch.replace(/"/g, '&quot;')}"`
    )
    html += withMentionText
    // Zero-width space after badge ensures cursor can be placed after the last badge
    html += '\u200B'

    lastIndex = match.startIndex + match.fullMatch.length
  }

  // Add remaining text after last mention
  if (lastIndex < text.length) {
    html += escapeHTML(text.slice(lastIndex))
  }

  return html
}

// ============================================================================
// Check if mentions have changed (for determining if we need to re-render HTML)
// ============================================================================

function getMentionSignature(text: string, skillSlugs: string[], sourceSlugs: string[]): string {
  const matches = findMentionMatches(text, skillSlugs, sourceSlugs)
  return matches.map(m => `${m.type}:${m.id}:${m.startIndex}`).join('|')
}

// ============================================================================
// RotatingPlaceholder Component
// Animated placeholder that cycles through an array of strings with fade transitions.
// Stays visible even when input is focused (until user types).
// ============================================================================

interface RotatingPlaceholderProps {
  /** Array of placeholder strings to rotate through */
  placeholders: string[]
  /** Interval in ms between rotations (default: 5000) */
  intervalMs?: number
  /** Additional className for styling */
  className?: string
}

function RotatingPlaceholder({
  placeholders,
  intervalMs = 5000,
  className,
}: RotatingPlaceholderProps) {
  const [currentIndex, setCurrentIndex] = React.useState(0)
  const [opacity, setOpacity] = React.useState(1)

  React.useEffect(() => {
    // Don't rotate if only one placeholder
    if (placeholders.length <= 1) return

    const interval = setInterval(() => {
      // Fade out
      setOpacity(0)

      // After fade out (300ms), swap text and fade back in
      setTimeout(() => {
        setCurrentIndex((prev) => (prev + 1) % placeholders.length)
        setOpacity(1)
      }, 300)
    }, intervalMs)

    return () => clearInterval(interval)
  }, [placeholders.length, intervalMs])

  return (
    <div
      className={cn('transition-opacity duration-300 ease-in-out', className)}
      style={{ opacity }}
    >
      {placeholders[currentIndex]}
    </div>
  )
}

// ============================================================================
// RichTextInput Component
// ============================================================================

export const RichTextInput = React.forwardRef<RichTextInputHandle, RichTextInputProps>(
  function RichTextInput(
    {
      value,
      onChange,
      placeholder,
      skills = [],
      sources = [],
      workspaceId,
      disabled = false,
      className,
      onFocus,
      onBlur,
      onKeyDown,
      onInput,
      onPaste,
      onLongTextPaste,
      ...restProps
    },
    forwardedRef
  ) {
    const { t } = useTranslation()
    const safeValue = React.useMemo(() => coerceInputText(value), [value])
    const divRef = React.useRef<HTMLDivElement>(null)
    const [isFocused, setIsFocused] = React.useState(false)
    const isComposing = React.useRef(false)
    const lastValueRef = React.useRef(safeValue)
    const cursorPositionRef = React.useRef(0)
    const lastMentionSignatureRef = React.useRef('')
    const isInternalUpdate = React.useRef(false)
    // Pending cursor position to restore after external value update (e.g., after @mention selection)
    const pendingCursorRef = React.useRef<number | null>(null)

    const skillSlugs = React.useMemo(() => skills.map(s => s.slug), [skills])
    const sourceSlugs = React.useMemo(() => sources.map(s => s.config.slug), [sources])

    // Preload icons for sources and skills
    React.useEffect(() => {
      if (!workspaceId) return

      // Preload source icons
      for (const source of sources) {
        loadSourceIcon({ config: source.config, workspaceId })
      }

      // LoadedSkill.iconPath already comes from host file discovery. An absent
      // path and config icon mean fallback, not another round of missing reads.
      for (const skill of skills) {
        if (skill.iconPath || skill.metadata.icon) loadSkillIcon(skill, workspaceId)
      }
    }, [sources, skills, workspaceId])

    // Expose imperative handle
    React.useImperativeHandle(forwardedRef, () => ({
      focus: () => divRef.current?.focus(),
      blur: () => divRef.current?.blur(),
      get value() { return lastValueRef.current },
      get selectionStart() { return cursorPositionRef.current },
      setValue: (newValue: string) => {
        lastValueRef.current = newValue
      },
      setSelectionRange: (start: number, _end: number) => {
        // Store pending cursor for when external value sync runs
        pendingCursorRef.current = start
        cursorPositionRef.current = start
        if (divRef.current) {
          setCursorPosition(divRef.current, start)
        }
      },
      getBoundingClientRect: () => divRef.current?.getBoundingClientRect() ?? new DOMRect(),
      getCaretRect: () => {
        const selection = window.getSelection()
        if (!selection || selection.rangeCount === 0) return null
        const range = selection.getRangeAt(0)
        const rect = range.getBoundingClientRect()
        // If rect has zero dimensions (collapsed selection at line start), use a fallback
        if (rect.width === 0 && rect.height === 0 && rect.x === 0 && rect.y === 0) {
          // Insert a temporary span to measure position
          const span = document.createElement('span')
          span.textContent = '\u200B' // Zero-width space
          range.insertNode(span)
          const spanRect = span.getBoundingClientRect()
          span.remove()
          // Restore selection
          selection.removeAllRanges()
          selection.addRange(range)
          return spanRect
        }
        return rect
      },
      get element() { return divRef.current },
    }), [])

    // Handle input events
    const handleInput = React.useCallback(() => {
      if (isComposing.current) return
      if (!divRef.current) return

      const newText = getTextFromElement(divRef.current)
      const cursorPos = getCursorPosition(divRef.current, cursorPositionRef.current)

      lastValueRef.current = newText
      cursorPositionRef.current = cursorPos

      // Check if mentions changed - if so, we need to re-render HTML
      const newSignature = getMentionSignature(newText, skillSlugs, sourceSlugs)
      if (newSignature !== lastMentionSignatureRef.current) {
        lastMentionSignatureRef.current = newSignature
        // Re-render with badges
        isInternalUpdate.current = true
        const html = textToHTML(newText, skills, sources, workspaceId)
        divRef.current.innerHTML = html || '<br>' // Empty contenteditable needs a BR
        // Restore cursor
        setCursorPosition(divRef.current, cursorPos)
        isInternalUpdate.current = false
      }

      onChange(newText)
      onInput?.(newText, cursorPos)
    }, [onChange, onInput, skills, sources, skillSlugs, sourceSlugs, workspaceId])

    // Handle composition (IME)
    const handleCompositionStart = React.useCallback(() => {
      isComposing.current = true
    }, [])

    const handleCompositionEnd = React.useCallback(() => {
      isComposing.current = false
      handleInput()
    }, [handleInput])

    const handleKeyDownInternal = React.useCallback((e: React.KeyboardEvent<HTMLDivElement>) => {
      if (isEscapeDuringComposition(e, isComposing.current)) {
        e.stopPropagation()
        return
      }

      onKeyDown?.(e)
    }, [onKeyDown])

    // Handle paste - delegate files to parent, manually insert plain text
    const handlePasteInternal = React.useCallback((e: React.ClipboardEvent) => {
      // Check if we have files - let parent handle that
      const hasFiles = e.clipboardData?.files && e.clipboardData.files.length > 0
      if (hasFiles && onPaste) {
        e.preventDefault()
        onPaste(e)
        return
      }

      // Prevent default to avoid HTML paste, then insert plain text manually
      e.preventDefault()

      const text = e.clipboardData?.getData('text/plain')
      if (!text) return

      // Check if text is too long - convert to file attachment instead
      const lineCount = text.split('\n').length
      if (lineCount > LONG_TEXT_LINE_THRESHOLD && onLongTextPaste) {
        onLongTextPaste(text)
        return
      }

      // Use execCommand to insert text - this integrates with the browser's
      // native undo stack so CMD+Z works after paste. Manual DOM manipulation
      // (range.insertNode) bypasses the undo history.
      document.execCommand('insertText', false, text)
    }, [onPaste, onLongTextPaste])

    // Handle focus
    const handleFocus = React.useCallback((e: React.FocusEvent<HTMLDivElement>) => {
      setIsFocused(true)
      // Tell browser to use <br> instead of <div> for line breaks.
      // This prevents div-wrapping when typing before non-editable spans (badges).
      document.execCommand('defaultParagraphSeparator', false, 'br')
      onFocus?.(e)
    }, [onFocus])

    // Handle blur
    const handleBlur = React.useCallback((e: React.FocusEvent<HTMLDivElement>) => {
      setIsFocused(false)
      onBlur?.(e)
    }, [onBlur])

    // Sync value from props (when parent updates value externally)
    React.useEffect(() => {
      if (!divRef.current) return
      if (isInternalUpdate.current) return
      if (lastValueRef.current === safeValue) return

      // External value change - update content
      lastValueRef.current = safeValue
      lastMentionSignatureRef.current = getMentionSignature(safeValue, skillSlugs, sourceSlugs)

      const html = textToHTML(safeValue, skills, sources, workspaceId)
      divRef.current.innerHTML = html || '<br>'

      // Restore cursor position after innerHTML update.
      // Only restore if:
      // 1. We have a pending position from setSelectionRange (explicit programmatic positioning), OR
      // 2. The element is actually focused (user is actively editing)
      // This prevents stealing focus during session changes when search is active.
      if (pendingCursorRef.current !== null || document.activeElement === divRef.current) {
        const cursorPos = pendingCursorRef.current ?? cursorPositionRef.current ?? safeValue.length
        setCursorPosition(divRef.current, cursorPos)
        pendingCursorRef.current = null // Clear after use
      }
    }, [safeValue, skills, sources, skillSlugs, sourceSlugs, workspaceId])

    // Initialize content on mount
    React.useEffect(() => {
      if (!divRef.current) return
      lastMentionSignatureRef.current = getMentionSignature(safeValue, skillSlugs, sourceSlugs)
      const html = textToHTML(safeValue, skills, sources, workspaceId)
      divRef.current.innerHTML = html || '<br>'
      lastValueRef.current = safeValue
    }, []) // eslint-disable-line react-hooks/exhaustive-deps

    // Handle selection changes to highlight badges when selected
    React.useEffect(() => {
      // Get selection color from CSS variable (accent with transparency)
      const getSelectionColor = () => {
        const accent = getComputedStyle(document.documentElement).getPropertyValue('--accent').trim()
        // color-mix accepts every supported CSS color syntax (hex, rgb, hsl,
        // oklch and named colors) without parsing token serialization in JS.
        return accent
          ? `color-mix(in srgb, ${accent} 40%, transparent)`
          : 'rgba(99, 102, 241, 0.4)'
      }

      const handleSelectionChange = () => {
        if (!divRef.current) return

        const selection = window.getSelection()
        if (!selection || selection.rangeCount === 0) return

        const range = selection.getRangeAt(0)

        // Get all mention badges
        const badges = divRef.current.querySelectorAll('.mention-badge') as NodeListOf<HTMLElement>

        badges.forEach((badge) => {
          // Check if badge is within selection range
          const badgeRange = document.createRange()
          badgeRange.selectNode(badge)

          const isSelected =
            range.compareBoundaryPoints(Range.START_TO_END, badgeRange) > 0 &&
            range.compareBoundaryPoints(Range.END_TO_START, badgeRange) < 0

          if (isSelected) {
            badge.style.backgroundColor = getSelectionColor()
            badge.classList.remove('bg-background')
          } else {
            badge.style.backgroundColor = ''
            badge.classList.add('bg-background')
          }
        })
      }

      document.addEventListener('selectionchange', handleSelectionChange)
      return () => document.removeEventListener('selectionchange', handleSelectionChange)
    }, [])

    // Show placeholder when input is empty (regardless of focus state)
    const showPlaceholder = !safeValue

    // Normalize placeholder to array for RotatingPlaceholder
    const placeholderArray = React.useMemo(() => {
      if (!placeholder) return [t("chatInput.placeholder.typeMessage")]
      return Array.isArray(placeholder) ? placeholder : [placeholder]
    }, [placeholder])

    // Check if value contains any mentions (badges) to adjust line height
    const hasMentions = React.useMemo(() => {
      const mentions = parseMentions(safeValue, skillSlugs, sourceSlugs)
      return mentions.skills.length > 0 || mentions.sources.length > 0 || mentions.files.length > 0 || mentions.folders.length > 0
    }, [safeValue, skillSlugs, sourceSlugs])

    return (
      <div className="relative">
        <div
          ref={divRef}
          contentEditable={!disabled}
          suppressContentEditableWarning
          tabIndex={disabled ? -1 : 0}
          // Disable auto-capitalization/correction that breaks IME (e.g. CJK pinyin) input (#837/#878)
          autoCapitalize="none"
          autoCorrect="off"
          className={cn(
            'outline-none text-sm whitespace-pre-wrap break-words',
            'min-h-[1.5em]',
            disabled && 'opacity-50 cursor-not-allowed',
            // Make text transparent when showing placeholder (so caret is still visible)
            showPlaceholder && 'text-transparent caret-foreground',
            className
          )}
          // Use inline style for line-height to override text-sm's built-in line-height
          style={{ lineHeight: 1.25 }}
          onInput={handleInput}
          onKeyDown={handleKeyDownInternal}
          onFocus={handleFocus}
          onBlur={handleBlur}
          onPaste={handlePasteInternal}
          onCompositionStart={handleCompositionStart}
          onCompositionEnd={handleCompositionEnd}
          aria-disabled={disabled}
          aria-placeholder={Array.isArray(placeholder) ? placeholder[0] : placeholder}
          role="textbox"
          aria-multiline="true"
          {...restProps}
        />
        {/* Rotating placeholder overlay - visible when empty, even when focused */}
        {showPlaceholder && (
          <RotatingPlaceholder
            placeholders={placeholderArray}
            intervalMs={5000}
            className={cn(
              'absolute inset-0 text-sm text-muted-foreground pointer-events-none select-none',
              className
            )}
          />
        )}
      </div>
    )
  }
)

import { useState, useEffect, useCallback, useRef } from "react"
import { useTranslation } from "react-i18next"
import { ArrowLeft, CheckCircle, XCircle, Plus } from "lucide-react"
import { cn } from "@/lib/utils"
import { slugify } from "@/lib/slugify"
import { Input } from "../ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "../ui/select"
import { AddWorkspaceContainer, AddWorkspaceStepHeader, AddWorkspacePrimaryButton, AddWorkspaceSecondaryButton } from "./primitives"
import { DATA_DIR_NAME } from "@phaneris/shared/identity.generated"

const CREATE_NEW_VALUE = '__create_new__'

interface AddWorkspaceStep_ConnectRemoteProps {
  onBack: () => void
  onCreate: (folderPath: string, name: string, remoteServer: { url: string; token: string; remoteWorkspaceId: string; allowInsecureTls?: boolean }) => Promise<void>
  isCreating: boolean
  /** Pre-fill the server URL (for reconnect flow) */
  initialUrl?: string
  /** Initial value for the explicit self-signed TLS opt-in */
  initialAllowInsecureTls?: boolean
  /** When set, updating an existing workspace's remote config instead of creating */
  reconnectWorkspace?: { id: string; name: string; remoteWorkspaceId: string; allowInsecureTls?: boolean }
  /** Called when reconnect updates the remote server config. A blank token keeps the stored vault credential. */
  onUpdate?: (workspaceId: string, remoteServer: { url: string; token?: string; remoteWorkspaceId: string; allowInsecureTls?: boolean }) => Promise<void>
}

/**
 * Resolve a unique local workspace slug by appending suffixes if needed.
 * Tries: baseName → baseName-remote → baseName-2 → baseName-3 → ...
 */
async function resolveUniqueSlug(baseName: string): Promise<{ slug: string; path: string }> {
  const baseSlug = slugify(baseName)
  if (!baseSlug) return { slug: 'remote', path: '' }

  let slug = baseSlug
  let attempt = 0

  // eslint-disable-next-line no-constant-condition
  while (true) {
    const result = await window.electronAPI.checkWorkspaceSlug(slug)
    if (!result.exists) {
      return { slug, path: result.path }
    }
    attempt++
    slug = attempt === 1 ? `${baseSlug}-remote` : `${baseSlug}-${attempt}`
    if (attempt > 20) {
      // Safety valve — shouldn't happen in practice
      return { slug: `${baseSlug}-${Date.now()}`, path: result.path.replace(baseSlug, `${baseSlug}-${Date.now()}`) }
    }
  }
}

/**
 * AddWorkspaceStep_ConnectRemote - Connect to a remote Phaneris Server
 *
 * Two paths:
 * 1. Connect to existing workspace — select from dropdown, no name needed, auto-resolve local slug
 * 2. Create new workspace — type a name, creates on server, then connects
 */
export function AddWorkspaceStep_ConnectRemote({
  onBack,
  onCreate,
  isCreating,
  initialUrl,
  initialAllowInsecureTls,
  reconnectWorkspace,
  onUpdate,
}: AddWorkspaceStep_ConnectRemoteProps) {
  const { t } = useTranslation()
  const isReconnectMode = !!reconnectWorkspace
  const [serverUrl, setServerUrl] = useState(initialUrl ?? '')
  const [token, setToken] = useState('')
  const [allowInsecureTls, setAllowInsecureTls] = useState(
    initialAllowInsecureTls ?? reconnectWorkspace?.allowInsecureTls ?? false,
  )
  const [homeDir, setHomeDir] = useState('')
  const [testState, setTestState] = useState<'idle' | 'testing' | 'ok' | 'error'>('idle')
  const [testError, setTestError] = useState<string | null>(null)
  const [remoteWorkspaces, setRemoteWorkspaces] = useState<Array<{ id: string; name: string }>>([])
  const [selectedValue, setSelectedValue] = useState<string | null>(null) // workspace ID or CREATE_NEW_VALUE
  const [newWorkspaceName, setNewWorkspaceName] = useState('')
  const [serverVersion, setServerVersion] = useState<string | null>(null)
  const selectPortalRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    window.electronAPI.getHomeDir().then(setHomeDir)
  }, [])

  const isCreateNew = selectedValue === CREATE_NEW_VALUE
  const selectedWorkspace = !isCreateNew ? remoteWorkspaces.find(w => w.id === selectedValue) : null
  // Fresh server (no workspaces at all) — always in create mode
  const isFreshServer = testState === 'ok' && remoteWorkspaces.length === 0

  // Reset test state when URL or token changes
  useEffect(() => {
    setTestState('idle')
    setTestError(null)
    setRemoteWorkspaces([])
    setSelectedValue(null)
    setNewWorkspaceName('')
  }, [serverUrl, token, allowInsecureTls])

  const handleTestConnection = useCallback(async () => {
    // In reconnect mode a blank token means "use the stored vault credential";
    // main resolves it from the workspace id passed below.
    if (!serverUrl || (!token && !isReconnectMode)) return
    setTestState('testing')
    setTestError(null)
    try {
      const result = await window.electronAPI.testRemoteConnection(
        serverUrl,
        token || undefined,
        allowInsecureTls,
        reconnectWorkspace?.id,
      )
      console.log('[ConnectRemote] testRemoteConnection result:', JSON.stringify(result, null, 2))
      if (result.ok) {
        setTestState('ok')
        setServerVersion(result.serverVersion ?? null)
        if (result.needsWorkspace) {
          // Fresh server — no workspaces, go straight to create mode
          setRemoteWorkspaces([])
          setSelectedValue(null)
        } else {
          const workspaces = result.remoteWorkspaces ?? []
          setRemoteWorkspaces(workspaces)
          if (workspaces.length === 1) {
            setSelectedValue(workspaces[0]!.id)
          }
        }
      } else {
        setTestState('error')
        setTestError(result.error || 'Connection failed')
      }
    } catch (err) {
      setTestState('error')
      setTestError(err instanceof Error ? err.message : 'Connection failed')
    }
  }, [serverUrl, token, allowInsecureTls, reconnectWorkspace])

  const handleConnect = useCallback(async () => {
    // A reconnect may only change URL/TLS while keeping the stored token.
    if (!serverUrl || (!token && !isReconnectMode)) return

    // Reconnect mode — update existing workspace config
    if (isReconnectMode && onUpdate) {
      try {
        await onUpdate(reconnectWorkspace!.id, {
          url: serverUrl,
          token: token.trim() || undefined,
          remoteWorkspaceId: reconnectWorkspace!.remoteWorkspaceId,
          allowInsecureTls,
        })
        return
      } catch (err) {
        setTestState('error')
        setTestError(err instanceof Error ? err.message : 'Failed to reconnect workspace')
        return
      }
    }

    if (!token) return
    if (!homeDir) return
    const defaultBasePath = `${homeDir}/${DATA_DIR_NAME}/workspaces`

    if (isCreateNew || isFreshServer) {
      // Create new workspace on remote server via direct RPC, then connect locally
      const name = newWorkspaceName.trim()
      if (!name) return

      try {
        // Token here is the credential the user just typed into this form (not a
        // stored workspace token), and no local workspace exists yet for
        // sendResourcesToRemote to resolve — so this goes through the validated
        // invokeOnServer bridge (H-2: scheme allowlist + channel allowlist +
        // main-frame sender check enforced main-side).
        const created = await window.electronAPI.invokeOnServer(
          serverUrl,
          token,
          'server:createWorkspace',
          [name],
          { allowInsecureTls },
        ) as { id: string; name: string }

        const { slug, path } = await resolveUniqueSlug(name)
        const finalPath = path || `${defaultBasePath}/${slug}`
        await onCreate(finalPath, name, { url: serverUrl, token, remoteWorkspaceId: created.id, allowInsecureTls })
      } catch (err) {
        setTestState('error')
        setTestError(err instanceof Error ? err.message : 'Failed to create workspace on remote server')
        return
      }
    } else if (selectedWorkspace) {
      // Connect to existing workspace — auto-resolve local slug
      const { slug, path } = await resolveUniqueSlug(selectedWorkspace.name)
      const finalPath = path || `${defaultBasePath}/${slug}`
      await onCreate(finalPath, selectedWorkspace.name, { url: serverUrl, token, remoteWorkspaceId: selectedWorkspace.id, allowInsecureTls })
    }
  }, [serverUrl, token, allowInsecureTls, homeDir, isCreateNew, isFreshServer, newWorkspaceName, selectedWorkspace, onCreate, isReconnectMode, onUpdate, reconnectWorkspace])

  const canConnect = testState === 'ok' && !isCreating && (
    isReconnectMode ? true :
    (isFreshServer || isCreateNew) ? !!newWorkspaceName.trim() : !!selectedWorkspace
  )

  const showCreateMode = !isReconnectMode && (isCreateNew || isFreshServer)
  const buttonLabel = isReconnectMode ? 'Reconnect' : showCreateMode ? 'Create and Connect' : 'Connect'
  const buttonLoadingLabel = isReconnectMode ? 'Reconnecting...' : showCreateMode ? 'Creating...' : 'Connecting...'

  return (
    <AddWorkspaceContainer>
      {/* Back button */}
      <button
        onClick={onBack}
        disabled={isCreating}
        className={cn(
          "self-start flex items-center gap-1 text-sm text-muted-foreground",
          "hover:text-foreground transition-colors mb-4",
          isCreating && "opacity-50 cursor-not-allowed"
        )}
      >
        <ArrowLeft className="h-4 w-4" />
        Back
      </button>

      <AddWorkspaceStepHeader
        title={isReconnectMode ? t("workspace.reconnect", { name: reconnectWorkspace!.name }) : "Connect to remote server"}
        description={isReconnectMode
          ? "Update the server URL or token to restore the connection."
          : "Connect to a remote Phaneris Server for this workspace."}
      />

      <div className="mt-6 w-full space-y-5">
        {/* Server URL */}
        <div className="space-y-2">
          <label className="block text-sm font-medium text-foreground">
            Server URL
          </label>
          <div className="bg-background shadow-minimal rounded-lg">
            <Input
              value={serverUrl}
              onChange={(e) => setServerUrl(e.target.value)}
              placeholder="ws://192.168.1.100:9100"
              disabled={isCreating}
              autoFocus
              className="border-0 bg-transparent shadow-none font-mono text-sm"
            />
          </div>
        </div>

        {/* Token */}
        <div className="space-y-2">
          <label className="block text-sm font-medium text-foreground">
            Token
          </label>
          <div className="bg-background shadow-minimal rounded-lg">
            <Input
              type="password"
              value={token}
              onChange={(e) => setToken(e.target.value)}
              placeholder={t("workspace.serverAuthToken")}
              disabled={isCreating}
              className="border-0 bg-transparent shadow-none"
            />
          </div>
          {isReconnectMode && (
            <p className="text-xs text-muted-foreground">Leave blank to keep the stored token.</p>
          )}
        </div>


        {/* Self-signed TLS opt-in. Off by default so tokens are not exposed to MITM. */}
        <label className="flex items-start gap-2 text-xs text-muted-foreground">
          <input
            type="checkbox"
            checked={allowInsecureTls}
            onChange={(e) => setAllowInsecureTls(e.target.checked)}
            disabled={isCreating}
            className="mt-0.5 h-3.5 w-3.5 rounded border-border"
          />
          <span>{t("workspace.allowInsecureTls")}</span>
        </label>

        {/* Test Connection */}
        <div className="flex items-center gap-3">
          <AddWorkspaceSecondaryButton
            onClick={handleTestConnection}
            disabled={!serverUrl || (!token && !isReconnectMode) || testState === 'testing' || isCreating}
          >
            {testState === 'testing' ? 'Testing...' : 'Test Connection'}
          </AddWorkspaceSecondaryButton>
          {testState === 'ok' && !isFreshServer && (
            <span className="flex items-center gap-1 text-xs text-green-600 dark:text-green-400">
              <CheckCircle className="h-3.5 w-3.5" />
              Connected{serverVersion ? ` — v${serverVersion}` : ''}
            </span>
          )}
          {testState === 'ok' && isFreshServer && (
            <span className="flex items-center gap-1 text-xs text-green-600 dark:text-green-400">
              <CheckCircle className="h-3.5 w-3.5" />
              Connected{serverVersion ? ` — v${serverVersion}` : ''} — no workspaces yet
            </span>
          )}
          {testState === 'error' && (
            <span className="flex items-center gap-1 text-xs text-destructive">
              <XCircle className="h-3.5 w-3.5" />
              {testError || 'Failed'}
            </span>
          )}
        </div>

        {/* Old server warning */}
        {testState === 'ok' && !serverVersion && (
          <div className="flex items-start gap-2 px-3 py-2 rounded-lg bg-yellow-500/10 border border-yellow-500/20 text-xs text-yellow-700 dark:text-yellow-400">
            <XCircle className="h-3.5 w-3.5 shrink-0 mt-0.5" />
            <span>{t("workspace.olderServerWarning")}</span>
          </div>
        )}

        {/* Portal container for Select — must be inside the Dialog to receive pointer events */}
        <div ref={selectPortalRef} />

        {/* Workspace selector — pick existing or create new (hidden in reconnect mode) */}
        {!isReconnectMode && testState === 'ok' && remoteWorkspaces.length > 0 && !isCreateNew && (
          <div className="space-y-2">
            <label className="block text-sm font-medium text-foreground">
              Workspace
            </label>
            <div className="bg-background shadow-minimal rounded-lg">
              <Select
                value={selectedValue ?? ''}
                onValueChange={setSelectedValue}
                disabled={isCreating}
              >
                <SelectTrigger className="border-0 bg-transparent shadow-none">
                  <SelectValue placeholder={t("workspace.selectWorkspacePlaceholder")} />
                </SelectTrigger>
                <SelectContent container={selectPortalRef.current}>
                  {remoteWorkspaces.map(ws => (
                    <SelectItem key={ws.id} value={ws.id}>
                      {ws.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <button
              type="button"
              onClick={() => setSelectedValue(CREATE_NEW_VALUE)}
              disabled={isCreating}
              className="flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground transition-colors"
            >
              <Plus className="h-3 w-3" />
              Create new workspace on server
            </button>
          </div>
        )}

        {/* New workspace name — shown for fresh servers or "Create new" selection (hidden in reconnect mode) */}
        {!isReconnectMode && testState === 'ok' && showCreateMode && (
          <div className="space-y-2">
            <label className="block text-sm font-medium text-foreground">
              Workspace name
            </label>
            <div className="bg-background shadow-minimal rounded-lg">
              <Input
                value={newWorkspaceName}
                onChange={(e) => setNewWorkspaceName(e.target.value)}
                placeholder={t("workspace.myRemoteWorkspace")}
                disabled={isCreating}
                className="border-0 bg-transparent shadow-none"
              />
            </div>
            <p className="text-xs text-muted-foreground">
              A workspace will be created on the remote server with this name.
            </p>
            {isCreateNew && remoteWorkspaces.length > 0 && (
              <button
                type="button"
                onClick={() => {
                  setSelectedValue(remoteWorkspaces.length === 1 ? remoteWorkspaces[0]!.id : null)
                  setNewWorkspaceName('')
                }}
                disabled={isCreating}
                className="flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground transition-colors"
              >
                <ArrowLeft className="h-3 w-3" />
                Use existing workspace
              </button>
            )}
          </div>
        )}

        {/* Connect / Create and Connect */}
        <AddWorkspacePrimaryButton
          onClick={handleConnect}
          disabled={!canConnect}
          loading={isCreating}
          loadingText={buttonLoadingLabel}
        >
          {buttonLabel}
        </AddWorkspacePrimaryButton>
      </div>
    </AddWorkspaceContainer>
  )
}

import { useState, useEffect, useCallback, useMemo } from "react"
import { useTranslation } from "react-i18next"
import { X } from "lucide-react"
import { motion, useReducedMotionConfig } from "motion/react"
import { Dithering } from "@paper-design/shaders-react"
import { FullscreenOverlayBase } from "@phaneris/ui"
import { ContentSwap } from "@/components/ui/content-swap"
import { cn } from "@/lib/utils"
import { overlayTransitionIn } from "@/lib/animations"
import { AddWorkspaceStep_Choice } from "./AddWorkspaceStep_Choice"
import { AddWorkspaceStep_CreateNew } from "./AddWorkspaceStep_CreateNew"
import { AddWorkspaceStep_OpenFolder } from "./AddWorkspaceStep_OpenFolder"
import { AddWorkspaceStep_ConnectRemote } from "./AddWorkspaceStep_ConnectRemote"
import type { Workspace } from "../../../shared/types"
import { toast } from "sonner"

type CreationStep = 'choice' | 'create' | 'open' | 'remote'

interface WorkspaceCreationScreenProps {
  /** Callback when a workspace is created successfully */
  onWorkspaceCreated: (workspace: Workspace) => void
  /** Callback when the screen is dismissed */
  onClose: () => void
  className?: string
  /** When set, skip choice step and open ConnectRemote in reconnect mode */
  reconnectWorkspace?: Workspace
  /** Reconnect an existing remote workspace and resolve only on real success. */
  onReconnectWorkspace?: (workspaceId: string, remoteServer: { url: string; token?: string; remoteWorkspaceId: string; allowInsecureTls?: boolean }) => Promise<void>
}

/**
 * WorkspaceCreationScreen - Full-screen overlay for creating workspaces
 *
 * Obsidian-style flow:
 * 1. Choice: Create new workspace OR Open existing folder
 * 2a. Create: Enter name + choose location (default or custom)
 * 2b. Open: Browse folder OR create new folder at location
 */
export function WorkspaceCreationScreen({
  onWorkspaceCreated,
  onClose,
  className,
  reconnectWorkspace,
  onReconnectWorkspace,
}: WorkspaceCreationScreenProps) {
  const { t } = useTranslation()
  // Canvas motion is outside MotionConfig's reach: the shader owns its own rAF
  // loop, so the preference has to be passed in explicitly. speed=0 stops the
  // loop entirely (static shader, no recurring cost) instead of just slowing it.
  const reduceMotion = useReducedMotionConfig()
  // Start at 'remote' step directly when reconnecting
  const [step, setStep] = useState<CreationStep>(reconnectWorkspace ? 'remote' : 'choice')
  const [isCreating, setIsCreating] = useState(false)
  const [dimensions, setDimensions] = useState({ width: 1920, height: 1080 })

  // Track window dimensions for shader
  useEffect(() => {
    const updateDimensions = () => {
      setDimensions({ width: window.innerWidth, height: window.innerHeight })
    }
    updateDimensions()
    window.addEventListener('resize', updateDimensions)
    return () => window.removeEventListener('resize', updateDimensions)
  }, [])

  // Wrap onClose to prevent closing during creation
  // FullscreenOverlayBase handles ESC key, this wrapper prevents closing when busy
  const handleClose = useCallback(() => {
    if (!isCreating) {
      onClose()
    }
  }, [isCreating, onClose])

  const handleCreateWorkspace = useCallback(async (folderPath: string, name: string, remoteServer?: { url: string; token: string; remoteWorkspaceId: string; allowInsecureTls?: boolean }) => {
    setIsCreating(true)
    try {
      const workspace = await window.electronAPI.createWorkspace(folderPath, name, remoteServer)
      onWorkspaceCreated(workspace)
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error'
      toast.error(t('toast.failedToCreateWorkspace'), {
        description: message,
      })
    } finally {
      setIsCreating(false)
    }
  }, [onWorkspaceCreated])

  const handleReconnectWorkspace = useCallback(async (workspaceId: string, remoteServer: { url: string; token?: string; remoteWorkspaceId: string; allowInsecureTls?: boolean }) => {
    if (!onReconnectWorkspace) {
      throw new Error('Reconnect handler not configured')
    }

    setIsCreating(true)
    try {
      await onReconnectWorkspace(workspaceId, remoteServer)
    } finally {
      setIsCreating(false)
    }
  }, [onReconnectWorkspace])

  const renderStep = () => {
    switch (step) {
      case 'choice':
        return (
          <AddWorkspaceStep_Choice
            onCreateNew={() => setStep('create')}
            onOpenFolder={() => setStep('open')}
            onConnectRemote={() => setStep('remote')}
          />
        )

      case 'create':
        return (
          <AddWorkspaceStep_CreateNew
            onBack={() => setStep('choice')}
            onCreate={handleCreateWorkspace}
            isCreating={isCreating}
          />
        )

      case 'open':
        return (
          <AddWorkspaceStep_OpenFolder
            onBack={() => setStep('choice')}
            onCreate={handleCreateWorkspace}
            isCreating={isCreating}
          />
        )

      case 'remote':
        return (
          <AddWorkspaceStep_ConnectRemote
            onBack={reconnectWorkspace ? onClose : () => setStep('choice')}
            onCreate={handleCreateWorkspace}
            isCreating={isCreating}
            initialUrl={reconnectWorkspace?.remoteServer?.url}
            initialAllowInsecureTls={reconnectWorkspace?.remoteServer?.allowInsecureTls}
            reconnectWorkspace={reconnectWorkspace?.remoteServer ? {
              id: reconnectWorkspace.id,
              name: reconnectWorkspace.name,
              remoteWorkspaceId: reconnectWorkspace.remoteServer.remoteWorkspaceId,
            } : undefined}
            onUpdate={handleReconnectWorkspace}
          />
        )

      default:
        return null
    }
  }

  // Get theme colors from CSS variables for the shader
  const shaderColors = useMemo(() => {
    if (typeof window === 'undefined') return { back: '#00000000', front: '#684e85' }
    const root = document.documentElement
    const isDark = root.classList.contains('dark')
    // Transparent back, accent-tinted front
    return isDark
      ? { back: '#00000000', front: '#9b7bb8' }  // lighter accent for dark mode
      : { back: '#00000000', front: '#684e85' }  // accent color
  }, [])

  // FullscreenOverlayBase handles portal, traffic lights, and ESC key
  return (
    <FullscreenOverlayBase
      isOpen={true}
      onClose={handleClose}
      className={cn("z-splash flex flex-col bg-background", className)}
    >
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        transition={overlayTransitionIn}
        className="flex flex-col flex-1"
      >
        {/* Dithering shader background */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 0.3 }}
          transition={overlayTransitionIn}
          className="absolute inset-0 pointer-events-none"
        >
          <Dithering
            colorBack={shaderColors.back}
            colorFront={shaderColors.front}
            shape="swirl"
            type="8x8"
            size={2}
            speed={reduceMotion ? 0 : 1}
            scale={1}
            width={dimensions.width}
            height={dimensions.height}
          />
        </motion.div>

        {/* Header with drag region and close button */}
        <header className="titlebar-drag-region relative h-[50px] shrink-0 flex items-center justify-end px-6">
          {/* Close button - explicitly no-drag */}
          <motion.button
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={overlayTransitionIn}
            onClick={(e) => {
              e.stopPropagation()
              handleClose()
            }}
            disabled={isCreating}
            className={cn(
              "titlebar-no-drag flex items-center justify-center p-2 rounded-[6px]",
              "bg-background shadow-minimal hover:bg-foreground-5",
              "text-muted-foreground hover:text-foreground",
              "transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-ring",
              "mr-[-8px] mt-2",
              isCreating && "opacity-50 cursor-not-allowed"
            )}
            aria-label={t('common.close')}
          >
            <X className="h-4 w-4" />
          </motion.button>
        </header>

        {/* Main content */}
        <motion.main
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={overlayTransitionIn}
          className="relative flex flex-1 items-center justify-center p-8"
        >
          {/* Step identity: forward and back are the same visible change of
              content instead of an unrelated snap, and the form values live in
              the parent so going back still restores them. */}
          <ContentSwap swapKey={step} className="flex w-full justify-center">
            {renderStep()}
          </ContentSwap>
        </motion.main>
      </motion.div>
    </FullscreenOverlayBase>
  )
}

