                        const enabledSources = sources.filter(s => optimisticSourceSlugs.includes(s.config.slug))
                        if (enabledSources.length === 1) return enabledSources[0].config.name
                        return t("chat.sourcesCount", { count: enabledSources.length })
                      })()
