                  const newSlugs = isEnabled
                    ? optimisticSourceSlugs.filter(currentSlug => currentSlug !== slug)
                    : [...optimisticSourceSlugs, slug]
                  setOptimisticSourceSlugs(newSlugs)
                  onSourcesChange?.(newSlugs)
