                                          onClick={(e) => {
                                            e.preventDefault()
                                            e.stopPropagation()
                                            handleToggleModelVision(conn.slug, modelId, !visionOn)
                                          }}
                                          onKeyDown={(e) => {
                                            if (e.key === 'Enter' || e.key === ' ') {
                                              e.preventDefault()
                                              e.stopPropagation()
                                              handleToggleModelVision(conn.slug, modelId, !visionOn)
                                            }
                                          }}
                                        >
                                          <ImageIcon className={cn(
                                            "h-3.5 w-3.5",
