                                  {isSelectedModel && (
                                    <Check className="h-3 w-3 text-foreground" />
                                  )}
                                </div>
                              </StyledDropdownMenuItem>
                            )
                          })}
                        </StyledDropdownMenuSubContent>
                      )}
                    </DropdownMenuSub>
                  )
                })
              ) : (
                /* Flat model list (single connection or session started) */
