                              </TooltipTrigger>
                              <TooltipContent>
                                {visionOn
                                  ? t('chat.modelPicker.supportsImagesOn')
                                  : t('chat.modelPicker.supportsImagesOff')}
                              </TooltipContent>
                            </Tooltip>
                          )}
                          {isSelected && (
                            <Check className="h-3 w-3 text-foreground" />
