                              <div className="font-medium text-sm">{t(nameKey)}</div>
                              <div className="text-xs text-muted-foreground">{t(descriptionKey)}</div>
                            </div>
                            {isSelected && (
                              <Check className="h-3 w-3 text-foreground shrink-0 ml-3" />
                            )}
