      setPlugins(result?.plugins ?? [])
      setPluginLoadErrors(result?.errors ?? [])
    } catch (err) {
      console.error('[Plugins] Failed to load plugins:', err)
      setPlugins([])
      setPluginLoadErrors([])
    }
  }, [])

  React.useEffect(() => {
