  const handleAutomationSelect = React.useCallback((automationId: string) => {
    // Preserve current automation filter when selecting an automation
    const type = isAutomationsNavigation(navState) ? navState.filter?.automationType : undefined
    navigate(routes.view.automations({ automationId, type }))
  }, [navState, navigate])

  // Focus zone management
  const { focusZone, focusNextZone, focusPreviousZone } = useFocusContext()

  // Register focus zones
  const { zoneRef: sidebarRef, isFocused: sidebarFocused } = useFocusZone({ zoneId: 'sidebar' })

  // Global keyboard shortcuts using centralized action registry
  // Actions are defined in @/actions/definitions.ts

  // Zone navigation - explicit keyboard intent, always move DOM focus
  useAction('nav.focusSidebar', () => {
    setIsSidebarAndNavigatorHidden(false)
    setIsSidebarVisible(true)
    requestAnimationFrame(() => focusZone('sidebar', { intent: 'keyboard' }))
  }, { enabled: () => !isAutoCompact })
  useAction('nav.focusNavigator', () => {
    if (!hasNavigator(navState)) return
    store.set(setExpandedWorkbenchItemAtom, null)
    setIsSidebarAndNavigatorHidden(false)
    if (isSessionsListVisible) setIsNavigatorVisible(true)
    else setIsManagementNavigatorVisible(true)
    requestAnimationFrame(() => focusZone('navigator', { intent: 'keyboard' }))
  }, { enabled: () => !isAutoCompact })
  useAction('nav.focusChat', () => {
    if (isWorkbenchFullWidth) {
      shellRef.current?.querySelector<HTMLElement>('[data-panel-role="content"]:not([inert]) button')?.focus()
    } else {
      focusZone('chat', { intent: 'keyboard' })
    }
  })

  // Tab navigation between zones
  useAction('nav.nextZone', () => {
    focusNextZone()
  }, { enabled: () => !document.querySelector('[role="dialog"]') })

  // Shift+Tab cycles permission mode through enabled modes (the textarea handles its own).
  const effectiveSessionId = primarySessionId ?? session.selected

  // Active session for bound content panels + TopBar session-bound affordances.
  // Sticky: follows the focused session, but holds the last focused session while
  // a non-session surface (projects/files/trajectory/terminal) is focused.
  const topBarActiveSessionId = useAtomValue(activeSessionIdAtom)

  // Focus chat input for the target session only.
  const focusChatInputForSession = useCallback((targetSessionId?: string | null) => {
    if (!targetSessionId) return
    dispatchFocusInputEvent({ sessionId: targetSessionId })
  }, [])

  useAction('chat.cyclePermissionMode', () => {
    if (effectiveSessionId) {
      const currentOptions = contextValue.sessionOptions.get(effectiveSessionId)
      const currentMode = currentOptions?.permissionMode ?? 'ask'
      // Cycle through enabled permission modes. An unavailable Guarded behaves as Ask, so it
      // stands in as Ask (never re-adding Execute the user left out of the cycle).
      const base = enabledModes.length >= 2 ? enabledModes : DEFAULT_PERMISSION_MODES
      const listed = base
        .map(mode => (mode === 'guarded' && !guardedModeAvailable ? 'ask' : mode))
        .filter((mode, index, all) => all.indexOf(mode) === index)
      const modes = listed.length >= 2 ? listed : (['safe', 'ask'] as PermissionMode[])
      const currentIndex = modes.indexOf(currentMode)
      // If current mode not in enabled list, jump to first enabled mode
      const nextIndex = currentIndex === -1 ? 0 : (currentIndex + 1) % modes.length
      const nextMode = modes[nextIndex]
      contextValue.onSessionOptionsChange(effectiveSessionId, { permissionMode: nextMode })
    }
  })

  const handleToggleSidebar = useCallback(() => {
    if (isSidebarAndNavigatorHidden) {
      setIsSidebarAndNavigatorHidden(false)
      setIsSidebarVisible(true)
      return
    }
    setIsSidebarVisible(v => !v)
  }, [isSidebarAndNavigatorHidden])

  // Sidebar toggle (CMD+B)
  useAction('view.toggleSidebar', handleToggleSidebar)

