// ---------------------------------------------------------------------------
// Subtask card (includes the required prompt)
// ---------------------------------------------------------------------------
function SubtaskCard({
  index,
  subtask,
  allSubtasks,
  groups,
  fallbackModel,
  modelToConnection,
  onChange,
  onRemove,
}: {
  index: number
  subtask: EditorSubtask
  /** Every row, so dependency chips resolve titles (incl. forward edges) and add-candidates can be cycle-filtered. */
  allSubtasks: EditorSubtask[]
  groups: KanbanModelProviderGroup[]
  /** Effective model shown when the node has no explicit one (it inherits the orchestrator default). */
  fallbackModel: string
  /** model id → connection slug, so picking a model pins the connection that serves it. */
  modelToConnection: Map<string, string>
  onChange: (patch: Partial<EditorSubtask>) => void
  onRemove: () => void
}) {
  const { t } = useTranslation()
  const titleByUid = new Map(allSubtasks.map((s) => [s.uid, s.title]))
  const depTitle = (depUid: string) => titleByUid.get(depUid) || t('tasks.untitledSubtask')
  const addDep = (depUid: string) => onChange({ dependsOn: [...subtask.dependsOn, depUid] })
  const removeDep = (depUid: string) => onChange({ dependsOn: subtask.dependsOn.filter((d) => d !== depUid) })
  // Candidates exclude self, already-selected, and any edge that would close a cycle.
  const candidates = allSubtasks.filter(
    (s) => !subtask.dependsOn.includes(s.uid) && canDependOn(allSubtasks, subtask.uid, s.uid),
  )
  return (
    <div className="group rounded-[10px] border border-border/70 bg-foreground/[0.015] p-3">
      <div className="flex items-start gap-2">
        <div className="mt-0.5 grid h-6 w-6 shrink-0 place-items-center rounded-full bg-indigo-500/10 text-[12px] font-bold text-indigo-500 dark:text-indigo-300">
          {index + 1}
        </div>
        <div className="min-w-0 flex-1">
          <input
            value={subtask.title}
            onChange={(e) => onChange({ title: e.target.value })}
            placeholder={t('tasks.subtaskTitlePlaceholder')}
            className="w-full bg-transparent text-[13.5px] font-semibold text-foreground outline-none placeholder:text-foreground/30"
          />
          <textarea
            value={subtask.prompt}
            onChange={(e) => onChange({ prompt: e.target.value })}
            rows={2}
            placeholder={t('tasks.promptPlaceholder')}
            className="mt-1.5 w-full resize-none rounded-md border border-border/60 bg-background px-2 py-1.5 text-[12px] leading-relaxed outline-none focus:border-foreground/25 field-sizing-content max-h-40"
          />
          <div className="mt-2 flex flex-wrap items-center gap-1.5">
            <ModelSelect
              value={subtask.model ?? fallbackModel}
              onChange={(id) => onChange({ model: id, llmConnection: modelToConnection.get(id) })}
              groups={groups}
              width={128}
              size="sm"
            />
            {subtask.dependsOn.map((depUid) => (
              <span
                key={depUid}
                className="inline-flex h-7 max-w-[168px] items-center gap-1 rounded-lg border border-border bg-foreground/[0.03] pl-2 pr-1 text-[11.5px] font-medium text-foreground/70"
              >
                <span className="truncate">{t('tasks.dependsOnLabel', { title: depTitle(depUid) })}</span>
                <button
                  type="button"
                  onClick={() => removeDep(depUid)}
                  aria-label={t('tasks.removeDependency')}
                  className="grid h-4 w-4 shrink-0 place-items-center rounded text-foreground/40 hover:bg-foreground/10 hover:text-red-500"
                >
                  <X className="h-3 w-3" strokeWidth={2.5} />
                </button>
              </span>
            ))}
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <SelectButton size="sm" style={{ width: 144 }}>
                  <span className="truncate text-foreground/70">
                    {subtask.dependsOn.length === 0 ? t('tasks.noDependencies') : t('tasks.addDependency')}
                  </span>
                </SelectButton>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="start" className="max-w-[240px]">
                {candidates.map((c) => (
                  <DropdownMenuItem key={c.uid} className="text-xs" onSelect={() => addDep(c.uid)}>
                    <span className="truncate">{c.title || t('tasks.untitledSubtask')}</span>
                  </DropdownMenuItem>
                ))}
                {candidates.length === 0 && (
                  <div className="px-2 py-1.5 text-[11px] text-foreground/40">{t('tasks.noAvailableSubtasks')}</div>
                )}
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </div>
        <button
          type="button"
          onClick={onRemove}
          aria-label={t('tasks.removeSubtask')}
          className="motion-interactive grid h-6 w-6 shrink-0 place-items-center rounded text-foreground/40 opacity-0 transition-[color,background-color,opacity,transform] hover:bg-foreground/10 hover:text-red-500 group-hover:opacity-100"
        >
          <Trash2 className="h-3.5 w-3.5" strokeWidth={2} />
        </button>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Task Editor
// ---------------------------------------------------------------------------
export interface TaskEditorProps {
  workspaceId: string
  /** What the editor points at: create-new or edit an existing tile. Defaults to create. */
  target?: TaskEditorTarget
  /** Return to the board. */
  onClose: () => void
  /** Jump to the underlying orchestrator chat session (edit mode only). */
  onOpenSession?: () => void
  /** Jump to a specific child/subtask session (used by Results "Open session" links). */
  onOpenChildSession?: (sessionId: string) => void
  /**
   * Fired after a successful CREATE (never for edit-mode saves) so the host can land the
   * user somewhere useful — e.g. the session list scoped to the task. `taskLabelId` is the
   * RESOLVED reserved-label id from tasks:create (may be 'task-2' after a name collision).
   */
  onCreated?: (created: { sessionId: string; taskLabelId?: string; projectId?: string }) => void
  /** Real provider→model groups (from the workspace's LLM connections). */
  modelGroups: KanbanModelProviderGroup[]
  /** model id → connection slug that serves it (so each node routes to the right backend). */
  modelToConnection: Map<string, string>
  /** Default model id. */
  defaultModel: string
}

export function TaskEditor({
  workspaceId,
  target = { mode: 'create' },
  onClose,
  onOpenSession,
  onOpenChildSession,
  onCreated,
  modelGroups,
  modelToConnection,
  defaultModel,
}: TaskEditorProps) {
  const { t } = useTranslation()
  const isEdit = target.mode === 'edit'
  // The slug to pin on save (edit mode). Undefined for create and for quick-add tiles with no slug;
  // in those cases buildSpec derives the id from the title.
  const editSlug = target.mode === 'edit' ? target.taskSlug : undefined
  const editSessionId = target.mode === 'edit' ? target.sessionId : undefined
  const groups = modelGroups
  const fallbackModel = (modelToConnection.has(defaultModel) ? defaultModel : undefined) || groups[0]?.models[0]?.id || ''
  const { projects } = useProjects(workspaceId)
  const [tab, setTab] = React.useState<Tab>('definition')
  const [mode, setMode] = React.useState<Mode>('manual')
  const [title, setTitle] = React.useState('')
  const [goal, setGoal] = React.useState('')
  const [acceptanceCriteria, setAcceptanceCriteria] = React.useState('')
  // Empty string = "use the runner default"; a number pins the spec's max_iterations.
  const [maxRepairs, setMaxRepairs] = React.useState('')
  // Create mode seeds the project from the board's active filter (so a new card stays
  // visible under that filter); edit mode starts empty and is prefilled from the spec below.
  const [projectId, setProjectId] = React.useState(target.mode === 'create' ? (target.initialProjectId ?? '') : '')
  const [orchModel, setOrchModel] = React.useState(fallbackModel)
  // Explicit connection serving the orch model; undefined lets buildSpec derive it from orchModel.
  // Preserved from the loaded spec so an authored connection isn't rewritten on save (round-trip).
  const [orchConnection, setOrchConnection] = React.useState<string | undefined>(undefined)
  // A catalog may arrive after the editor mounts. Only seed an empty selection;
  // never overwrite a user choice or an explicitly authored task model.
  React.useEffect(() => {
    if (!isEdit) setOrchModel(previous => previous || fallbackModel)
  }, [isEdit, fallbackModel])
  const hasAvailableModel = !!orchModel && modelToConnection.has(orchModel)
  // Task-family permission mode. New UI tasks default to autonomous (Execute/allow-all) so product
  // behavior is unchanged; edit mode prefills from the spec. Persisted to defaults.permissionMode so
  // subtask autonomy is explicit + visible, never a hidden runner default.
  const [permissionMode, setPermissionMode] = React.useState<TaskPermissionMode>('allow-all')
  // The task's project binding at load (edit mode). Floor for buildSpec so leaving the picker on
  // "No Project" can't silently drop a binding, and the gate for whether "No Project" is offered.
  const [boundProjectId, setBoundProjectId] = React.useState('')
  const [subtasks, setSubtasks] = React.useState<EditorSubtask[]>([])
  const [cwd, setCwd] = React.useState('')
  // Task-level sources (enabled on orchestrator + children) and skills (read as context
  // before each child works). Empty = leave workspace defaults / no skill preamble.
  const [sourceSlugs, setSourceSlugs] = React.useState<string[]>([])
  const [skillSlugs, setSkillSlugs] = React.useState<string[]>([])
  const [busy, setBusy] = React.useState(false)
  /*
   * When the work happens. This editor is the only create/edit surface for project
   * work now, so the plan the board, the calendar and the timeline all read has to
   * be editable here — and a create from the calendar arrives with it prefilled.
   */
  const [plan, setPlan] = React.useState<TaskPlanValue>(() => ({
    ...EMPTY_TASK_PLAN,
    ...(target.mode === 'create' ? target.initialPlan ?? {} : {}),
  }))
  const [planLoaded, setPlanLoaded] = React.useState(false)
  const { statuses } = useStatuses(workspaceId)
  const { items: planCandidates } = useWorkItems(workspaceId)
  const updatePlan = React.useCallback(
    (patch: Partial<TaskPlanValue>) => setPlan((previous) => ({ ...previous, ...patch })),
    [],
  )

  // Pickable catalogs from the active workspace (AppShell keeps these atoms populated).
  const workspaceSources = useAtomValue(sourcesAtom)
  const workspaceSkills = useAtomValue(skillsAtom)
  // Sources are the task-level pickable catalog (children inherit them); skills are
  // read as context before each child. Both feed the icon-rich selector fields below.
  const enabledSources = React.useMemo(
    () => workspaceSources.filter((s) => s.config.enabled !== false),
    [workspaceSources],
  )

  // Results tab (edit mode): storage-backed run outcome, loaded lazily on tab open / refresh.
  const [results, setResults] = React.useState<TaskResults | null>(null)
  const [resultsLoading, setResultsLoading] = React.useState(false)

  // Jotai store handle for one-shot reads (no subscription — the editor must not re-render
  // on every streaming metadata tick just to have read children once at open).
  const store = useStore()

  /**
   * The tile's quick-add children as editor rows, so hand-spawned subtasks show up (and get
   * adopted into the spec on save) instead of living only on the tile. Each row carries the
   * deterministic node id `qa-<sessionId>`; a child whose qa-id is already a spec node was
   * adopted by a previous save and is skipped. Conductor-owned children (`taskNodeId`) are
   * executions of spec nodes — the node row already represents them.
   */
  const collectQuickAddRows = React.useCallback(
    (adoptedNodeIds: ReadonlySet<string>): EditorSubtask[] => {
      if (!editSessionId) return []
      const metaMap = store.get(sessionMetaMapAtom)
      const children = [...metaMap.values()]
        .filter(
          (child) =>
            child.parentSessionId === editSessionId &&
            !child.taskNodeId &&
            !child.hidden &&
            !child.isArchived &&
            // Handoff continuations continue this task instead of being a unit of
            // its work; they must not be adopted as quick-add subtask rows.
            !isHandoffContinuation(child) &&
            !adoptedNodeIds.has(quickAddNodeId(child.id)),
        )
        .sort((a, b) => (a.createdAt ?? 0) - (b.createdAt ?? 0))
      return children.map((child) => {
        // Quick-add contract: the typed title is the session name AND the dispatch prompt. Preserve the
        // child's explicit model + connection (custom-routed children must not lose their backend).
        const title = child.name?.trim() || getSessionTitle(child)
        return quickAddChildToSubtask({ sessionId: child.id, title, model: child.model, llmConnection: child.llmConnection })
      })
    },
    // fallbackModel is stable for the life of an open editor (same reasoning as the prefill effect).
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [store, editSessionId],
  )

  // Edit-mode prefill: spec-backed tiles load their authored task.yaml; either way the tile's
  // quick-add children merge in as editable rows (adopted into the spec on the next save).
  React.useEffect(() => {
    if (target.mode !== 'edit') return
    let cancelled = false
    // The tile's existing project binding (spec-less quick-add tiles have no spec.project, so fall
    // back to the session's own projectId) — prefilled into the picker and kept as the buildSpec floor.
    const sessionMeta = editSessionId ? store.get(sessionMetaMapAtom).get(editSessionId) : undefined
    const sessionProjectId = sessionMeta?.projectId ?? ''
    if (target.taskSlug) {
      void window.electronAPI
        .getTask(workspaceId, target.taskSlug)
        .then((res) => {
          if (cancelled) return
          const spec = res.spec as
            | { title?: string; goal?: string; acceptance_criteria?: string; max_iterations?: number; project?: string; cwd?: string; sources?: string[]; skills?: string[]; defaults?: { model?: string; llmConnection?: string; permissionMode?: TaskPermissionMode }; nodes?: Array<{ id: string; title?: string; prompt?: string; model?: string; llmConnection?: string; depends_on?: string[] }> }
            | undefined
          if (!spec) return
          if (spec.title) setTitle(spec.title)
          if (spec.goal) setGoal(spec.goal)
          setAcceptanceCriteria(spec.acceptance_criteria ?? '')
          setMaxRepairs(spec.max_iterations != null ? String(spec.max_iterations) : '')
          // Bind from the spec, else the session's existing binding. Record it as the immutable floor.
          const bound = spec.project ?? sessionProjectId
          setProjectId(bound)
          setBoundProjectId(bound)
          if (spec.cwd) setCwd(spec.cwd)
          setSourceSlugs(spec.sources ?? [])
          setSkillSlugs(spec.skills ?? [])
          setOrchModel(spec.defaults?.model ?? sessionMeta?.model ?? fallbackModel)
          // Preserve the authored orchestrator connection + permission mode (round-trip, no silent rewrite).
          // Fall back to the session's actual mode so saving a bound tile can't silently escalate it.
          setOrchConnection(spec.defaults?.llmConnection ?? (spec.defaults?.model ? undefined : sessionMeta?.llmConnection))
          if (isTaskPermissionMode(spec.defaults?.permissionMode)) setPermissionMode(spec.defaults.permissionMode)
          else if (isTaskPermissionMode(sessionMeta?.permissionMode)) setPermissionMode(sessionMeta.permissionMode)
          const nodes = spec.nodes ?? []
          setSubtasks([
            ...specToSubtasks(nodes),
            ...collectQuickAddRows(new Set(nodes.map((n) => n.id))),
          ])
        })
        .catch(() => {})
    } else {
      if (target.initialTitle) setTitle(target.initialTitle)
      // A bound quick-add tile with no task.yaml: prefill + floor from the session's own state, so
      // saving it as a task neither drops its project nor silently changes its permission mode.
      setProjectId(sessionProjectId)
      setBoundProjectId(sessionProjectId)
      if (sessionMeta?.model) setOrchModel(sessionMeta.model)
      setOrchConnection(sessionMeta?.llmConnection)
      if (isTaskPermissionMode(sessionMeta?.permissionMode)) setPermissionMode(sessionMeta.permissionMode)
      setSubtasks(collectQuickAddRows(new Set()))
    }
    return () => {
      cancelled = true
    }
    // Prefill runs once per target identity; fallbackModel is stable enough for this load.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target.mode, editSessionId, editSlug, workspaceId])

  /*
   * Plan prefill. The plan lives on the session, which this editor reaches through
   * the same projection the board and the calendar read — so the values shown here
   * are exactly the ones a drag on the timeline or the calendar would have changed.
   */
  React.useEffect(() => {
    if (target.mode !== 'edit') {
      setPlanLoaded(true)
      return
    }
    let cancelled = false
    void window.electronAPI
      .listWorkItems(workspaceId)
      .then((items) => {
        if (cancelled) return
        // Edit mode replaces the whole plan: the row is the source of truth and the
        // state started empty. (Create mode never reaches here — its plan is seeded
        // from the gesture that opened the editor.)
        setPlan(taskPlanFromItem(items.find((item) => item.id === editSessionId)))
        setPlanLoaded(true)
      })
      .catch(() => { if (!cancelled) setPlanLoaded(true) })
    return () => { cancelled = true }
  }, [target.mode, editSessionId, workspaceId])

  const loadResults = React.useCallback(() => {
    if (!editSlug) return
    setResultsLoading(true)
    void window.electronAPI
      .getTaskResults(workspaceId, editSlug)
      .then((res) => setResults(res))
      .catch(() => {})
      .finally(() => setResultsLoading(false))
  }, [workspaceId, editSlug])

  // Load results when the Results tab is first opened (and there's a slug to read).
  React.useEffect(() => {
    if (tab === 'results' && editSlug && !results && !resultsLoading) loadResults()
  }, [tab, editSlug, results, resultsLoading, loadResults])

  // Async generate: tasks:generate returns the orchestrator session id immediately and the
  // authored spec arrives later via the onTaskGenerated push event. We track the pending
  // orchestrator id so the listener only reacts to *our* generation, plus a client-side
  // fallback timer so the spinner can't hang forever if the event never lands.
  const pendingGenRef = React.useRef<string | null>(null)
  const genTimeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(null)

  // A completed-but-unadopted generate orchestrator (hidden `taskDraft` session). Submit adopts it
  // in place — editing the authored spec is fine, since the draft is just the conductor orchestrator
  // and spec edits run on it. Discarded on regenerate/close; cleared once adopted so the unmount
  // cleanup never deletes a live orchestrator (#bug1).
  const generatedDraftRef = React.useRef<string | null>(null)

  const discardDraft = React.useCallback((sessionId: string) => {
    void window.electronAPI.deleteSession(sessionId).catch(() => {})
  }, [])

  const finishGenerate = React.useCallback(() => {
    pendingGenRef.current = null
    if (genTimeoutRef.current) {
      clearTimeout(genTimeoutRef.current)
      genTimeoutRef.current = null
    }
    setBusy(false)
  }, [])

  const project = projects.find((p) => p.config.id === projectId)

  const updateSubtask = (id: string, patch: Partial<EditorSubtask>) =>
    setSubtasks((prev) => prev.map((s) => (s.uid === id ? { ...s, ...patch } : s)))
  const removeSubtask = (id: string) =>
    setSubtasks((prev) =>
      prev.filter((s) => s.uid !== id).map((s) => ({ ...s, dependsOn: s.dependsOn.filter((d) => d !== id) })),
    )
  const addSubtask = () =>
    setSubtasks((prev) => {
      const last = prev[prev.length - 1]
      // No explicit model → the new subtask inherits the orchestrator default (the picker still shows
      // that effective model). Picking a model in the row makes it explicit.
      return [...prev, { uid: uid(), title: '', prompt: '', dependsOn: last ? [last.uid] : [] }]
    })

  // Generate mode: the persistent orchestrator session AUTHORS the task.yaml from the goal,
  // then we drop into Manual so the user reviews/edits the AI's plan before running — the
  // generate → edit → run loop (#2 / architecture §3a).
  // Apply a generated spec to the editor (or surface its failure). Runs from the
  // onTaskGenerated listener once the orchestrator finishes authoring.
  const applyGeneratedSpec = React.useCallback(
    (res: { orchestratorSessionId: string; spec?: unknown; validation: { valid: boolean; errors: Array<{ path: string; message: string }> }; error?: string }) => {
      if (res.error) {
        // The hidden draft orchestrator can't produce a usable spec — discard it so it doesn't
        // linger off-board.
        discardDraft(res.orchestratorSessionId)
        toast.error(t('tasks.toastCreateFailed'), { description: res.error })
        return
      }
      const spec = res.spec as
        | { title?: string; goal?: string; acceptance_criteria?: string; max_iterations?: number; defaults?: { model?: string; llmConnection?: string; permissionMode?: TaskPermissionMode }; nodes?: Array<{ id: string; title?: string; prompt?: string; model?: string; llmConnection?: string; depends_on?: string[] }> }
        | undefined
      if (!spec || !res.validation.valid) {
        discardDraft(res.orchestratorSessionId)
        const first = res.validation.errors[0]
        toast.error(t('tasks.toastInvalid'), { description: first ? `${first.path}: ${first.message}` : undefined })
        return
      }
      if (spec.title) setTitle(spec.title)
      if (spec.goal) setGoal(spec.goal)
      setAcceptanceCriteria(spec.acceptance_criteria ?? '')
      setMaxRepairs(spec.max_iterations != null ? String(spec.max_iterations) : '')
      // Adopt the generator's routing only when it explicitly authored it — don't wipe the user's picks.
      if (spec.defaults?.model) setOrchModel(spec.defaults.model)
      if (spec.defaults?.llmConnection) setOrchConnection(spec.defaults.llmConnection)
      if (spec.defaults?.permissionMode) setPermissionMode(spec.defaults.permissionMode)
      setSubtasks(specToSubtasks(spec.nodes ?? []))
      setMode('manual')
      // Record the draft as adoptable: submit reuses it in place (edits are fine to run on it).
      generatedDraftRef.current = res.orchestratorSessionId
      // No success toast here: switching to Manual mode and populating the Subtasks panel is
      // the visible signal. A top-right toast would also overlap the editor's top-right
      // Cancel/Create/Create & Run buttons and swallow their clicks.
    },
    [t, fallbackModel, discardDraft],
  )

  // Subscribe once for async generate results; ignore events for other generations/sessions.
  React.useEffect(() => {
    const off = window.electronAPI.onTaskGenerated((_wsId, res) => {
      if (res.orchestratorSessionId !== pendingGenRef.current) return
      finishGenerate()
      applyGeneratedSpec(res)
    })
    return off
  }, [finishGenerate, applyGeneratedSpec])

  // Clear any pending fallback timer on unmount, and discard a draft orchestrator that was never
  // adopted (editor closed/cancelled after generating). Best-effort — a dropped delete only leaves
  // a hidden draft, never a visible board tile.
  React.useEffect(() => () => {
    if (genTimeoutRef.current) clearTimeout(genTimeoutRef.current)
    const draftId = generatedDraftRef.current
    if (draftId) {
      generatedDraftRef.current = null
      void window.electronAPI.deleteSession(draftId).catch(() => {})
    }
  }, [])

  async function generatePlan() {
    if (!hasAvailableModel) return
    const g = goal.trim() || title.trim()
    if (!g) {
      toast.error(t('tasks.toastNeedTitle'))
      return
    }
    // Regenerating abandons any previously authored draft — discard it before minting a new one.
    if (generatedDraftRef.current) {
      discardDraft(generatedDraftRef.current)
      generatedDraftRef.current = null
    }
    setBusy(true)
    try {
      const ack = await window.electronAPI.generateTask(workspaceId, {
        goal: g,
        title: title.trim() || undefined,
        model: orchModel,
        // Route the authoring turn through the preserved connection (falls back to the model's default),
        // and give the draft the project context + sources + autonomy it will author against — else a
        // pi/* model produces nothing and the draft runs at the workspace-default permission mode.
        llmConnection: orchConnection ?? modelToConnection.get(orchModel),
        permissionMode,
        ...(projectId ? { projectId } : {}),
        ...(sourceSlugs.length ? { enabledSourceSlugs: sourceSlugs } : {}),
        cwd: cwd.trim() || undefined,
      })
      // Authoring continues on the server; the spec arrives via onTaskGenerated. Keep busy until
      // then, with a fallback timer that releases the spinner if the event never lands.
      pendingGenRef.current = ack.orchestratorSessionId
      if (genTimeoutRef.current) clearTimeout(genTimeoutRef.current)
      genTimeoutRef.current = setTimeout(() => {
        if (pendingGenRef.current !== ack.orchestratorSessionId) return
        finishGenerate()
        toast.error(t('tasks.toastCreateFailed'), { description: t('tasks.toastGenerateTimeout') })
      }, GENERATE_CLIENT_TIMEOUT_MS)
    } catch (err) {
      finishGenerate()
      toast.error(t('tasks.toastCreateFailed'), { description: err instanceof Error ? err.message : String(err) })
    }
  }

  // Create the task (write task.yaml + orchestrator session). When `run` is true, also start a
  // run; otherwise the task tile just lands on the board in ToDo for the user to run later.
  async function submit(run: boolean) {
    if (run && !hasAvailableModel) return
    if (!title.trim()) {
      toast.error(t('tasks.toastNeedTitle'))
      return
    }
    if (subtasks.length === 0) {
      toast.error(t('tasks.toastNeedSubtask'))
      return
    }
    if (subtasks.some((s) => !s.prompt.trim())) {
      toast.error(t('tasks.toastNeedPrompt'))
      return
    }
    // Edit mode pins the existing slug so the title can change without forking a new task folder
    // and orphaning the bound orchestrator session.
    const spec = buildSpec(
      {
        title,
        goal,
        acceptanceCriteria,
        maxRepairs: maxRepairs.trim() === '' ? undefined : Number(maxRepairs),
        projectId,
        orchModel,
        orchConnection,
        permissionMode,
        boundProjectId,
        subtasks,
        cwd,
        sourceSlugs,
        skillSlugs,
        fixedId: editSlug,
      },
      modelToConnection,
    )
    const yaml = JSON.stringify(spec, null, 2) // JSON is a valid YAML subset
    // Adopt the generate draft in place whenever we have one — spec edits run fine on the draft
    // orchestrator, so there's no need to mint a fresh session.
    const draftId = generatedDraftRef.current
    setBusy(true)
    try {
      // Edit mode binds the authored spec onto the tile's existing session; create mode reuses
      // a generate draft if present, else mints a fresh orchestrator.
      const created = await window.electronAPI.createTask(workspaceId, {
        yaml,
        // The plan travels with the spec on every path, so a create from the calendar
        // lands on the day the user drew rather than nowhere.
        planning: taskPlanningInput(plan),
        ...(isEdit && editSessionId
          ? { attachToExistingSession: editSessionId }
          : { orchestratorSessionId: draftId ?? undefined }),
      })
      if (!created.validation.valid) {
        const first = created.validation.errors[0]
        toast.error(t('tasks.toastInvalid'), { description: first ? `${first.path}: ${first.message}` : undefined })
        return
      }
      // Resolve the draft: if the server reused it, it's now a live orchestrator — stop tracking it.
      // If it minted a fresh session instead (draft gone server-side), discard the orphan.
      if (draftId) {
        if (created.orchestratorSessionId !== draftId) discardDraft(draftId)
        generatedDraftRef.current = null
      }
      // After a successful CREATE, hand off to the host so it can land the user on the
      // task-scoped session list (edit-mode saves stay on the board).
      const notifyCreated = () => {
        if (isEdit) return
        onCreated?.({
          sessionId: created.orchestratorSessionId,
          taskLabelId: created.taskLabelId,
          projectId: projectId || undefined,
        })
      }
      if (!run) {
        toast.success(t('tasks.toastCreated'), { description: t('tasks.toastCreatedDesc', { slug: created.slug }) })
        onClose()
        notifyCreated()
        return
      }
      const runResult = await window.electronAPI.runTask(workspaceId, {
        slug: created.slug,
        orchestratorSessionId: created.orchestratorSessionId,
      })
      toast.success(t('tasks.toastStarted'), {
        description: t('tasks.toastStartedDesc', { slug: created.slug, runId: runResult.runId, count: runResult.nodes.length }),
      })
      onClose()
      notifyCreated()
    } catch (err) {
      toast.error(t('tasks.toastCreateFailed'), { description: err instanceof Error ? err.message : String(err) })
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className="flex h-full flex-col gap-3 bg-background p-3 text-foreground">
      {/* Header */}
      <div className="flex items-center gap-2.5 rounded-xl border border-border bg-card px-3 py-2.5 shadow-minimal">
        <Btn variant="ghost" className="px-2" onClick={onClose}>
          <ChevronLeft className="h-4 w-4" strokeWidth={2} /> {t('contentPanel.button.kanban')}
        </Btn>
        <span className="text-foreground/25">/</span>
        <span className="text-sm font-semibold">{isEdit ? t('tasks.editTask') : t('kanban.newTask')}</span>

        {/* Definition / Results tabs — edit mode only (results need a backing task to read). */}
        {isEdit && (
          <div className="ml-3 inline-flex rounded-[9px] bg-foreground/[0.05] p-0.5">
            {(['definition', 'results'] as Tab[]).map((tb) => (
              <button
                key={tb}
                onClick={() => setTab(tb)}
                className={cn(
                  'rounded-[7px] px-3 py-1 text-[12.5px] font-semibold transition-colors',
                  tab === tb ? 'bg-card text-foreground shadow-minimal' : 'text-foreground/55 hover:text-foreground/80',
                )}
              >
                {tb === 'definition' ? t('tasks.tabDefinition') : t('tasks.tabResults')}
              </button>
            ))}
          </div>
        )}

        <div className="ml-auto flex items-center gap-2">
          {isEdit && onOpenSession && (
            <Btn variant="secondary" onClick={onOpenSession} disabled={busy}>
              <ExternalLink className="h-3.5 w-3.5" strokeWidth={2} /> {t('tasks.openSession')}
            </Btn>
          )}
          {tab === 'definition' && (
            <>
              <Btn variant="secondary" onClick={onClose} disabled={busy}>
                {t('common.cancel')}
              </Btn>
              <Btn variant="secondary" onClick={() => submit(false)} disabled={busy}>
                {isEdit ? t('common.save') : t('common.create')}
              </Btn>
              <Btn variant="primary" onClick={() => submit(true)} disabled={busy || !hasAvailableModel}>
                {busy ? <Spinner /> : <Sparkles className="h-3.5 w-3.5" strokeWidth={2.5} />}
                {busy ? t('tasks.starting') : isEdit ? t('tasks.saveAndRun') : t('tasks.createAndRun')}
              </Btn>
            </>
          )}
          {tab === 'results' && (
            <Btn variant="secondary" onClick={loadResults} disabled={resultsLoading}>
              {resultsLoading ? <Spinner /> : <RefreshCw className="h-3.5 w-3.5" strokeWidth={2} />} {t('common.refresh')}
            </Btn>
          )}
        </div>
      </div>

      {tab === 'results' ? (
        <ResultsPanel
          results={results}
          loading={resultsLoading}
          onOpenChildSession={onOpenChildSession}
        />
      ) : (
      /* Body */
      <div className="grid min-h-0 flex-1 grid-cols-[minmax(360px,2fr)_3fr] gap-3">
        {/* Left — definition */}
        <div className="flex min-h-0 flex-col gap-4 overflow-y-auto rounded-xl border border-border bg-card p-4 shadow-minimal">
          <div className="text-[15px] font-bold">{t('tasks.definition')}</div>

          <div className="inline-flex w-fit rounded-[9px] bg-foreground/[0.05] p-0.5">
            {(['manual', 'generate'] as Mode[]).map((m) => (
              <button
                key={m}
                onClick={() => setMode(m)}
                className={cn(
                  'inline-flex items-center gap-1.5 rounded-[7px] px-3 py-1.5 text-[12.5px] font-semibold transition-colors',
                  mode === m ? 'bg-card text-foreground shadow-minimal' : 'text-foreground/55 hover:text-foreground/80',
                )}
              >
                {m === 'generate' && <Sparkles className="h-3.5 w-3.5" strokeWidth={2.5} />}
                {m === 'generate' ? t('tasks.modeGenerate') : t('tasks.modeManual')}
              </button>
            ))}
          </div>

          <div>
            <div className="mb-1.5 text-[12px] font-semibold text-foreground/55">{t('tasks.title')}</div>
            <input
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder={t('tasks.titlePlaceholder')}
              className="w-full rounded-lg border border-border bg-background px-3 py-2 text-[13.5px] font-semibold outline-none focus:border-foreground/25"
            />
          </div>

          <div>
            <div className="mb-1.5 flex items-baseline justify-between">
              <span className="text-[12px] font-semibold text-foreground/55">{t('tasks.goal')}</span>
              <span className="text-[10.5px] text-foreground/35">{t('tasks.goalHint')}</span>
            </div>
            <textarea
              value={goal}
              onChange={(e) => setGoal(e.target.value)}
              rows={4}
              placeholder={t('tasks.goalPlaceholder')}
              className="w-full resize-none rounded-lg border border-border bg-background px-3 py-2 text-[12.5px] leading-relaxed outline-none focus:border-foreground/25 field-sizing-content max-h-48"
            />
          </div>

          <div>
            <div className="mb-1.5 flex items-baseline justify-between">
              <span className="text-[12px] font-semibold text-foreground/55">{t('tasks.acceptanceCriteria')}</span>
              <span className="text-[10.5px] text-foreground/35">{t('tasks.acceptanceCriteriaHint')}</span>
            </div>
            <textarea
              value={acceptanceCriteria}
              onChange={(e) => setAcceptanceCriteria(e.target.value)}
              rows={3}
              placeholder={t('tasks.acceptanceCriteriaPlaceholder')}
              className="w-full resize-none rounded-lg border border-border bg-background px-3 py-2 text-[12.5px] leading-relaxed outline-none focus:border-foreground/25 field-sizing-content max-h-48"
            />
          </div>

          {/*
            When the work happens. The two pages this editor replaced owned these
            fields — status, progress, milestone, parent, dependencies and the plan
            dates — and a session is the same row for all three projections, so they
            belong here rather than disappearing with the pages.
          */}
          <TaskPlanPanel
            value={plan}
            onChange={updatePlan}
            statuses={statuses}
            workItems={planCandidates}
            selfId={editSessionId}
            disabled={busy || !planLoaded}
          />

          <div className="flex flex-col gap-3">
            <FieldRow label={t('tasks.project')}>
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <SelectButton style={{ width: 168 }}>
                    <span className="truncate">{project ? project.config.name : t('tasks.noProject')}</span>
                  </SelectButton>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="min-w-[160px]">
                  {/* "No Project" clears the binding — only offered when NOT already bound. The backend
                      never unbinds on save, and buildSpec floors a blank pick to the existing project,
                      so showing it for a bound task would be a no-op that implies clearing works. */}
                  {!boundProjectId && (
                    <DropdownMenuItem className="text-xs" onSelect={() => setProjectId('')}>
                      {t('tasks.noProject')}
                      {!projectId && <Check className="ml-auto h-3.5 w-3.5" strokeWidth={2} />}
                    </DropdownMenuItem>
                  )}
                  {projects.map((p) => (
                    <DropdownMenuItem key={p.config.id} className="text-xs" onSelect={() => setProjectId(p.config.id)}>
                      <span className="truncate">{p.config.name}</span>
                      {projectId === p.config.id && <Check className="ml-auto h-3.5 w-3.5 shrink-0" strokeWidth={2} />}
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>
            </FieldRow>

            <FieldRow label={t('tasks.orchestratorModel')}>
              <ModelSelect
                value={orchModel}
                onChange={(m) => {
                  // Keep the connection in step with the model: an unchanged model preserves the loaded
                  // (possibly custom) connection; changing it re-routes to the new model's connection.
                  setOrchModel(m)
                  setOrchConnection(modelToConnection.get(m))
                }}
                groups={groups}
              />
            </FieldRow>

            <FieldRow label={t('tasks.permissionMode')}>
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <SelectButton style={{ width: 168 }}>
                    <span className="truncate">{t(`mode.${permissionMode}`)}</span>
                  </SelectButton>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="min-w-[160px]">
                  {(['allow-all', 'ask', 'safe'] as const).map((m) => (
                    <DropdownMenuItem key={m} className="text-xs" onSelect={() => setPermissionMode(m)}>
                      <span className="truncate">{t(`mode.${m}`)}</span>
                      {permissionMode === m && <Check className="ml-auto h-3.5 w-3.5 shrink-0" strokeWidth={2} />}
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>
            </FieldRow>

            {enabledSources.length > 0 && (
              <FieldRow label={t('tasks.sources')}>
                <SourcesField
                  sources={enabledSources}
                  values={sourceSlugs}
                  onChange={setSourceSlugs}
                  title={t('tasks.sourcesHint')}
                />
              </FieldRow>
            )}

            {workspaceSkills.length > 0 && (
              <FieldRow label={t('tasks.skills')}>
                <SkillsField
                  skills={workspaceSkills}
                  values={skillSlugs}
                  onChange={setSkillSlugs}
                  workspaceId={workspaceId}
                  title={t('tasks.skillsHint')}
                />
              </FieldRow>
            )}

            <FieldRow label={t('tasks.workingDirectory')}>
              <FolderField cwd={cwd} onChange={setCwd} workspaceId={workspaceId} />
            </FieldRow>

            <FieldRow label={t('tasks.maxRepairs')}>
              <input
                type="number"
                inputMode="numeric"
                min={0}
                max={MAX_REPAIR_ATTEMPTS_CAP}
                value={maxRepairs}
                onChange={(e) => setMaxRepairs(e.target.value)}
                placeholder={String(DEFAULT_REPAIR_ATTEMPTS)}
                title={t('tasks.maxRepairsHint')}
                className="h-8 w-[88px] rounded-lg border border-border bg-background px-2.5 text-right text-[12.5px] tabular-nums outline-none focus:border-foreground/25 placeholder:text-foreground/30"
              />
            </FieldRow>
          </div>
        </div>

        {/* Right — subtasks (Manual) / scaffold (Generate) */}
        <div className="flex min-h-0 flex-col rounded-xl border border-border bg-card shadow-minimal">
          {mode === 'manual' ? (
            <>
              <div className="flex shrink-0 items-center gap-2 px-4 pt-4">
                <span className="text-[15px] font-bold">{t('kanban.subtasks')}</span>
                <span className="grid h-5 min-w-[20px] place-items-center rounded-full bg-foreground/[0.06] px-1.5 text-[11px] font-bold text-foreground/55">
                  {subtasks.length}
                </span>
                <Btn variant="secondary" className="ml-auto h-7 px-2.5 text-[12px]" onClick={addSubtask}>
                  <Plus className="h-3.5 w-3.5" strokeWidth={2.5} /> {t('kanban.addSubtask')}
                </Btn>
              </div>

              <div className="flex min-h-0 flex-1 flex-col gap-2.5 overflow-y-auto p-4">
                {subtasks.map((st, i) => (
                  <SubtaskCard
                    key={st.uid}
                    index={i}
                    subtask={st}
                    allSubtasks={subtasks}
                    groups={groups}
                    fallbackModel={orchModel || fallbackModel}
                    modelToConnection={modelToConnection}
                    onChange={(patch) => updateSubtask(st.uid, patch)}
                    onRemove={() => removeSubtask(st.uid)}
                  />
                ))}
                {subtasks.length === 0 && (
                  <button
                    onClick={addSubtask}
                    className="flex w-full items-center justify-center gap-1.5 rounded-[10px] border border-dashed border-border py-2.5 text-[12.5px] font-semibold text-foreground/40 transition-colors hover:border-foreground/30 hover:text-foreground/60"
                  >
                    <Plus className="h-3.5 w-3.5" strokeWidth={2.5} /> {t('tasks.addFirstSubtask')}
                  </button>
                )}
              </div>

              <div className="shrink-0 border-t border-border/60 px-4 py-2.5 text-[10.5px] text-foreground/40">
                {t('tasks.subtaskFooter')}
              </div>
            </>
          ) : busy ? (
            <div className="flex min-h-full flex-col gap-3 p-4">
              <div className="flex items-center gap-2 text-[13px] font-semibold text-foreground/70">
                <LoadingIndicator label={t('tasks.generatingTitle')} showElapsed />
              </div>
              <p className="text-[12px] leading-relaxed text-foreground/50">{t('tasks.generatingBody')}</p>
              {/* Skeleton subtask cards: the long author wait reads as "drafting nodes", not frozen. */}
              {[0, 1, 2].map((i) => (
                <div key={i} className="animate-pulse rounded-[10px] border border-border/70 bg-foreground/[0.015] p-3">
                  <div className="flex items-start gap-2">
                    <div className="mt-0.5 h-6 w-6 shrink-0 rounded-full bg-foreground/[0.06]" />
                    <div className="min-w-0 flex-1 space-y-2">
                      <div className="h-3.5 w-1/2 rounded bg-foreground/[0.06]" />
                      <div className="h-8 w-full rounded bg-foreground/[0.04]" />
                      <div className="flex gap-1.5">
                        <div className="h-7 w-[128px] rounded-lg bg-foreground/[0.05]" />
                        <div className="h-7 w-[144px] rounded-lg bg-foreground/[0.05]" />
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="flex min-h-full flex-col items-center justify-center gap-3 px-6 py-8 text-center">
              <div className="grid h-12 w-12 place-items-center rounded-full bg-indigo-500/10 text-indigo-500 dark:text-indigo-300">
                <Sparkles className="h-6 w-6" strokeWidth={2} />
              </div>
              <div className="text-[14px] font-bold">{t('tasks.generatePlan')}</div>
              <p className="max-w-[360px] text-[12.5px] leading-relaxed text-foreground/55">{t('tasks.generateBody')}</p>
              <Btn variant="primary" onClick={generatePlan} disabled={busy || !hasAvailableModel}>
                <Sparkles className="h-3.5 w-3.5" strokeWidth={2.5} /> {t('tasks.generatePlan')}
              </Btn>
              <span className="text-[11px] text-foreground/40">{t('tasks.generateHint')}</span>
            </div>
          )}
        </div>
      </div>
      )}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Results panel — storage-backed run outcome (verdict + per-node output).
// ---------------------------------------------------------------------------
function ResultsPanel({
  results,
  loading,
  onOpenChildSession,
}: {
  results: TaskResults | null
  loading: boolean
  onOpenChildSession?: (sessionId: string) => void
}) {
  const { t } = useTranslation()

  if (loading && !results) {
    return (
      <div className="flex min-h-0 flex-1 items-center justify-center rounded-xl border border-border bg-card text-foreground/50 shadow-minimal">
        <Spinner className="text-lg" />
      </div>
    )
  }

  if (!results || !results.runId || results.nodes.length === 0) {
    return (
      <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-2 rounded-xl border border-border bg-card px-6 text-center text-foreground/50 shadow-minimal">
        <CircleSlash className="h-6 w-6 text-foreground/30" strokeWidth={2} />
        <p className="text-[12.5px]">{t('tasks.resultsEmpty')}</p>
      </div>
    )
  }

  const verdict = results.verdict
  const verdicts = results.verdicts ?? (verdict ? [verdict] : [])
  const repair = results.repair
  return (
    <div className="flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto rounded-xl border border-border bg-card p-4 shadow-minimal">
      {results.acceptanceCriteria && (
        <div className="rounded-[10px] border border-border/70 bg-foreground/[0.015] px-3 py-2.5">
          <div className="text-[11px] font-bold uppercase tracking-wide text-foreground/45">{t('tasks.acceptanceCriteria')}</div>
          <p className="mt-1 text-[12px] leading-relaxed text-foreground/70">{results.acceptanceCriteria}</p>
        </div>
      )}

      {verdict && (
        <div
          className={cn(
            'flex items-start gap-2.5 rounded-[10px] border px-3 py-2.5',
            verdict.result === 'pass'
              ? 'border-emerald-500/30 bg-emerald-500/[0.06]'
              : verdict.result === 'fail'
                ? 'border-red-500/30 bg-red-500/[0.06]'
                : 'border-border bg-foreground/[0.03]',
          )}
        >
          {verdict.result === 'pass' ? (
            <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-emerald-500" strokeWidth={2.5} />
          ) : verdict.result === 'fail' ? (
            <XCircle className="mt-0.5 h-4 w-4 shrink-0 text-red-500" strokeWidth={2.5} />
          ) : (
            <CircleSlash className="mt-0.5 h-4 w-4 shrink-0 text-foreground/40" strokeWidth={2.5} />
          )}
          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-2">
              <span className="text-[13px] font-bold">
                {verdict.result === 'pass' ? t('tasks.verdictPass') : verdict.result === 'fail' ? t('tasks.verdictFail') : t('tasks.verdictUnparsed')}
              </span>
              {repair && (
                <span className="ml-auto shrink-0 rounded-full bg-foreground/[0.06] px-2 py-0.5 text-[10.5px] font-bold text-foreground/55">
                  {t('tasks.repairAttempt', { used: repair.used, max: repair.max })}
                </span>
              )}
            </div>
            {verdict.via === 'decision' && (
              <p className="mt-0.5 text-[11px] text-foreground/45">
                {t('tasks.verdictInferred', { confidence: Math.round((verdict.confidence ?? 0) * 100) })}
              </p>
            )}
            {verdict.reason && <p className="mt-0.5 text-[12px] leading-relaxed text-foreground/65">{verdict.reason}</p>}
            {verdict.nodes && verdict.nodes.length > 0 && (
              <p className="mt-1 text-[11px] text-foreground/45">{t('tasks.repairNodes', { nodes: verdict.nodes.join(', ') })}</p>
            )}
          </div>
        </div>
      )}

      {verdicts.length > 1 && (
        <div className="rounded-[10px] border border-border/70 bg-foreground/[0.015] px-3 py-2.5">
          <div className="mb-1.5 text-[11px] font-bold uppercase tracking-wide text-foreground/45">{t('tasks.verdictHistory')}</div>
          <div className="flex flex-col gap-1">
            {verdicts.map((v, i) => (
              <div key={i} className="flex items-start gap-2 text-[11.5px]">
                {v.result === 'pass' ? (
                  <CheckCircle2 className="mt-0.5 h-3.5 w-3.5 shrink-0 text-emerald-500" strokeWidth={2.5} />
                ) : v.result === 'fail' ? (
                  <XCircle className="mt-0.5 h-3.5 w-3.5 shrink-0 text-red-500" strokeWidth={2.5} />
                ) : (
                  <CircleSlash className="mt-0.5 h-3.5 w-3.5 shrink-0 text-foreground/40" strokeWidth={2.5} />
                )}
                <span className="min-w-0 flex-1 text-foreground/60">
                  {v.reason || (v.result === 'pass' ? t('tasks.verdictPass') : v.result === 'fail' ? t('tasks.verdictFail') : t('tasks.verdictUnparsed'))}
                </span>
              </div>
            ))}
          </div>
        </div>
      )}

      {results.nodes.map((node) => {
        const pill = resolveNodeStatePill(node.state)
        return (
        <div key={node.id} className="rounded-[10px] border border-border/70 bg-foreground/[0.015] p-3">
          <div className="flex items-center gap-2">
            <span className="min-w-0 flex-1 truncate text-[13px] font-semibold">{node.title}</span>
            <span className={cn('shrink-0 rounded-full border px-2 py-0.5 text-[10.5px] font-bold', pill.className)}>
              {pill.labelKey ? t(pill.labelKey) : node.state}
            </span>
            {node.sessionId && onOpenChildSession && (
              <button
                type="button"
                onClick={() => onOpenChildSession(node.sessionId!)}
                className="inline-flex shrink-0 items-center gap-1 rounded text-[11.5px] font-semibold text-indigo-500 hover:underline dark:text-indigo-300"
              >
                <ExternalLink className="h-3 w-3" strokeWidth={2.5} /> {t('tasks.openSession')}
              </button>
            )}
          </div>
          {node.output ? (
            <div className="mt-2 max-h-72 overflow-y-auto rounded-md border border-border/50 bg-background px-3 py-2 text-[12px] leading-relaxed">
              <Markdown>{node.output}</Markdown>
            </div>
          ) : (
            <p className="mt-1.5 text-[11.5px] text-foreground/40">{t('tasks.noOutput')}</p>
          )}
        </div>
        )
      })}
    </div>
  )
}

/**
 * useEntityListInteractions — Convenience hook that wires together:
 * - useRovingTabIndex (keyboard navigation)
 * - useMultiSelect (pure selection state)
 * - Optional search filtering
 *
 * Returns props to spread onto EntityList and EntityRow.
 *
 * NOTE: Does NOT include useFocusZone — that requires app-level FocusContext.
 * Consumers who need zone integration compose it externally (see SessionList).
 */

import { useState, useCallback, useMemo, useRef } from 'react'
import { useRovingTabIndex } from '@/hooks/keyboard'
import * as MultiSelect from '@/hooks/useMultiSelect'

// ============================================================================
// Types
// ============================================================================

export interface UseEntityListInteractionsOptions<T> {
  /** List of items (pre-filtering) */
  items: T[]
  /** Unique ID extractor */
  getId: (item: T) => string

  /** Keyboard navigation (opt-in) */
  keyboard?: {
    /** Called when Enter/Space is pressed on the active item */
    onActivate?: (item: T, index: number) => void
    /** Called when arrow keys move to a new item */
    onNavigate?: (item: T, index: number) => void
    /** Whether keyboard navigation is enabled (default: true) */
    enabled?: boolean
    /** Keep DOM focus elsewhere (e.g. search input) while navigating (default: false) */
    virtualFocus?: boolean
  }

  /** Multi-select (opt-in — set to true to enable) */
  multiSelect?: boolean

  /** Search filtering (opt-in) */
  search?: {
    /** Current search query */
    query: string
    /** Filter function — return true to include the item */
    fn: (item: T, query: string) => boolean
  }

  /**
   * External selection store (opt-in).
   * When provided, the hook uses this instead of its own internal useState.
   * This enables atom-backed selection shared with other components (e.g. Jotai).
   *
   * @example
   * const [state, setState] = useAtom(sessionSelectionAtom)
   * const interactions = useEntityListInteractions({ ..., selectionStore: { state, setState } })
   */
  selectionStore?: {
    state: MultiSelect.MultiSelectState
    setState: (fn: MultiSelect.MultiSelectState | ((prev: MultiSelect.MultiSelectState) => MultiSelect.MultiSelectState)) => void
  }

  /**
   * Override which item ID is considered "selected" for highlighting.
   * When provided, `getRowProps` uses this instead of `selectionState.selected`.
   * Used when structural navigation owns selection independently of the list store.
   */
  selectedIdOverride?: string | null
}

export interface EntityListInteractions<T> {
  /** Filtered items (after search). Use this as EntityList's items prop. */
  items: T[]

  /** Props to spread on EntityList */
  listProps: {
    containerRef?: React.Ref<HTMLDivElement>
    containerProps: Record<string, string>
  }

  /** Get props to spread on each EntityRow */
  getRowProps: (item: T, index: number) => {
    buttonProps: Record<string, unknown>
    isSelected: boolean
    isInMultiSelect: boolean
    onMouseDown: (e: React.MouseEvent) => void
  }

  /** Keyboard state */
  keyboard: {
    activeIndex: number
    setActiveIndex: (index: number) => void
    focusActiveItem: () => void
  }

  /** Props to spread on a search <input> — forwards ArrowDown/Up to the list */
  searchInputProps: {
    onKeyDown: (e: React.KeyboardEvent<HTMLInputElement>) => void
  }

  /** Selection state (only meaningful when multiSelect is enabled) */
  selection: {
    state: MultiSelect.MultiSelectState
    isMultiSelectActive: boolean
    selectedIds: Set<string>
    toggle: (id: string, index: number) => void
    range: (toIndex: number) => void
    selectAll: () => void
    clear: () => void
  }
}

// ============================================================================
// Hook
// ============================================================================

export function useEntityListInteractions<T>({
  items: rawItems,
  getId,
  keyboard: keyboardOpts,
  multiSelect: multiSelectEnabled = false,
  search,
  selectionStore,
  selectedIdOverride,
}: UseEntityListInteractionsOptions<T>): EntityListInteractions<T> {
  // ---- Search filtering ----
  const items = useMemo(() => {
    if (!search || !search.query.trim()) return rawItems
    return rawItems.filter(item => search.fn(item, search.query))
  }, [rawItems, search?.query, search?.fn]) // eslint-disable-line react-hooks/exhaustive-deps

  // ---- Multi-select state ----
  // Use external store (e.g. Jotai atom) when provided, otherwise local useState
  const [internalState, setInternalState] = useState<MultiSelect.MultiSelectState>(
    MultiSelect.createInitialState
  )
  const selectionState = selectionStore?.state ?? internalState
  const setSelectionState = selectionStore?.setState ?? setInternalState

  const allIds = useMemo(() => items.map(getId), [items, getId])

  const toggle = useCallback((id: string, index: number) => {
    setSelectionState(prev => MultiSelect.toggleSelect(prev, id, index))
  }, [])

  const range = useCallback((toIndex: number) => {
    setSelectionState(prev => MultiSelect.rangeSelect(prev, toIndex, allIds))
  }, [allIds])

  const selectAllItems = useCallback(() => {
    setSelectionState(MultiSelect.selectAll(allIds))
  }, [allIds])

  const clearSelection = useCallback(() => {
    setSelectionState(prev => MultiSelect.clearMultiSelect(prev))
  }, [])

  const isMultiSelectActive = MultiSelect.isMultiSelectActive(selectionState)

  // ---- Keyboard navigation ----
  const handleNavigate = useCallback((item: T, index: number) => {
    // Scroll into view
    const id = getId(item)
    requestAnimationFrame(() => {
      const el = document.getElementById(`item-${id}`)
      el?.scrollIntoView({ block: 'nearest', behavior: 'instant' })
    })

    // Exit multi-select on plain arrow navigation, then single-select the navigated item
    if (multiSelectEnabled && isMultiSelectActive) {
      clearSelection()
    }

    // Update selection to follow the keyboard cursor
    setSelectionState(MultiSelect.singleSelect(id, index))

    keyboardOpts?.onNavigate?.(item, index)
  }, [getId, multiSelectEnabled, isMultiSelectActive, clearSelection, keyboardOpts?.onNavigate]) // eslint-disable-line react-hooks/exhaustive-deps

  const handleActivate = useCallback((item: T, index: number) => {
    if (multiSelectEnabled && !isMultiSelectActive) {
      // Single-select on Enter
      setSelectionState(MultiSelect.singleSelect(getId(item), index))
    }
    keyboardOpts?.onActivate?.(item, index)
  }, [multiSelectEnabled, isMultiSelectActive, getId, keyboardOpts?.onActivate]) // eslint-disable-line react-hooks/exhaustive-deps

  const handleExtendSelection = useCallback((toIndex: number) => {
    if (multiSelectEnabled) {
      range(toIndex)
    }
  }, [multiSelectEnabled, range])

  const {
    activeIndex,
    setActiveIndex,
    getItemProps,
    getContainerProps,
    focusActiveItem,
  } = useRovingTabIndex({
    items,
    getId: (item) => getId(item),
    orientation: 'vertical',
    wrap: true,
    onNavigate: handleNavigate,
    onActivate: handleActivate,
    enabled: keyboardOpts?.enabled ?? true,
    moveFocus: !(keyboardOpts?.virtualFocus ?? false),
    onExtendSelection: multiSelectEnabled ? handleExtendSelection : undefined,
  })

  // ---- Mouse interaction ----
  // Track last selected index for range select — separate from activeIndex
  // because activeIndex follows keyboard, this follows clicks.
  const lastClickIndexRef = useRef<number>(-1)

  const getRowMouseDown = useCallback((item: T, index: number) => {
    return (e: React.MouseEvent) => {
      const id = getId(item)

      // Right-click: preserve multi-select, let context menu handle batch actions
      if (e.button === 2) {
        if (multiSelectEnabled && isMultiSelectActive && !selectionState.selectedIds.has(id)) {
          // Right-clicking an unselected item during multi-select: add it to selection
          toggle(id, index)
        }
        // Don't change selection — context menu shows batch or single actions
        return
      }

      const isMetaKey = e.metaKey || e.ctrlKey
      const isShiftKey = e.shiftKey

      if (multiSelectEnabled && isMetaKey) {
        e.preventDefault()
        toggle(id, index)
        lastClickIndexRef.current = index
        return
      }

      if (multiSelectEnabled && isShiftKey) {
        e.preventDefault()
        range(index)
        return
      }

      // Normal click — single select
      setSelectionState(MultiSelect.singleSelect(id, index))
      lastClickIndexRef.current = index
      setActiveIndex(index)
    }
  }, [getId, multiSelectEnabled, isMultiSelectActive, selectionState.selectedIds, toggle, range, setActiveIndex])

  // ---- Search input keyboard forwarding ----
  // Forwards ArrowDown/ArrowUp from a search input to the roving tabindex handler.
  // Matches SessionList pattern (SessionList.tsx:1598).
  const searchInputOnKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault()
      // Forward to the roving tabindex container handler
      getContainerProps().onKeyDown(e as unknown as React.KeyboardEvent)
      return
    }
    if (e.key === 'Escape') {
      e.preventDefault()
      ;(e.target as HTMLInputElement).blur()
      return
    }
    if (e.key === 'Enter') {
      // Forward Enter to activate the focused item
      e.preventDefault()
      getContainerProps().onKeyDown(e as unknown as React.KeyboardEvent)
      return
    }
  }, [getContainerProps])

  // ---- Build return values ----
  const containerProps = getContainerProps()

  const listProps = useMemo(() => ({
    containerRef: undefined as React.Ref<HTMLDivElement> | undefined,
    containerProps: {
      role: containerProps.role,
      'aria-activedescendant': containerProps['aria-activedescendant'] ?? '',
    },
  }), [containerProps.role, containerProps['aria-activedescendant']])

  const getRowProps = useCallback((item: T, index: number) => {
    const id = getId(item)
    const itemProps = getItemProps(item, index)
    const effectiveSelected = selectedIdOverride !== undefined
      ? selectedIdOverride
      : selectionState.selected
    const isSelected = multiSelectEnabled
      ? effectiveSelected === id
      : index === activeIndex
    const isInMultiSelect = multiSelectEnabled && isMultiSelectActive && selectionState.selectedIds.has(id)

    return {
      buttonProps: {
        id: itemProps.id,
        tabIndex: itemProps.tabIndex,
        ref: itemProps.ref,
        onKeyDown: itemProps.onKeyDown,
        onFocus: itemProps.onFocus,
        'aria-selected': itemProps['aria-selected'],
        role: itemProps.role,
      } as Record<string, unknown>,
      isSelected,
      isInMultiSelect,
      onMouseDown: getRowMouseDown(item, index),
    }
  }, [getId, getItemProps, multiSelectEnabled, selectionState, activeIndex, isMultiSelectActive, getRowMouseDown, selectedIdOverride])

  return {
    items,
    listProps,
    getRowProps,
    searchInputProps: {
      onKeyDown: searchInputOnKeyDown,
    },
    keyboard: {
      activeIndex,
      setActiveIndex,
      focusActiveItem,
    },
    selection: {
      state: selectionState,
      isMultiSelectActive,
      selectedIds: selectionState.selectedIds,
      toggle,
      range,
      selectAll: selectAllItems,
      clear: clearSelection,
    },
  }
}

import { useCallback, useEffect, useRef, useState } from 'react'
import type { SessionDecisionQuery, SessionDecisionReport } from '@phaneris/shared/decisions/session'

export type DecisionLoadState = 'loading' | 'ready' | 'error' | 'unsupported'
export function useSessionDecisions(sessionId: string | undefined, workspaceId: string | undefined, query: SessionDecisionQuery = {}, enabled = true, serverScope = workspaceId) {
  const key = JSON.stringify([serverScope, workspaceId, sessionId, query.feature, query.status, query.turnId])
  const [value, setValue] = useState<{ key: string; state: DecisionLoadState; report?: SessionDecisionReport; paging?: boolean }>({ key, state: 'loading' })
  const generation = useRef(0)
  const loader = useRef<(cursor?: string) => Promise<void>>(async () => {})
  useEffect(() => {
    let disposed = false, timer: ReturnType<typeof setTimeout> | undefined
    const current = ++generation.current
    let latest: SessionDecisionReport | undefined, loaded = 40
    setValue({ key, state: 'loading' })
    if (!enabled || !sessionId || !workspaceId) return
    const load = async (cursor?: string, snapshotRetry = false) => {
      const requestGeneration = ++generation.current
      if (typeof window.electronAPI?.getSessionDecisions !== 'function') { setValue({ key, state: 'unsupported' }); return }
      if (cursor) setValue(previous => ({ ...previous, paging: true }))
      try {
        let report = await window.electronAPI.getSessionDecisions(sessionId, { ...query, cursor, limit: cursor ? 40 : Math.min(100, loaded) })
        if (disposed || requestGeneration !== generation.current) return
        if (report?.schemaVersion !== 1) { setValue({ key, state: 'unsupported' }); return }
        if (report.sessionId !== sessionId || report.workspaceId !== workspaceId) throw new Error('Decision report ownership mismatch')
        // Retain loaded history and its keyed details when new records arrive.
        const added = latest ? Math.max(0, report.totals.points + report.totals.legacyCalls - latest.totals.points - latest.totals.legacyCalls) : 0
        const target = loaded + added
        while (!cursor && report.nextCursor && report.items.length < target) {
          const page = await window.electronAPI.getSessionDecisions(sessionId, { ...query, cursor: report.nextCursor, limit: Math.min(100, target - report.items.length) })
          if (disposed || requestGeneration !== generation.current) return
          if (page.revision !== report.revision || page.workspaceId !== workspaceId || page.sessionId !== sessionId) throw new Error('Decision snapshot changed; reload the first page')
          report = { ...page, items: [...report.items, ...page.items] }
        }
        if (cursor && latest?.revision === report.revision) report = { ...report, items: [...latest.items, ...report.items.filter(item => !latest!.items.some(old => old.id === item.id))] }
        latest = report
        loaded = Math.max(40, report.items.length)
        setValue({ key, state: 'ready', report })
      } catch (error) {
        if (disposed || requestGeneration !== generation.current) return
        const message = error instanceof Error ? error.message : String(error)
        if (!snapshotRetry && /snapshot changed/.test(message)) { await load(undefined, true); return }
        setValue({ key, state: /unknown channel|unknown method|not registered|not supported|no handler|method not found/i.test(message) ? 'unsupported' : 'error' })
      }
    }
    loader.current = load
    void load()
    const refresh = () => { clearTimeout(timer); timer = setTimeout(() => { void load() }, 180) }
    const unsubscribe = window.electronAPI.onSessionDecisionsChanged?.(id => { if (id === sessionId) refresh() })
    const reconnect = window.electronAPI.onTransportConnectionStateChanged?.(() => {
      ++generation.current
      setValue({ key, state: 'loading' })
      refresh()
    })
    return () => { disposed = true; if (generation.current >= current) ++generation.current; clearTimeout(timer); unsubscribe?.(); reconnect?.() }
    // The serialized key owns the query and prevents stale session/filter responses from painting.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, enabled])
  const retry = useCallback(() => { setValue({ key, state: 'loading' }); void loader.current() }, [key])
  const state = value.key === key ? value : { key, state: 'loading' as const }
  const loadMore = () => { if (state.report?.nextCursor && !state.paging) void loader.current(state.report.nextCursor) }
  return { ...state, retry, loadMore }
}

/**
 * useWorkspaceIcon Hook
 *
 * Fetches workspace icons as data URLs for rendering in img tags.
 * Handles file:// to data URL conversion via IPC since Electron's CSP
 * blocks direct file:// URLs in the renderer.
 *
 * Used by settings pages that display workspace icons.
 */

import { useState, useEffect, useRef } from 'react'
import type { Workspace } from '../../shared/types'

// Module-level cache to avoid redundant fetches across component instances
// Key: workspaceId, Value: { dataUrl, sourceUrl }
const iconCache = new Map<string, { dataUrl: string; sourceUrl: string }>()

/**
 * Hook to get a workspace icon as a renderable URL.
 *
 * - Remote URLs (http/https) are returned directly
 * - Local file:// URLs are converted to data URLs via IPC
 * - Returns undefined while loading or if no icon exists
 *
 * @param workspace - The workspace object with iconUrl
 * @returns Data URL or remote URL for the icon, or undefined
 */
export function useWorkspaceIcon(workspace: Workspace | undefined): string | undefined {
  const [iconUrl, setIconUrl] = useState<string | undefined>(() => {
    if (!workspace?.iconUrl) return undefined

    // Remote URLs can be used directly
    if (workspace.iconUrl.startsWith('http://') || workspace.iconUrl.startsWith('https://')) {
      return workspace.iconUrl
    }

    // Check cache for file:// URLs
    const cached = iconCache.get(workspace.id)
    if (cached && cached.sourceUrl === workspace.iconUrl) {
      return cached.dataUrl
    }

    return undefined
  })

  // Track the workspace to detect changes
  const workspaceRef = useRef(workspace)

  useEffect(() => {
    if (!workspace?.iconUrl) {
      setIconUrl(undefined)
      return
    }

    // Remote URLs - use directly
    if (workspace.iconUrl.startsWith('http://') || workspace.iconUrl.startsWith('https://')) {
      setIconUrl(workspace.iconUrl)
      return
    }

    // Not a file:// URL - skip
    if (!workspace.iconUrl.startsWith('file://')) {
      setIconUrl(undefined)
      return
    }

    // Check if already cached with same source URL
    const cached = iconCache.get(workspace.id)
    if (cached && cached.sourceUrl === workspace.iconUrl) {
      setIconUrl(cached.dataUrl)
      return
    }

    // Extract icon filename from file:// URL
    // e.g., "file:///path/to/icon.png?t=123" -> "icon.png"
    const urlWithoutQuery = workspace.iconUrl.split('?')[0]
    const iconFilename = urlWithoutQuery.split('/').pop()
    if (!iconFilename) {
      setIconUrl(undefined)
      return
    }

    // Fetch via IPC and convert to data URL
    let cancelled = false

    async function fetchIcon() {
      try {
        const result = await window.electronAPI.readWorkspaceImage(workspace!.id, iconFilename!)
        if (cancelled) return

        if (result) {
          // readWorkspaceImage returns raw SVG for .svg files, data URL for others
          let dataUrl = result
          if (iconFilename!.endsWith('.svg')) {
            dataUrl = `data:image/svg+xml;base64,${btoa(result)}`
          }

          // Cache the result
          iconCache.set(workspace!.id, { dataUrl, sourceUrl: workspace!.iconUrl! })
          setIconUrl(dataUrl)
        } else {
          setIconUrl(undefined)
        }
      } catch (error) {
        console.error(`Failed to load icon for workspace ${workspace!.id}:`, error)
        if (!cancelled) {
          setIconUrl(undefined)
        }
      }
    }

    fetchIcon()

    return () => {
      cancelled = true
    }
  }, [workspace?.id, workspace?.iconUrl])

  return iconUrl
}

/**
 * Hook to get icons for multiple workspaces at once.
 * More efficient than calling useWorkspaceIcon for each workspace.
 *
 * @param workspaces - Array of workspace objects
 * @returns Map of workspaceId -> icon URL (data URL or remote URL)
 */
export function useWorkspaceIcons(workspaces: Workspace[]): Map<string, string> {
  const [iconMap, setIconMap] = useState<Map<string, string>>(() => {
    const map = new Map<string, string>()
    for (const ws of workspaces) {
      if (!ws.iconUrl) continue

      // Remote URLs
      if (ws.iconUrl.startsWith('http://') || ws.iconUrl.startsWith('https://')) {
        map.set(ws.id, ws.iconUrl)
        continue
      }

      // Cached file:// URLs
      const cached = iconCache.get(ws.id)
      if (cached && cached.sourceUrl === ws.iconUrl) {
        map.set(ws.id, cached.dataUrl)
      }
    }
    return map
  })

  useEffect(() => {
    let cancelled = false

    async function fetchIcons() {
      const newMap = new Map<string, string>()

      for (const workspace of workspaces) {
        if (!workspace.iconUrl) continue

        // Remote URLs - use directly
        if (workspace.iconUrl.startsWith('http://') || workspace.iconUrl.startsWith('https://')) {
          newMap.set(workspace.id, workspace.iconUrl)
          continue
        }

        // Not a file:// URL - skip
        if (!workspace.iconUrl.startsWith('file://')) continue

        // Check cache first
        const cached = iconCache.get(workspace.id)
        if (cached && cached.sourceUrl === workspace.iconUrl) {
          newMap.set(workspace.id, cached.dataUrl)
          continue
        }

        // Extract icon filename
        const urlWithoutQuery = workspace.iconUrl.split('?')[0]
        const iconFilename = urlWithoutQuery.split('/').pop()
        if (!iconFilename) continue

        try {
          const result = await window.electronAPI.readWorkspaceImage(workspace.id, iconFilename)
          if (cancelled) return

          if (result) {
            let dataUrl = result
            if (iconFilename.endsWith('.svg')) {
              dataUrl = `data:image/svg+xml;base64,${btoa(result)}`
            }

            iconCache.set(workspace.id, { dataUrl, sourceUrl: workspace.iconUrl })
            newMap.set(workspace.id, dataUrl)
          }
        } catch (error) {
          console.error(`Failed to load icon for workspace ${workspace.id}:`, error)
        }
      }

      if (!cancelled) {
        setIconMap(newMap)
      }
    }

    fetchIcons()

    return () => {
      cancelled = true
    }
  }, [workspaces])

  return iconMap
}

/**
 * useOnboarding Hook
 *
 * Manages the state machine for the onboarding wizard.
 * Flow:
 * 1. Welcome
 * 2. Git Bash (Windows only, if not found)
 * 3. API Setup (API Key / Claude OAuth)
 * 4. Credentials (API Key or Claude OAuth)
 * 5. Complete
 */
import { useState, useCallback, useEffect } from 'react'
import type {
  OnboardingState,
  OnboardingStep,
  ApiSetupMethod,
} from '@/components/onboarding'
import type { ProviderChoice } from '@/components/onboarding/ProviderSelectStep'
import type { LlmProviderType } from '@phaneris/shared/config/llm-connections'
import type { LocalModelSubmitData } from '@/components/onboarding/LocalModelStep'
import type { ApiKeySubmitData } from '@/components/apisetup'
import type { CustomEndpointConfig } from '@config/llm-connections'
import type { SetupNeeds, LlmConnectionSetup, ClaudeOAuthIdentityDto } from '../../shared/types'

interface UseOnboardingOptions {
  /** Called when onboarding is complete */
  onComplete: () => void
  /** Initial setup needs from auth state check */
  initialSetupNeeds?: SetupNeeds
  /** Start the wizard at a specific step (default: 'welcome') */
  initialStep?: OnboardingStep
  /** Pre-select an API setup method (useful when editing an existing connection) */
  initialApiSetupMethod?: ApiSetupMethod
  /** Called when user goes back from the initial step (dismisses the wizard) */
  onDismiss?: () => void
  /** Called immediately after config is saved to disk (before wizard closes).
   *  Use this to propagate billing/model changes to the UI without waiting for onComplete. */
  onConfigSaved?: () => void
  /** Slug of existing connection being edited (null = creating new) */
  editingSlug?: string | null
  /** Set of slugs already in use (for generating unique slugs when creating new) */
  existingSlugs?: Set<string>
}

interface UseOnboardingReturn {
  // State
  state: OnboardingState

  // Wizard actions
  handleContinue: () => void
  handleBack: () => void

  // Provider select (new flow)
  handleSelectProvider: (choice: ProviderChoice) => void

  // API Setup (legacy — kept for direct edit)
  handleSelectApiSetupMethod: (method: ApiSetupMethod) => void

  // Credentials
  handleSubmitCredential: (data: ApiKeySubmitData) => void

  // Local model
  handleSubmitLocalModel: (data: LocalModelSubmitData) => void
  handleStartOAuth: (methodOverride?: ApiSetupMethod, connectionSlugOverride?: string) => void

  // Claude OAuth (two-step flow)
  isWaitingForCode: boolean
  handleSubmitAuthCode: (code: string) => void
  handleCancelOAuth: () => void

  // Copilot device code + unified Pi OAuth events
  copilotDeviceCode?: {
    userCode: string
    verificationUri: string
    instructions?: string
    progressMessage?: string
    manualCodeRequested?: boolean
    placeholder?: string
  }
  /** Headless Pi OAuth: forward a pasted authorization code / redirect URL. */
  handleSubmitPiOAuthCode: (code: string) => void

  // Git Bash (Windows)
  handleBrowseGitBash: () => Promise<string | null>
  handleUseGitBashPath: (path: string) => void
  handleRecheckGitBash: () => void
  handleClearError: () => void

  // Skip setup ("Setup later")
  handleSkipSetup: () => void

  // Completion
  handleFinish: () => void
  handleCancel: () => void

  // Direct edit (skip method selection, jump to credentials)
  jumpToCredentials: (method: ApiSetupMethod) => void

  // Reset
  reset: () => void
}

// Base slug for each setup method (used as template key in ipc.ts)
export const BASE_SLUG_FOR_METHOD: Record<ApiSetupMethod, string> = {
  anthropic_api_key: 'anthropic-api',
  claude_oauth: 'claude-max',
  pi_chatgpt_oauth: 'chatgpt-plus',
  pi_copilot_oauth: 'github-copilot',
  pi_xai_oauth: 'grok-x',
  pi_openrouter_oauth: 'openrouter',
  pi_kimi_oauth: 'kimi-coding',
  pi_radius_oauth: 'radius',
  pi_api_key: 'pi-api-key',
}

/**
 * Generate a unique slug for a new connection.
 * If the base slug is taken, appends -2, -3, etc.
 * When editingSlug is provided, reuses that slug (editing existing connection).
 */
export function resolveSlugForMethod(
  method: ApiSetupMethod,
  editingSlug: string | null,
  existingSlugs: Set<string>,
): string {
  // Editing an existing connection — reuse its slug
  if (editingSlug) return editingSlug

  const base = BASE_SLUG_FOR_METHOD[method]
  if (!existingSlugs.has(base)) return base

  let i = 2
  while (existingSlugs.has(`${base}-${i}`)) i++
  return `${base}-${i}`
}

// Map ApiSetupMethod to LlmConnectionSetup for the new unified connection system
function isLoopbackEndpoint(baseUrl?: string): boolean {
  if (!baseUrl?.trim()) return false
  try {
    const hostname = new URL(baseUrl.trim()).hostname
    const normalizedHostname = hostname.startsWith('[') && hostname.endsWith(']')
      ? hostname.slice(1, -1)
      : hostname
    return normalizedHostname === 'localhost' || normalizedHostname === '127.0.0.1' || normalizedHostname === '::1'
  } catch {
    return false
  }
}

export function apiSetupMethodToConnectionSetup(
  method: ApiSetupMethod,
  options: {
    credential?: string
    baseUrl?: string
    brandId?: string
    connectionDefaultModel?: string
    utilityModel?: string | null
    models?: string[]
    piAuthProvider?: string
    modelSelectionMode?: 'automaticallySyncedFromProvider' | 'userDefined3Tier'
    customEndpoint?: CustomEndpointConfig
    iamCredentials?: { accessKeyId: string; secretAccessKey: string; sessionToken?: string }
    awsRegion?: string
    bedrockAuthMethod?: 'iam_credentials' | 'environment'
    oauthIdentity?: ClaudeOAuthIdentityDto
  },
  editingSlug: string | null,
  existingSlugs: Set<string>,
): LlmConnectionSetup {
  const slug = resolveSlugForMethod(method, editingSlug, existingSlugs)

  switch (method) {
    case 'anthropic_api_key':
      return {
        slug,
        credential: options.credential,
        baseUrl: options.baseUrl,
        brandId: options.brandId,
        defaultModel: options.connectionDefaultModel,
        utilityModel: options.utilityModel,
        models: options.models,
        customEndpoint: options.customEndpoint,
      }
    case 'claude_oauth':
      return {
        slug,
        credential: options.credential,
        oauthIdentity: options.oauthIdentity,
      }
    case 'pi_chatgpt_oauth':
    case 'pi_copilot_oauth':
    case 'pi_xai_oauth':
    case 'pi_openrouter_oauth':
    case 'pi_kimi_oauth':
    case 'pi_radius_oauth':
      return {
        slug,
        credential: options.credential,
      }
    case 'pi_api_key':
      return {
        slug,
        credential: options.credential,
        baseUrl: options.baseUrl,
        brandId: options.brandId,
        defaultModel: options.connectionDefaultModel,
        utilityModel: options.utilityModel,
        models: options.models,
        piAuthProvider: options.piAuthProvider,
        modelSelectionMode: options.modelSelectionMode,
        customEndpoint: options.customEndpoint,
        iamCredentials: options.iamCredentials,
        awsRegion: options.awsRegion,
        bedrockAuthMethod: options.bedrockAuthMethod,
      }
  }
}

export function useOnboarding({
  onComplete,
  initialSetupNeeds,
  initialStep = 'provider-select',
  initialApiSetupMethod,
  onDismiss,
  onConfigSaved,
  editingSlug = null,
  existingSlugs = new Set(),
}: UseOnboardingOptions): UseOnboardingReturn {
  // Main wizard state
  const [state, setState] = useState<OnboardingState>({
    step: initialStep,
    loginStatus: 'idle',
    credentialStatus: 'idle',
    completionStatus: 'saving',
    apiSetupMethod: initialApiSetupMethod ?? null,
    isExistingUser: initialSetupNeeds?.needsBillingConfig ?? false,
    gitBashStatus: undefined,
    isRecheckingGitBash: false,
    isCheckingGitBash: true, // Start as true until check completes
  })

  // Check Git Bash on Windows at mount. If missing, redirect to git-bash step
  // regardless of the initial step (provider-select skips the welcome gate).
  useEffect(() => {
    const checkGitBash = async () => {
      try {
        const status = await window.electronAPI.checkGitBash()
        setState(s => ({
          ...s,
          gitBashStatus: status,
          isCheckingGitBash: false,
          // Redirect to git-bash step when missing on Windows
          ...(status.platform === 'win32' && !status.found ? { step: 'git-bash' as const } : {}),
        }))
      } catch (error) {
        console.error('[Onboarding] Failed to check Git Bash:', error)
        // Even on error, allow continuing (will skip git-bash step)
        setState(s => ({ ...s, isCheckingGitBash: false }))
      }
    }
    checkGitBash()
  }, [])

  // Save configuration using the new unified LLM connection API
  // Returns true on success, false on failure (sets errorMessage on failure)
  // `methodOverride` lets callers pass the method explicitly to avoid stale-closure issues
  // (e.g. when called from an async OAuth flow whose closure predates the state update).
  const handleSaveConfig = useCallback(async (
    credential?: string,
    options?: {
      baseUrl?: string
      brandId?: string
      connectionDefaultModel?: string
      utilityModel?: string | null
      models?: string[]
      piAuthProvider?: string
      modelSelectionMode?: 'automaticallySyncedFromProvider' | 'userDefined3Tier'
      customEndpoint?: CustomEndpointConfig
      iamCredentials?: { accessKeyId: string; secretAccessKey: string; sessionToken?: string }
      awsRegion?: string
      bedrockAuthMethod?: 'iam_credentials' | 'environment'
      oauthIdentity?: ClaudeOAuthIdentityDto
    },
    methodOverride?: ApiSetupMethod,
    connectionSlugOverride?: string,
    updateOnly?: boolean,
  ): Promise<boolean> => {
    const method = methodOverride ?? state.apiSetupMethod
    if (!method) {
      return false
    }

    setState(s => ({ ...s, completionStatus: 'saving' }))

    try {
      // Build connection setup from UI state
      const setup = apiSetupMethodToConnectionSetup(method, {
        credential,
        baseUrl: options?.baseUrl,
        brandId: options?.brandId,
        connectionDefaultModel: options?.connectionDefaultModel,
        utilityModel: options?.utilityModel,
        models: options?.models,
        piAuthProvider: options?.piAuthProvider,
        modelSelectionMode: options?.modelSelectionMode,
        customEndpoint: options?.customEndpoint,
        iamCredentials: options?.iamCredentials,
        awsRegion: options?.awsRegion,
        bedrockAuthMethod: options?.bedrockAuthMethod,
        oauthIdentity: options?.oauthIdentity,
      }, connectionSlugOverride ?? editingSlug, existingSlugs)
      // Use new unified API
      const result = await window.electronAPI.setupLlmConnection(
        updateOnly ? { ...setup, updateOnly: true } : setup
      )

      if (result.success) {
        setState(s => ({ ...s, completionStatus: 'complete' }))
        // Notify caller immediately so UI can reflect billing/model changes
        onConfigSaved?.()
        return true
      } else {
        console.error('[Onboarding] Save failed:', result.error)
        setState(s => ({
          ...s,
          completionStatus: 'saving',
          errorMessage: result.error || 'Failed to save configuration',
        }))
        return false
      }
    } catch (error) {
      console.error('[Onboarding] handleSaveConfig error:', error)
      setState(s => ({
        ...s,
        errorMessage: error instanceof Error ? error.message : 'Failed to save configuration',
      }))
      return false
    }
  }, [state.apiSetupMethod, onConfigSaved, editingSlug, existingSlugs])

  // Continue to next step
  const handleContinue = useCallback(async () => {
    switch (state.step) {
      case 'provider-select':
        // Handled by handleSelectProvider (card click navigates directly)
        break

      case 'welcome':
        // On Windows, check if Git Bash is needed
        if (state.gitBashStatus?.platform === 'win32' && !state.gitBashStatus?.found) {
          setState(s => ({ ...s, step: 'git-bash' }))
        } else {
          setState(s => ({ ...s, step: 'provider-select' }))
        }
        break

      case 'git-bash':
        setState(s => ({ ...s, step: 'provider-select' }))
        break

      case 'local-model':
        // Handled by handleSubmitLocalModel
        break

      case 'credentials':
        // Handled by handleSubmitCredential
        break

      case 'complete':
        onComplete()
        break
    }
  }, [state.step, state.gitBashStatus, state.apiSetupMethod, onComplete])

  // Go back to previous step. If at the initial step, call onDismiss instead.
  const handleBack = useCallback(() => {
    if (state.step === initialStep && onDismiss) {
      onDismiss()
      return
    }
    switch (state.step) {
      case 'git-bash':
        if (onDismiss) {
          onDismiss()
        }
        break
      case 'provider-select':
        // If on Windows and Git Bash was needed, go back to git-bash step
        if (state.gitBashStatus?.platform === 'win32' && state.gitBashStatus?.found === false) {
          setState(s => ({ ...s, step: 'git-bash' }))
        } else if (onDismiss) {
          onDismiss()
        }
        break
      case 'credentials':
        setState(s => ({ ...s, step: 'provider-select', credentialStatus: 'idle', errorMessage: undefined }))
        break
      case 'local-model':
        setState(s => ({ ...s, step: 'provider-select', credentialStatus: 'idle', errorMessage: undefined }))
        break
    }
  }, [state.step, state.gitBashStatus, initialStep, onDismiss])

  // Select API setup method (legacy — kept for direct edit flows)
  const handleSelectApiSetupMethod = useCallback((method: ApiSetupMethod) => {
    setState(s => ({ ...s, apiSetupMethod: method }))
  }, [])

  // Submit credential (API key + optional endpoint config)
  // Tests the connection first before saving to catch issues early
  const handleSubmitCredential = useCallback(async (data: ApiKeySubmitData) => {
    setState(s => ({ ...s, credentialStatus: 'validating', errorMessage: undefined }))

    const isPiApiKeyFlow = state.apiSetupMethod === 'pi_api_key'

    try {
      // Bedrock (Pi+amazon-bedrock) — skip API key validation and connection test
      if (data.bedrockAuthMethod) {
        const saved = await handleSaveConfig(undefined, {
          baseUrl: data.baseUrl,
          brandId: data.brandId,
          connectionDefaultModel: data.connectionDefaultModel,
          utilityModel: data.utilityModel,
          models: data.models,
          piAuthProvider: data.piAuthProvider,
          modelSelectionMode: data.modelSelectionMode,
          iamCredentials: data.iamCredentials,
          awsRegion: data.awsRegion,
          bedrockAuthMethod: data.bedrockAuthMethod,
        })
        if (saved) {
          setState(s => ({ ...s, credentialStatus: 'success', step: 'complete' }))
        } else {
          setState(s => ({ ...s, credentialStatus: 'error' }))
        }
        return
      }

      // When editing an existing connection, API key is optional (empty = keep existing credential)
      if (!data.apiKey.trim() && editingSlug) {
        const saved = await handleSaveConfig(undefined, {
          baseUrl: data.baseUrl,
          brandId: data.brandId,
          connectionDefaultModel: data.connectionDefaultModel,
          utilityModel: data.utilityModel,
          models: data.models,
          piAuthProvider: data.piAuthProvider,
          modelSelectionMode: data.modelSelectionMode,
          customEndpoint: data.customEndpoint,
        })
        if (saved) {
          setState(s => ({ ...s, credentialStatus: 'success', step: 'complete' }))
        } else {
          setState(s => ({ ...s, credentialStatus: 'error' }))
        }
        return
      }

      // API key validation differs by endpoint locality:
      // - Local/loopback custom endpoints may be keyless (e.g. Ollama)
      // - Non-local endpoints require an API key
      const isLoopbackCustomEndpoint = isLoopbackEndpoint(data.baseUrl)
      if (isPiApiKeyFlow) {
        if (!data.apiKey.trim() && !isLoopbackCustomEndpoint) {
          setState(s => ({
            ...s,
            credentialStatus: 'error',
            errorMessage: 'Please enter a valid API key',
          }))
          return
        }
      } else {
        if (!data.apiKey.trim() && !isLoopbackCustomEndpoint) {
          setState(s => ({
            ...s,
            credentialStatus: 'error',
            errorMessage: 'Please enter a valid API key',
          }))
          return
        }
      }

      // Validate connection by spawning a lightweight subprocess test.
      // Custom endpoint protocol routes through PiAgent at runtime, so test with Pi too.
      const setupTestProvider: LlmProviderType = 'pi'
      const testResult = await window.electronAPI.testLlmConnectionSetup({
        provider: setupTestProvider,
        apiKey: data.apiKey,
        baseUrl: data.baseUrl,
        model: data.models?.[0],
        piAuthProvider: data.piAuthProvider,
        customEndpoint: data.customEndpoint,
        // Editing: the key field may still hold the masked placeholder; the server
        // resolves it to the stored credential by slug (craft-agents-oss#1048).
        // This callback has no slug override of its own — it edits exactly
        // `editingSlug`, which is also the slug it hands to handleSaveConfig below.
        connectionSlug: editingSlug ?? undefined,
      })

      if (!testResult.success) {
        setState(s => ({
          ...s,
          credentialStatus: 'error',
          errorMessage: testResult.error || 'Connection test failed',
        }))
        return
      }

      const saved = await handleSaveConfig(data.apiKey, {
        baseUrl: data.baseUrl,
        brandId: data.brandId,
        connectionDefaultModel: data.connectionDefaultModel,
        utilityModel: data.utilityModel,
        models: data.models,
        piAuthProvider: data.piAuthProvider,
        modelSelectionMode: data.modelSelectionMode,
        customEndpoint: data.customEndpoint,
      })

      if (saved) {
        setState(s => ({
          ...s,
          credentialStatus: 'success',
          step: 'complete',
        }))
      } else {
        // Save failed — error is already set by handleSaveConfig, stay on credentials step
        setState(s => ({ ...s, credentialStatus: 'error' }))
      }
    } catch (error) {
      setState(s => ({
        ...s,
        credentialStatus: 'error',
        errorMessage: error instanceof Error ? error.message : 'Validation failed',
      }))
    }
  }, [handleSaveConfig, state.apiSetupMethod])

  // Save config, validate the connection, and update state accordingly.
  // Shared by all OAuth flows after tokens are captured.
  // `method` is passed explicitly to break the stale-closure chain — the OAuth
  // await crosses renders, so handleSaveConfig's closure may have an outdated
  // state.apiSetupMethod.
  const saveAndValidateConnection = useCallback(async (connectionSlug: string, method: ApiSetupMethod, credential?: string, updateOnly?: boolean, oauthIdentity?: ClaudeOAuthIdentityDto): Promise<boolean> => {
    const saved = await handleSaveConfig(credential, oauthIdentity ? { oauthIdentity } : undefined, method, connectionSlug, updateOnly)
    if (!saved) {
      setState(s => ({ ...s, credentialStatus: 'error' }))
      return false
    }
    const testResult = await window.electronAPI.testLlmConnection(connectionSlug)
    if (testResult.success) {
      setState(s => ({ ...s, credentialStatus: 'success', step: 'complete' }))
      return true
    } else {
      setState(s => ({ ...s, credentialStatus: 'error', errorMessage: testResult.error || 'Connection test failed' }))
      return false
    }
  }, [handleSaveConfig])

  // Two-step OAuth flow state
  const [isWaitingForCode, setIsWaitingForCode] = useState(false)

  // Copilot device code (displayed during device flow; also carries the
  // unified Pi OAuth events: auth URL, progress, headless manual-code prompt)
  const [copilotDeviceCode, setCopilotDeviceCode] = useState<{
    userCode: string
    verificationUri: string
    instructions?: string
    progressMessage?: string
    manualCodeRequested?: boolean
    placeholder?: string
  } | undefined>()
  // Connection slug of the in-flight Pi OAuth flow (for headless code submit)
  const [piOAuthSlug, setPiOAuthSlug] = useState<string | undefined>()

  // Start OAuth flow (Claude or ChatGPT depending on selected method)
  const handleStartOAuth = useCallback(async (methodOverride?: ApiSetupMethod, connectionSlugOverride?: string) => {
    const effectiveMethod = methodOverride ?? state.apiSetupMethod

    if (methodOverride && methodOverride !== state.apiSetupMethod) {
      setState(s => ({
        ...s,
        apiSetupMethod: methodOverride,
        step: 'credentials',
        credentialStatus: 'validating',
        errorMessage: undefined,
      }))
    } else {
      setState(s => ({ ...s, credentialStatus: 'validating', errorMessage: undefined }))
    }

    if (!effectiveMethod) {
      setState(s => ({
        ...s,
        credentialStatus: 'error',
        errorMessage: 'Select an authentication method first.',
      }))
      return
    }

    try {
      // ChatGPT OAuth (single-step flow - opens browser, captures tokens automatically)
      if (effectiveMethod === 'pi_chatgpt_oauth') {
        const effectiveEditingSlug = connectionSlugOverride ?? editingSlug
        const isReauth = !!effectiveEditingSlug
        const connectionSlug = apiSetupMethodToConnectionSetup(effectiveMethod, {}, effectiveEditingSlug, existingSlugs).slug
        const result = await window.electronAPI.startChatGptOAuth(connectionSlug)

        if (result.success) {
          await saveAndValidateConnection(connectionSlug, effectiveMethod, undefined, isReauth)
        } else {
          setState(s => ({
            ...s,
            credentialStatus: 'error',
            errorMessage: result.error || 'ChatGPT authentication failed',
          }))
        }
        return
      }

      // Copilot OAuth (device flow — polls for token after user enters code on GitHub)
      if (effectiveMethod === 'pi_copilot_oauth') {
        const effectiveEditingSlug = connectionSlugOverride ?? editingSlug
        const isReauth = !!effectiveEditingSlug
        const connectionSlug = apiSetupMethodToConnectionSetup(effectiveMethod, {}, effectiveEditingSlug, existingSlugs).slug

        // Subscribe to device code event before starting the flow
        const cleanup = window.electronAPI.onCopilotDeviceCode((data) => {
          setCopilotDeviceCode(data)
        })

        try {
          const result = await window.electronAPI.startCopilotOAuth(connectionSlug)

          if (result.success) {
            await saveAndValidateConnection(connectionSlug, effectiveMethod, undefined, isReauth)
          } else {
            setState(s => ({
              ...s,
              credentialStatus: 'error',
              errorMessage: result.error || 'GitHub authentication failed',
            }))
          }
        } finally {
          cleanup()
          setCopilotDeviceCode(undefined)
        }
        return
      }

      // Pi SDK Unified OAuth (xAI, OpenRouter, Kimi, Radius)
      const piOAuthMethods = ['pi_xai_oauth', 'pi_openrouter_oauth', 'pi_kimi_oauth', 'pi_radius_oauth']
      if (piOAuthMethods.includes(effectiveMethod)) {
        const effectiveEditingSlug = connectionSlugOverride ?? editingSlug
        const isReauth = !!effectiveEditingSlug
        const connectionSlug = apiSetupMethodToConnectionSetup(effectiveMethod, {}, effectiveEditingSlug, existingSlugs).slug

        // Subscribe to device code events (used by xAI, Kimi device-code flows
        // and OpenRouter auth-URL / headless manual-code prompts)
        setPiOAuthSlug(connectionSlug)
        const cleanup = window.electronAPI.onCopilotDeviceCode((data) => {
          setCopilotDeviceCode(data)
        })

        try {
          const result = await window.electronAPI.startPiOAuth(connectionSlug)

          if (result.success) {
            await saveAndValidateConnection(connectionSlug, effectiveMethod, undefined, isReauth)
          } else {
            setState(s => ({
              ...s,
              credentialStatus: 'error',
              errorMessage: result.error || 'Authentication failed',
            }))
          }
        } finally {
          cleanup()
          setCopilotDeviceCode(undefined)
          setPiOAuthSlug(undefined)
        }
        return
      }

      // Claude OAuth (two-step flow - opens browser, user copies code)
      // Remaining method must be claude_oauth
      if (effectiveMethod !== 'claude_oauth') {
        setState(s => ({
          ...s,
          credentialStatus: 'error',
          errorMessage: 'This connection uses API keys, not OAuth.',
        }))
        return
      }

      const result = await window.electronAPI.startClaudeOAuth()

      if (result.success) {
        // Browser opened successfully, now waiting for user to copy the code
        setIsWaitingForCode(true)
        setState(s => ({ ...s, credentialStatus: 'idle' }))
      } else {
        setState(s => ({
          ...s,
          credentialStatus: 'error',
          errorMessage: result.error || 'Failed to start OAuth',
        }))
      }
    } catch (error) {
      setState(s => ({
        ...s,
        credentialStatus: 'error',
        errorMessage: error instanceof Error ? error.message : 'OAuth failed',
      }))
    }
  }, [state.apiSetupMethod, saveAndValidateConnection, editingSlug, existingSlugs])

  // Headless OAuth: forward a pasted authorization code / redirect URL to the
  // in-flight Pi OAuth flow (OpenRouter manual-code prompt).
  const handleSubmitPiOAuthCode = useCallback(async (code: string) => {
    if (!piOAuthSlug) return
    await window.electronAPI.submitPiOAuthCode(piOAuthSlug, code)
  }, [piOAuthSlug])

  // Map ProviderChoice → ApiSetupMethod and navigate to the right step
  const handleSelectProvider = useCallback((choice: ProviderChoice) => {
    const CHOICE_TO_METHOD: Record<Exclude<ProviderChoice, 'local'>, ApiSetupMethod> = {
      claude: 'claude_oauth',
      chatgpt: 'pi_chatgpt_oauth',
      copilot: 'pi_copilot_oauth',
      xai: 'pi_xai_oauth',
      openrouter: 'pi_openrouter_oauth',
      kimi: 'pi_kimi_oauth',
      radius: 'pi_radius_oauth',
      api_key: 'pi_api_key',
    }

    if (choice === 'local') {
      // Local uses anthropic_api_key with custom endpoint (Ollama doesn't need an API key)
      setState(s => ({ ...s, step: 'local-model', apiSetupMethod: 'anthropic_api_key', credentialStatus: 'idle', errorMessage: undefined }))
      return
    }

    const method = CHOICE_TO_METHOD[choice]
    setState(s => ({
      ...s,
      apiSetupMethod: method,
      step: 'credentials',
      credentialStatus: 'idle',
      errorMessage: undefined,
    }))

    // OAuth methods start immediately
    if (choice === 'claude' || choice === 'chatgpt' || choice === 'copilot' || choice === 'xai' || choice === 'openrouter' || choice === 'kimi' || choice === 'radius') {
      // Defer to next tick so state is updated before handleStartOAuth reads it
      setTimeout(() => handleStartOAuth(method), 0)
    }
  }, [handleStartOAuth])

  // Submit authorization code (second step of OAuth flow)
  const handleSubmitAuthCode = useCallback(async (code: string) => {
    if (!code.trim()) {
      setState(s => ({
        ...s,
        credentialStatus: 'error',
        errorMessage: 'Please enter the authorization code',
      }))
      return
    }

    setState(s => ({ ...s, credentialStatus: 'validating', errorMessage: undefined }))

    try {
      const connectionSlug = apiSetupMethodToConnectionSetup('claude_oauth', {}, editingSlug, existingSlugs).slug
      const result = await window.electronAPI.exchangeClaudeCode(code.trim(), connectionSlug)

      if (result.success && result.token) {
        setIsWaitingForCode(false)
        await saveAndValidateConnection(connectionSlug, 'claude_oauth', result.token, !!editingSlug, result.identity)
      } else {
        setState(s => ({
          ...s,
          credentialStatus: 'error',
          errorMessage: result.error || 'Failed to exchange code',
        }))
      }
    } catch (error) {
      setState(s => ({
        ...s,
        credentialStatus: 'error',
        errorMessage: error instanceof Error ? error.message : 'Failed to exchange code',
      }))
    }
  }, [saveAndValidateConnection, editingSlug, existingSlugs])

  // Submit local model configuration (Ollama or any OpenAI-compatible local server)
  const handleSubmitLocalModel = useCallback(async (data: LocalModelSubmitData) => {
    setState(s => ({ ...s, credentialStatus: 'validating', errorMessage: undefined }))

    try {
      // apiSetupMethod was set to 'anthropic_api_key' when entering local-model step
      const saved = await handleSaveConfig(undefined, {
        baseUrl: data.baseUrl,
        connectionDefaultModel: data.model,
        models: data.models,
        customEndpoint: { api: 'openai-completions' },
      })

      if (saved) {
        setState(s => ({ ...s, credentialStatus: 'success', step: 'complete' }))
      } else {
        setState(s => ({ ...s, credentialStatus: 'error' }))
      }
    } catch (error) {
      setState(s => ({
        ...s,
        credentialStatus: 'error',
        errorMessage: error instanceof Error ? error.message : 'Failed to save configuration',
      }))
    }
  }, [handleSaveConfig])

  // Cancel OAuth flow
  const handleCancelOAuth = useCallback(async () => {
    setIsWaitingForCode(false)
    setState(s => ({ ...s, credentialStatus: 'idle', errorMessage: undefined }))
    // Clear OAuth state on backend
    await window.electronAPI.clearClaudeOAuthState()
  }, [])

  // Git Bash handlers (Windows only)
  const handleBrowseGitBash = useCallback(async () => {
    return window.electronAPI.browseForGitBash()
  }, [])

  const handleUseGitBashPath = useCallback(async (path: string) => {
    const result = await window.electronAPI.setGitBashPath(path)
    if (result.success) {
      // Update state to mark Git Bash as found and continue
      setState(s => ({
        ...s,
        gitBashStatus: { ...s.gitBashStatus!, found: true, path },
        step: 'provider-select',
      }))
    } else {
      setState(s => ({
        ...s,
        errorMessage: result.error || 'Invalid path',
      }))
    }
  }, [])

  const handleRecheckGitBash = useCallback(async () => {
    setState(s => ({ ...s, isRecheckingGitBash: true }))
    try {
      const status = await window.electronAPI.checkGitBash()
      setState(s => ({
        ...s,
        gitBashStatus: status,
        isRecheckingGitBash: false,
        // If found, automatically continue to next step
        step: status.found ? 'provider-select' : s.step,
      }))
    } catch (error) {
      console.error('[Onboarding] Failed to recheck Git Bash:', error)
      setState(s => ({ ...s, isRecheckingGitBash: false }))
    }
  }, [])

  const handleClearError = useCallback(() => {
    setState(s => ({ ...s, errorMessage: undefined }))
  }, [])

  // Skip setup — user chose "Setup later"
  const handleSkipSetup = useCallback(async () => {
    try {
      await window.electronAPI.deferSetup()
    } catch (error) {
      console.error('[Onboarding] Failed to defer setup:', error)
    }
    onComplete()
  }, [onComplete])

  // Finish onboarding
  const handleFinish = useCallback(() => {
    onComplete()
  }, [onComplete])

  // Cancel onboarding
  const handleCancel = useCallback(() => {
    setState(s => ({ ...s, step: 'welcome' }))
  }, [])

  // Jump directly to credentials step with a pre-set method (for editing existing connections)
  const jumpToCredentials = useCallback((method: ApiSetupMethod) => {
    setState(s => ({
      ...s,
      step: 'credentials' as const,
      apiSetupMethod: method,
      credentialStatus: 'idle' as const,
      errorMessage: undefined,
    }))
  }, [])

  // Reset onboarding to initial state (used after logout or modal close)
  const reset = useCallback(() => {
    setState({
      step: initialStep,
      loginStatus: 'idle',
      credentialStatus: 'idle',
      completionStatus: 'saving',
      apiSetupMethod: initialApiSetupMethod ?? null,
      isExistingUser: false,
      errorMessage: undefined,
    })
    setIsWaitingForCode(false)
    // Clean up any pending OAuth state
    window.electronAPI.clearClaudeOAuthState().catch(() => {
      // Ignore errors - state may not exist
    })
  }, [initialStep, initialApiSetupMethod])

  return {
    state,
    handleContinue,
    handleBack,
    handleSelectProvider,
    handleSelectApiSetupMethod,
    handleSubmitCredential,
    handleSubmitLocalModel,
    handleStartOAuth,
    // Two-step OAuth flow
    isWaitingForCode,
    handleSubmitAuthCode,
    handleCancelOAuth,
    // Copilot device code
    copilotDeviceCode,
    // Headless Pi OAuth code submit
    handleSubmitPiOAuthCode,
    // Git Bash (Windows)
    handleBrowseGitBash,
    handleUseGitBashPath,
    handleRecheckGitBash,
    handleClearError,
    handleSkipSetup,
    handleFinish,
    handleCancel,
    jumpToCredentials,
    reset,
  }
}

import { useState, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import { RPC_CHANNELS } from '@phaneris/shared/protocol'
import { useTransportConnectionState } from './useTransportConnectionState'
import { toast } from 'sonner'

type ServerBrowserMode = 'browse' | 'manual'

interface DirectoryPickerResult {
  /** Open the picker (native dialog in local mode, ServerDirectoryBrowser in remote mode). */
  pickDirectory: () => void
  /** Whether the ServerDirectoryBrowser modal should be rendered. */
  showServerBrowser: boolean
  /** Which mode the ServerDirectoryBrowser should use. */
  serverBrowserMode: ServerBrowserMode
  /** Close the server browser without selecting. */
  cancelServerBrowser: () => void
  /** Called when a path is selected from the server browser. */
  confirmServerBrowser: (path: string) => void
  /** Whether we're in remote mode (informational). */
  isRemote: boolean
}

export function useDirectoryPicker(
  onSelect: (path: string) => void
): DirectoryPickerResult {
  const { t } = useTranslation()
  const connectionState = useTransportConnectionState()
  const isRemote = connectionState?.mode === 'remote'
  const canBrowse = isRemote &&
    window.electronAPI.isChannelAvailable(RPC_CHANNELS.fs.LIST_DIRECTORY)

  const [showServerBrowser, setShowServerBrowser] = useState(false)

  const serverBrowserMode: ServerBrowserMode = canBrowse ? 'browse' : 'manual'

  const pickDirectory = useCallback(async () => {
    if (isRemote) {
      // Remote mode — open ServerDirectoryBrowser (browse or manual depending on server support)
      setShowServerBrowser(true)
      return
    }

    // Local mode — native OS dialog
    try {
      const path = await window.electronAPI.openFolderDialog()
      if (path) onSelect(path)
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error'
      toast.error(t('toast.failedToOpenFolderPicker'), {
        description: message,
      })
    }
  }, [isRemote, onSelect])

  const cancelServerBrowser = useCallback(() => {
    setShowServerBrowser(false)
  }, [])

  const confirmServerBrowser = useCallback((path: string) => {
    setShowServerBrowser(false)
    onSelect(path)
  }, [onSelect])

  return {
    pickDirectory,
    showServerBrowser,
    serverBrowserMode,
    cancelServerBrowser,
    confirmServerBrowser,
    isRemote,
  }
}

/**
 * Update Checker Hook
 *
 * Manages auto-update state for the Electron app.
 * - Listens for update availability broadcasts from main process
 * - Tracks download progress
 * - Provides methods to check for updates and install
 * - Shows toast notification when update is ready
 * - Persistent dismissal across app restarts (per version)
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { useTranslation } from 'react-i18next'
import { toast } from 'sonner'
import type { UpdateInfo } from '../../shared/types'

interface UseUpdateCheckerResult {
  /** Current update info */
  updateInfo: UpdateInfo | null
  /** Whether an update is available */
  updateAvailable: boolean
  /** Whether update is currently downloading */
  isDownloading: boolean
  /** Whether update is ready to install */
  isReadyToInstall: boolean
  /**
   * Whether this build has an update feed at all. False means the check control
   * should not be offered — there is nowhere to check.
   */
  selfUpdateEnabled: boolean
  /** Download progress (0-100) */
  downloadProgress: number
  /** Check for updates manually */
  checkForUpdates: () => Promise<void>
  /** Install the downloaded update and restart */
  installUpdate: () => Promise<void>
}

// Toast ID for update notification (allows dismiss/update)
const UPDATE_TOAST_ID = 'update-available'

export function useUpdateChecker(): UseUpdateCheckerResult {
  const { t } = useTranslation()
  const [updateInfo, setUpdateInfo] = useState<UpdateInfo | null>(null)
  // Track if we've shown the toast for this version to avoid duplicates
  const shownToastVersionRef = useRef<string | null>(null)

  // Show toast notification when update is ready
  const showUpdateToast = useCallback((version: string, onInstall: () => void) => {
    // Don't show if already shown for this version in this session
    if (shownToastVersionRef.current === version) {
      return
    }
    shownToastVersionRef.current = version

    toast.info(t('toast.updateReady', { version }), {
      id: UPDATE_TOAST_ID,
      description: t('toast.restartToApply'),
      duration: 10000, // 10 seconds, then auto-dismiss
      action: {
        label: t('toast.restart'),
        onClick: onInstall,
      },
      onDismiss: () => {
        // Persist dismissal so we don't show again after app restart
        window.electronAPI.dismissUpdate(version)
      },
    })
  }, [t])

  // Install the update
  const installUpdate = useCallback(async () => {
    try {
      // Dismiss the update toast first
      toast.dismiss(UPDATE_TOAST_ID)
      toast.info(t('toast.installingUpdate'), {
        description: t('toast.appWillRestart'),
        duration: 5000,
      })
      await window.electronAPI.installUpdate()
    } catch (error) {
      console.error('[useUpdateChecker] Install failed:', error)
      toast.error(t('toast.failedToInstallUpdate'), {
        description: error instanceof Error ? error.message : 'Unknown error',
      })
    }
  }, [])

  // Load initial state and check if update ready
  useEffect(() => {
    const checkAndNotify = async (info: UpdateInfo) => {
      if (!info.available || !info.latestVersion) return
      if (info.downloadState !== 'ready') return

      // Check if this version was dismissed
      const dismissedVersion = await window.electronAPI.getDismissedUpdateVersion()
      if (dismissedVersion === info.latestVersion) {
        return
      }

      // Show toast for ready update
      showUpdateToast(info.latestVersion, installUpdate)
    }

    // Get initial update info
    window.electronAPI.getUpdateInfo().then((info) => {
      setUpdateInfo(info)
      checkAndNotify(info)
    })

    // Subscribe to update availability changes
    const cleanupAvailable = window.electronAPI.onUpdateAvailable((info) => {
      setUpdateInfo(info)
      checkAndNotify(info)
    })

    // Subscribe to download progress updates
    const cleanupProgress = window.electronAPI.onUpdateDownloadProgress((progress) => {
      setUpdateInfo((prev) => prev ? { ...prev, downloadProgress: progress } : prev)
    })

    return () => {
      cleanupAvailable()
      cleanupProgress()
    }
  }, [showUpdateToast, installUpdate])

  // Check for updates manually
  const checkForUpdates = useCallback(async () => {
    try {
      const info = await window.electronAPI.checkForUpdates()
      setUpdateInfo(info)

      // No feed configured: the main process returns the idle state without
      // asking anyone. Reporting that as "you are up to date" was false, so
      // stay quiet — the settings row and the menu item are hidden in this case.
      if (!info.selfUpdateEnabled) {
        return
      }

      if (!info.available) {
        toast.success(t('toast.upToDate'), {
          description: t('toast.versionIsLatest', { version: info.currentVersion }),
          duration: 3000,
        })
      } else if (info.downloadState === 'ready' && info.latestVersion) {
        // If already ready, show toast (clear any previous dismissal since user explicitly checked)
        shownToastVersionRef.current = null // Reset so toast can show again
        showUpdateToast(info.latestVersion, installUpdate)
      }
    } catch (error) {
      console.error('[useUpdateChecker] Check failed:', error)
      toast.error(t('toast.failedToCheckUpdates'), {
        description: error instanceof Error ? error.message : 'Unknown error',
      })
    }
  }, [showUpdateToast, installUpdate])

  return {
    updateInfo,
    updateAvailable: updateInfo?.available ?? false,
    isDownloading: updateInfo?.downloadState === 'downloading',
    isReadyToInstall: updateInfo?.downloadState === 'ready',
    selfUpdateEnabled: updateInfo?.selfUpdateEnabled ?? false,
    downloadProgress: updateInfo?.downloadProgress ?? 0,
    checkForUpdates,
    installUpdate,
  }
}

/**
 * useAutomations
 *
 * Encapsulates all automations state management:
 * - Loading automations from automations.json
 * - Subscribing to live updates
 * - Test, toggle, duplicate, delete handlers
 * - Delete confirmation state
 * - Syncing automations to Jotai atom for cross-component access
 */

import { useState, useCallback, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import { useSetAtom } from 'jotai'
import { toast } from 'sonner'
import { automationsAtom } from '@/atoms/automations'
import { parseAutomationsConfig, type AutomationListItem, type TestResult, type ExecutionEntry } from '@/components/automations/types'

async function loadAutomationsFromServer(workspaceId: string): Promise<AutomationListItem[]> {
  const json = await window.electronAPI.getAutomations(workspaceId)
  if (!json) return [] // No automations configured yet
  return parseAutomationsConfig(json)
}

export interface UseAutomationsResult {
  automations: AutomationListItem[]
  automationTestResults: Record<string, TestResult>
  automationPendingDelete: string | null
  pendingDeleteAutomation: AutomationListItem | undefined
  setAutomationPendingDelete: (id: string | null) => void
  handleTestAutomation: (automationId: string) => void
  handleToggleAutomation: (automationId: string) => void
  handleDuplicateAutomation: (automationId: string) => void
  handleDeleteAutomation: (automationId: string) => void
  confirmDeleteAutomation: () => void
  getAutomationHistory: (automationId: string) => Promise<ExecutionEntry[]>
  handleReplayAutomation: (automationId: string, event: string) => void
}

export function useAutomations(
  activeWorkspaceId: string | null | undefined,
): UseAutomationsResult {
  const { t } = useTranslation()
  const [automations, setAutomations] = useState<AutomationListItem[]>([])
  const [automationTestResults, setAutomationTestResults] = useState<Record<string, TestResult>>({})
  const [automationPendingDelete, setAutomationPendingDelete] = useState<string | null>(null)

  // Sync automations to Jotai atom for cross-component access (MainContentPanel)
  const setAutomationsAtom = useSetAtom(automationsAtom)
  useEffect(() => {
    setAutomationsAtom(automations)
  }, [automations, setAutomationsAtom])

  // Load automations from server and hydrate lastExecutedAt from history in one step.
  // This avoids the race where a config reload wipes timestamps before the
  // history effect can re-merge them.
  const loadAndHydrate = useCallback(async () => {
    if (!activeWorkspaceId) return
    try {
      const items = await loadAutomationsFromServer(activeWorkspaceId)
      try {
        const map = await window.electronAPI.getAutomationLastExecuted(activeWorkspaceId)
        for (const item of items) {
          item.lastExecutedAt = map[item.id] ?? item.lastExecutedAt
        }
      } catch { /* history unavailable — timestamps stay undefined */ }
      setAutomations(items)
    } catch {
      setAutomations([])
    }
  }, [activeWorkspaceId])

  // Initial load
  useEffect(() => {
    loadAndHydrate()
  }, [loadAndHydrate])

  // Subscribe to live automations updates (when automations.json changes on disk)
  useEffect(() => {
    if (!activeWorkspaceId) return
    const cleanup = window.electronAPI.onAutomationsChanged(() => { loadAndHydrate() })
    return () => { cleanup() }
  }, [activeWorkspaceId, loadAndHydrate])

  // Shared lookup — avoids repeating automations.find() in every callback
  const findAutomation = useCallback((id: string) => automations.find(h => h.id === id), [automations])

  // Test automation — aggregate all action results
  const handleTestAutomation = useCallback((automationId: string) => {
    const automation = findAutomation(automationId)
    if (!automation || !activeWorkspaceId) return

    setAutomationTestResults(prev => ({ ...prev, [automationId]: { state: 'running' } }))

    window.electronAPI.testAutomation({
      workspaceId: activeWorkspaceId,
      automationId: automation.id,
      automationName: automation.name,
      actions: automation.actions,
      permissionMode: automation.permissionMode,
      labels: automation.labels,
      telegramTopic: automation.telegramTopic,
    }).then((result) => {
      const actions = result.actions
      if (!actions || actions.length === 0) {
        setAutomationTestResults(prev => ({ ...prev, [automationId]: { state: 'error', stderr: 'No actions to execute' } }))
        return
      }
      const hasError = actions.some(a => !a.success)
      const state = hasError ? 'error' : 'success'
      const stderr = actions.map(a => ('stderr' in a ? a.stderr : 'error' in a ? a.error : undefined)).filter(Boolean).join('\n')
      const duration = actions.reduce((sum, a) => sum + (a.duration ?? 0), 0)
      setAutomationTestResults(prev => ({
        ...prev,
        [automationId]: {
          state,
          stderr: stderr || undefined,
          duration: duration || undefined,
        },
      }))
    }).catch((err: Error) => {
      setAutomationTestResults(prev => ({ ...prev, [automationId]: { state: 'error', stderr: err.message } }))
    })
  }, [findAutomation, activeWorkspaceId])

  const handleToggleAutomation = useCallback((automationId: string) => {
    const automation = findAutomation(automationId)
    if (!automation || !activeWorkspaceId) return
    window.electronAPI.setAutomationEnabled(
      activeWorkspaceId,
      automation.event,
      automation.matcherIndex,
      !automation.enabled,
    ).catch(() => {
      toast.error(t('toast.failedToToggleAutomation'))
    })
  }, [findAutomation, activeWorkspaceId])

  const handleDuplicateAutomation = useCallback((automationId: string) => {
    const automation = findAutomation(automationId)
    if (!automation || !activeWorkspaceId) return
    window.electronAPI.duplicateAutomation(activeWorkspaceId, automation.event, automation.matcherIndex)
      .catch(() => toast.error(t('toast.failedToDuplicateAutomation')))
  }, [findAutomation, activeWorkspaceId])

  // Delete: show confirmation dialog
  const handleDeleteAutomation = useCallback((automationId: string) => {
    setAutomationPendingDelete(automationId)
  }, [])

  const pendingDeleteAutomation = automationPendingDelete ? findAutomation(automationPendingDelete) : undefined

  const confirmDeleteAutomation = useCallback(() => {
    if (!pendingDeleteAutomation || !activeWorkspaceId) return
    window.electronAPI.deleteAutomation(activeWorkspaceId, pendingDeleteAutomation.event, pendingDeleteAutomation.matcherIndex)
      .catch(() => toast.error(t('toast.failedToDeleteAutomation')))
    setAutomationPendingDelete(null)
  }, [pendingDeleteAutomation, activeWorkspaceId])

  // Fetch execution history for a specific automation
  const getAutomationHistory = useCallback(async (automationId: string): Promise<ExecutionEntry[]> => {
    if (!activeWorkspaceId) return []
    try {
      const entries = await window.electronAPI.getAutomationHistory(activeWorkspaceId, automationId, 20)
      const automation = findAutomation(automationId)
      return entries.map(e => ({
        id: `${e.id}-${e.ts}`,
        automationId: e.id,
        event: automation?.event ?? 'LabelAdd',
        status: e.unsupported ? 'unsupported' as const : e.skipped ? 'skipped' as const : e.ok ? 'success' as const : 'error' as const,
        duration: e.webhook?.durationMs ?? 0,
        timestamp: e.ts,
        sessionId: e.sessionId,
        actionSummary: e.unsupported ? t('automations.unsupportedSummary') : e.skipped
          ? t('automations.skippedSummary', { reason: e.skipped })
          : e.webhook
          ? `Webhook ${e.webhook.method} ${e.webhook.url}${e.webhook.attempts && e.webhook.attempts > 1 ? ` (${e.webhook.attempts} attempts)` : ''}`
          : e.prompt,
        error: e.webhook?.error ?? e.error,
        webhookDetails: e.webhook ? {
          method: e.webhook.method,
          url: e.webhook.url,
          statusCode: e.webhook.statusCode,
          durationMs: e.webhook.durationMs,
          attempts: e.webhook.attempts,
          error: e.webhook.error,
          responseBody: e.webhook.responseBody,
        } : undefined,
      }))
    } catch {
      return []
    }
  }, [activeWorkspaceId, findAutomation])

  // Replay failed webhook actions for a specific automation
  const handleReplayAutomation = useCallback((automationId: string, event: string) => {
    if (!activeWorkspaceId) return
    window.electronAPI.replayAutomation(activeWorkspaceId, automationId, event)
      .then(() => {
        toast.success(t('toast.webhookReplayCompleted'))
      })
      .catch((err: Error) => {
        toast.error(t("toast.replayFailed", { error: err.message }))
      })
  }, [activeWorkspaceId])

  return {
    automations,
    automationTestResults,
    automationPendingDelete,
    pendingDeleteAutomation,
    setAutomationPendingDelete,
    handleTestAutomation,
    handleToggleAutomation,
    handleDuplicateAutomation,
    handleDeleteAutomation,
    confirmDeleteAutomation,
    getAutomationHistory,
    handleReplayAutomation,
  }
}

import { useEffect, useRef } from 'react'
import { useActionRegistry } from './registry'
import type { ActionId } from './definitions'

/**
 * Register a handler for an action.
 *
 * @example
 * useAction('app.newChat', () => handleNewChat())
 *
 * @example
 * // With enabled condition
 * useAction('navigator.selectAll', selectAll, {
 *   enabled: () => zoneRef.current?.contains(document.activeElement) ?? false
 * })
 */
export function useAction(
  actionId: ActionId,
  handler: () => void,
  options?: { enabled?: () => boolean },
  deps: unknown[] = []
) {
  const { register } = useActionRegistry()
  const handlerRef = useRef(handler)
  const optionsRef = useRef(options)

  // Keep refs current
  useEffect(() => {
    handlerRef.current = handler
    optionsRef.current = options
  }, [handler, options, ...deps])

  // Register handler
  useEffect(() => {
    return register({
      actionId,
      handler: () => handlerRef.current(),
      enabled: optionsRef.current?.enabled ? () => optionsRef.current?.enabled?.() ?? false : undefined,
    })
  }, [actionId, register])
}

/**
 * Centralized localStorage utility for the Electron renderer.
 * Provides type-safe access with consistent key prefixing.
 */

const PREFIX = 'craft-'

/**
 * All localStorage keys used in the app.
 * Centralized here to avoid magic strings and key collisions.
 */
export const KEYS = {
  // Chat sidebar
  sidebarVisible: 'sidebar-visible',
  /** Navigator (session list column) visibility — independent of the rail (decision #7) */
  navigatorVisible: 'navigator-visible',
  sidebarWidth: 'sidebar-width',
  sessionListWidth: 'session-list-width',
  sidebarMode: 'sidebar-mode',
  listFilter: 'list-filter',
  labelFilter: 'label-filter',
  viewFilters: 'view-filters', // Per-view filter map: { [viewKey]: { statuses, labels } }
  expandedFolders: 'expanded-folders',
  collapsedSidebarItems: 'collapsed-sidebar-items',
  chatGroupingMode: 'chat-grouping-mode', // How to group chats: 'date' | 'status'
  collapsedSessionFamilies: 'collapsed-session-families', // Parent session IDs, workspace-scoped
  collapsedSessionGroups: 'collapsed-session-groups', // Collapsed group keys in session list
  collapsedGanttItems: 'collapsed-gantt-items', // Collapsed work-item IDs, workspace/project-scoped
  calendarViewState: 'calendar-view-state', // Calendar mode + cursor date, workspace-scoped
  ganttScale: 'gantt-scale', // Gantt zoom preset, workspace-scoped
  ganttTaskColumnWidth: 'gantt-task-column-width', // Gantt task-list width the user dragged to, workspace-scoped

  // Focus mode
  focusModeEnabled: 'focus-mode-enabled',

  // Session files panel state
  sessionFilesExpandedFolders: 'session-files-expanded', // Expanded folders in session files tree (keyed by sessionId)

  // Theme
  theme: 'theme',

  // Panel layouts (dynamic key suffix)
  panelLayout: 'panel-layout', // Used as: panelLayout:${key}

  // Tabs (workspace-scoped)
  tabs: 'tabs', // Used as: tabs-${workspaceId}

  // Working directory
  recentWorkingDirs: 'recent-working-dirs',

  // TurnCard expansion state (persisted across session switches)
  turnCardExpansion: 'turncard-expansion',

  // Last selected session (workspace-scoped via suffix)
  lastSelectedSessionId: 'last-selected-session-id',

  // Settings navigation
  lastSettingsSubpage: 'last-settings-subpage',

  // Appearance
  showConnectionIcons: 'show-connection-icons',
  projectColorTreatment: 'project-color-treatment', // 'stripe' | 'stripe-tint'

  // What's New
  whatsNewLastSeenVersion: 'whats-new-last-seen-version',

  // Workspace navigation state (workspace-scoped via suffix = workspaceSlug)
  // Stores the full URL search string so switching back restores panels/focus/sidebar
  workspaceUrl: 'workspace-url',

  // Hidden (background) workbench panels (workspace-scoped via suffix = workspaceSlug)
  hiddenPanels: 'hidden-panels',
} as const

export type StorageKey = typeof KEYS[keyof typeof KEYS]

/**
 * Build the full prefixed key.
 * Supports dynamic suffixes like 'panel-layout:chat' or 'tabs-workspace123'
 */
function buildKey(key: string, suffix?: string): string {
  const base = `${PREFIX}${key}`
  return suffix ? `${base}:${suffix}` : base
}

/**
 * Get a value from localStorage with JSON parsing.
 * Returns fallback if key doesn't exist or parsing fails.
 */
export function get<T>(key: StorageKey, fallback: T, suffix?: string): T {
  try {
    const item = localStorage.getItem(buildKey(key, suffix))
    if (item === null) return fallback
    return JSON.parse(item) as T
  } catch {
    return fallback
  }
}

/**
 * Set a value in localStorage with JSON stringification.
 */
export function set<T>(key: StorageKey, value: T, suffix?: string): void {
  try {
    localStorage.setItem(buildKey(key, suffix), JSON.stringify(value))
  } catch (error) {
    console.warn(`[localStorage] Failed to set ${key}:`, error)
  }
}

/**
 * Remove a key from localStorage.
 */
export function remove(key: StorageKey, suffix?: string): void {
  localStorage.removeItem(buildKey(key, suffix))
}

/**
 * Get raw string value (for non-JSON data like atomWithStorage compatibility).
 */
export function getRaw(key: StorageKey, suffix?: string): string | null {
  return localStorage.getItem(buildKey(key, suffix))
}

/**
 * Set raw string value (for non-JSON data like atomWithStorage compatibility).
 */
export function setRaw(key: StorageKey, value: string, suffix?: string): void {
  localStorage.setItem(buildKey(key, suffix), value)
}

/**
 * Build a full key string for use with atomWithStorage or other APIs
 * that need the raw key string.
 */
export function getKeyString(key: StorageKey, suffix?: string): string {
  return buildKey(key, suffix)
}

